Object.assign(window.TEM8_DICTIONARY, {"creeping":{"media":{"uk":"media/uk/creeping__gb_1.mp3","us":"media/us/creeping__us_1.mp3"},"oxford":{"phon":"ˈkriːpɪŋ","pos":"adjective","senses":[{"en":"happening or moving gradually and not easily noticed","cn":"（不知不觉地）逐渐发生的，缓慢行进的","ex":{"en":"creeping inflation","cn":"慢慢加剧的通货膨胀"}}]},"examples":[{"en":"creeping inflation","cn":"慢慢加剧的通货膨胀"}],"base":"creep"},"crown":{"media":{"uk":"media/uk/crown__gb_1.mp3","us":"media/us/crown__us_1.mp3","img":["media/ldoce/img/crown.jpg"]},"oxford":{"phon":"kraʊn","pos":"noun","senses":[{"en":"an object in the shape of a circle, usually made of gold and precious stones, that a king or queen wears on his or her head on official occasions","cn":"王冠；皇冠；冕","g":"[countable]","sc":"of king/queen","ex":{"en":"The crown was placed upon the new monarch's head.","cn":"王冠戴在了新君主的头上。"}},{"en":"the government of a country, thought of as being represented by a king or queen","cn":"王国政府；王国","g":"[singular]","sc":"of king/queen","ex":{"en":"land owned by the Crown","cn":"王国的土地"}},{"en":"the position or power of a king or queen","cn":"王位；王权","g":"[singular]","sc":"of king/queen","ex":{"en":"She refused the crown (= refused to become queen).","cn":"她拒绝接受王位。"}},{"en":"a circle of flowers, leaves, etc. that is worn on somebody’s head, sometimes as a sign of victory","cn":"花冠（戴在头上，有时象征胜利）","g":"[countable]","sc":"of flowers/leaves"},{"en":"the position of winning a sports competition","cn":"冠军宝座；桂冠","g":"[countable, usually singular]","lab":"informal","sc":"in sports competition","ex":{"en":"She is determined to retain her Wimbledon crown.","cn":"她决心在温布尔登网球赛上卫冕。"}},{"en":"the top part of the head or a hat","cn":"头顶；帽顶","g":"[singular]","sc":"of head/hat","ex":{"en":"There were raindrops on his bald crown.","cn":"他的秃顶上有雨滴。"}},{"en":"the highest part of something","cn":"（某物的）顶部，顶端","g":"[singular]","sc":"highest part","ex":{"en":"the crown of a hill","cn":"山顶"}},{"en":"the part of a plant just above and below the ground","cn":"根颈（植物的茎与根连接的部分）","g":"[countable]","sc":"of a plant","ex":{"en":"Roses bloom on shoots that sprout from the crown of the mother plant.","cn":"玫瑰在从母株的树冠发芽的芽上开花。"}},{"en":"the top of a tree or other plant","cn":"树冠；冠（树或其他植物的顶部）","g":"[countable]","sc":"of a plant","ex":{"en":"Nests were built high in the crowns of trees.","cn":"巢建在高高的树冠上。"}},{"en":"an artificial cover for a damaged tooth","cn":"（受损牙齿的）人造冠","g":"[countable]"},{"en":"the part of the tooth that is above the gum","cn":"（受损牙齿的）人造冠","g":"[countable]"},{"en":"anything in the shape of a crown, especially as a decoration or a badge","cn":"王冠状物（尤指饰物或徽章）","g":"[countable]","sc":"shape"},{"en":"a unit of money in several European countries","cn":"克朗（欧洲一些国家的货币单位）","g":"[countable]","sc":"money","ex":{"en":"Czech crowns","cn":"捷克克朗"}},{"en":"an old British coin worth five shillings (= now 25p)","cn":"5 先令的英国旧币（等于现在的 25 便士）","g":"[countable]","sc":"money"},{"en":"to put a crown on the head of a new king or queen as a sign of royal power in a ceremony at which they officially become king or queen","cn":"为（新任君王）加冕","g":"[often passive]","sc":"king/queen","ex":{"en":"Queen Elizabeth was crowned in 1953.","cn":"伊丽莎白女王于 1953 年加冕。"},"pos":"verb"},{"en":"to form or cover the top of something","cn":"形成…顶部；给…加顶","g":"[usually passive]","sc":"cover top","ex":{"en":"His head was crowned with a mop of brown curls.","cn":"他长了一头蓬乱的棕色鬈发。"},"pos":"verb"},{"en":"to make something complete or perfect, especially by adding an achievement, a success, etc.","cn":"（尤指通过增添成就、成功等）使圆满，使完美","g":"[often passive]","sc":"make complete","ex":{"en":"The award of the Nobel Prize has crowned a glorious career in physics.","cn":"荣获诺贝尔奖使其物理学研究的辉煌事业达到了顶点。"},"pos":"verb"},{"en":"to hit somebody on the head","cn":"敲（某人）的脑壳","lab":"old-fashioned, informal，，","sc":"hit on head","pos":"verb"},{"en":"to put an artificial cover on a tooth","cn":"（在牙齿上）镶人造冠","g":"[often passive]","sc":"tooth","ex":{"en":"I've had one of my teeth crowned.","cn":"我的一颗牙齿镶了假齿冠。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"王冠;皇冠;冕;(戴在头上的)冠状物","en":"A crown is a circular ornament, usually made of gold and jewels, which a king or queen wears on their head at official ceremonies. You can also use crown to refer to anything circular that is worn on someone's head.","ex":{"en":"...a crown of flowers.","cn":"花冠"}},{"pos":"N-PROPER 专有名词","cn":"王国政府;王国;(英国刑事案件中的)公诉人","en":"The government of a country that has a king or queen is sometimes referred to as the Crown. In British criminal cases the prosecutor is the Crown .","ex":{"en":"She says the sovereignty of the Crown must be preserved.","cn":"她说必须维护王国政府的主权。"}},{"pos":"VERB 动词","cn":"为…加冕;立…为王(或女王)","en":"When a king or queen is crowned, a crown is placed on their head as part of a ceremony in which they are officially made king or queen.","ex":{"en":"Elizabeth was crowned in Westminster Abbey on 2 June 1953","cn":"伊丽莎白于1953年6月2日在威斯敏斯特大教堂加冕。"}},{"pos":"VERB 动词","cn":"形成…的顶部;给…加顶","en":"If one thing crowns another, it is on top of it.","ex":{"en":"Here another rugged castle crowns the cliffs and crags.","cn":"这里又有一座高低不平的城堡建在悬崖绝壁之上。"}},{"pos":"N-COUNT 可数名词","cn":"头顶(后部)","en":"Your crown is the top part of your head, at the back.","ex":{"en":"He laid his hand gently on the crown of her head.","cn":"他把手轻轻放在她的头顶上。"}},{"pos":"N-COUNT 可数名词","cn":"帽顶","en":"The crown of a hat is the part which covers the top of your head."},{"pos":"N-COUNT 可数名词","cn":"5先令的英国硬币","en":"A crown was a British coin worth five shillings."},{"pos":"N-COUNT 可数名词","cn":"(受损牙齿的)人造冠","en":"A crown is an artificial top piece fixed over a broken or decayed tooth."},{"pos":"N-COUNT 可数名词","cn":"冠军宝座;桂冠","en":"In sport, winning an important competition is sometimes referred to as a crown .","ex":{"en":"...his dream of a fourth Wimbledon crown.","cn":"他梦想第四次获得温布尔登网球公开赛的冠军"}},{"pos":"VERB 动词","cn":"使圆满;使完美","en":"An achievement or event that crowns something makes it perfect, successful, or complete.","ex":{"en":"It is an important moment, crowning the efforts of the Cup organisers","cn":"这是个重要时刻，它使得优胜杯赛组织者的努力圆满告捷。"}},{"pos":"VERB 动词","cn":"使(事业)达到顶峰","en":"If you crown your career with a success or achievement, you have a final success or achievement which is greater than all the others you have had.","ex":{"en":"He went on to crown a distinguished career in radio and television with his book 'The Price of Victory'.","cn":"凭借《胜利的代价》一书，在广播和电视事业上成就杰出的他再创辉煌。"}}]},"examples":[{"en":"The award of the Nobel Prize has crowned a glorious career in physics.","cn":"荣获诺贝尔奖使其物理学研究的辉煌事业达到了顶点。"},{"en":"It was cold and raining, and, to crown it all, we had to walk home.","cn":"天气寒冷又下着雨，最糟的是我们得走着回家。"}]},"crowded":{"media":{"uk":"media/uk/crowded__gb_1.mp3","us":"media/us/crowded__us_1.mp3"},"oxford":{"phon":"ˈkraʊdɪd","pos":"adjective","senses":[{"en":"having a lot of people or too many people","cn":"人（太）多的；拥挤的","ex":{"en":"We made our way through the crowded streets.","cn":"我们在拥挤的街道上艰难地前行。"}},{"en":"full of something","cn":"充满的；挤满的","ex":{"en":"a room crowded with books","cn":"堆满书籍的房间"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"人多的;拥挤的","en":"If a place is crowded, it is full of people.","ex":{"en":"He peered slowly around the small crowded room","cn":"他慢慢地环视这个拥挤的小屋。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"拥挤的;住有很多人的","en":"If a place is crowded, a lot of people live there.","ex":{"en":"...a crowded city of 2 million","cn":"有200万人口的拥挤的城市"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"排满的;占满的","en":"If your timetable, your life, or your mind is crowded, it is full of events, activities, or thoughts.","ex":{"en":"Never before has a summit had such a crowded agenda.","cn":"以前从来没有一次峰会的日程排得这么满。"}}]},"examples":[{"en":"In the spring the place is crowded with skiers.","cn":"春季这地方满是滑雪的人。"},{"en":"We have a very crowded schedule.","cn":"我们的日程排得满满的。"}],"base":"crowd"},"crush":{"oxford":{"phon":"krʌʃ","pos":"verb","senses":[{"en":"to press something so hard that it is damaged or injured, or loses its shape","cn":"压坏；压伤；挤压变形","g":"[transitive]","ex":{"en":"The car was completely crushed under the truck.","cn":"小轿车被卡车压得完全变形了。"}},{"en":"to break something into small pieces or into a powder by pressing hard","cn":"压碎；捣碎；碾成粉末","g":"[transitive]","ex":{"en":"Add two cloves of crushed garlic.","cn":"加入两瓣捣碎的蒜。"}},{"en":"to push or press somebody/something into a small space","cn":"把…挤入，将…塞进（狭小的空间内）","g":"[transitive]","ex":{"en":"Over twenty prisoners were crushed into a small dark cell.","cn":"二十多名囚犯被塞在一间黑暗狭小的牢房里。"}},{"en":"to make something full of folds or lines; to become full of folds or lines","cn":"弄皱；起皱","g":"[transitive, intransitive]","ex":{"en":"She crushed the scrap of paper in her hand.","cn":"她把手里的纸片揉得皱皱巴巴。"}},{"en":"to use violent methods to defeat people who are opposing you","cn":"镇压；（用暴力）制伏","g":"[transitive]","ex":{"en":"The army was sent in to crush the rebellion.","cn":"军队被派去平息叛乱。"}},{"en":"to destroy somebody’s confidence or happiness","cn":"破坏，毁坏（某人的信心或幸福）","ex":{"en":"She felt completely crushed by the teacher's criticism.","cn":"老师的批评使她觉得自己一无是处。"}},{"en":"a crowd of people pressed close together in a small space","cn":"（狭小空间中）拥挤的人群","g":"[countable, usually singular]","ex":{"en":"There was a big crush in the theatre bar.","cn":"剧院酒吧里挤满了人。"},"pos":"noun"},{"en":"a strong feeling of love, which usually does not last very long, that a young person has for another person, often older; the person who is the object of this feeling","cn":"（通常指年轻人对年长者的短暂的）热恋，迷恋","g":"[countable]","ex":{"en":"It's only a schoolgirl crush, it'll pass.","cn":"这不过是女学生的一时迷恋而已，会过去的。"},"pos":"noun"},{"en":"a drink made from fruit juice","cn":"果汁饮料","g":"[uncountable, countable]","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"压坏;压碎;挤压变形","en":"To crush something means to press it very hard so that its shape is destroyed or so that it breaks into pieces.","ex":{"en":"Andrew crushed his empty can","cn":"安德鲁把他的空罐子捏扁了。"}},{"pos":"VERB 动词","cn":"(常指通过武力)制服，镇压，彻底击败","en":"To crush a protest or movement, or a group of opponents, means to defeat it completely, usually by force.","ex":{"en":"The military operation was the first step in a plan to crush the uprising.","cn":"军事行动是镇压暴动计划的第一步。"}},{"pos":"VERB 动词","cn":"使心烦意乱;使消沉","en":"If you are crushed by something, it upsets you a great deal.","ex":{"en":"Listen to criticism but don't be crushed by it.","cn":"听取批评意见，但不要被它击垮。"}},{"pos":"VERB 动词","cn":"推;压;挤","en":"If you are crushed against someone or something, you are pushed or pressed against them.","ex":{"en":"We were at the front, crushed against the stage.","cn":"我们在前面，被挤到了舞台边上。"}},{"pos":"N-COUNT 可数名词","cn":"拥挤的人群","en":"A crush is a crowd of people close together, in which it is difficult to move.","ex":{"en":"Franklin and his thirteen-year-old son somehow got separated in the crush","cn":"富兰克林和他13岁的儿子在人群中被挤散了。"}},{"pos":"N-COUNT 可数名词","cn":"(对…的)迷恋;(对…的)爱慕","en":"If you have a crush on someone, you are in love with them but do not have a relationship with them.","ex":{"en":"She had a crush on you, you know","cn":"她曾爱慕你，你是知道的。"}}]},"media":{"img":["media/pic/squeeze_comp.jpg","media/thumb/crush.jpg"],"uk":"media/uk/crush__gb_1.mp3","us":"media/us/crush__us_1.mp3"},"examples":[{"en":"Over twenty prisoners were crushed into a small dark cell.","cn":"二十多名囚犯被塞在一间黑暗狭小的牢房里。"},{"en":"They crush the olives with a heavy wooden press.","cn":"他们用沉重的木制压榨机把橄榄压碎。"}]},"crescent":{"media":{"uk":"media/uk/crescent__gb_1.mp3","us":"media/us/crescent__us_1.mp3"},"oxford":{"phon":"ˈkresnt","pos":"noun","senses":[{"en":"a curved shape that is wide in the middle and pointed at each end","cn":"新月形；月牙形","g":"[countable]","ex":{"en":"a crescent moon","cn":"新月"}},{"en":"a curved street with a row of houses on it","cn":"新月形街区（一排房屋）","g":"[countable]","ex":{"en":"I live at 7 Park Crescent.","cn":"我住在帕克新月街 7 号。"}},{"en":"the curved shape that is used as a symbol of Islam","cn":"新月（伊斯兰教的象征）","g":"[singular]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"新月形，月牙形(伊斯兰教最重要的象征)","en":"A crescent is a curved shape that is wider in the middle than at its ends, like the shape of the moon during its first and last quarters. It is the most important symbol of the Islamic faith.","ex":{"en":"A glittering Islamic crescent tops the mosque.","cn":"新月形标志在清真寺顶端闪闪发光。"}},{"pos":"N-IN-NAMES 名称名词","cn":"(常用于街道或一排房子的名称中)新月形街区","en":"Crescent is sometimes used as part of the name of a street or row of houses that is usually built in a curve.","ex":{"en":"...44 Colville Crescent.","cn":"科尔维尔新月街44号"}}]},"examples":[{"en":"I live at 7 Park Crescent.","cn":"我住在帕克新月街 7 号。"},{"en":"a crescent moon","cn":"新月"}]},"crafted":{"lemma":"craft"},"craze":{"oxford":{"phon":"kreɪz","pos":"noun","senses":[{"en":"an enthusiastic interest in something that is shared by many people but that usually does not last very long; a thing that people have a craze for","cn":"（通常为一时的）狂热，疯狂；风行一时的东西","ex":{"en":"the latest fitness craze to sweep the country","cn":"最近风靡全国的健身热"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(一时的)狂热，风行","en":"If there is a craze for something, it is very popular for a short time.","ex":{"en":"...the craze for Mutant Ninja Turtles","cn":"《忍者神龟》的风靡一时"}}]},"media":{"uk":"media/uk/craze__gb_1.mp3","us":"media/us/craze__us_1.mp3"},"examples":[{"en":"the latest fitness craze to sweep the country","cn":"最近风靡全国的健身热"}]},"creative":{"media":{"uk":"media/uk/creative__gb_1.mp3","us":"media/us/creative__us_1.mp3"},"oxford":{"phon":"kriˈeɪtɪv","pos":"adjective","senses":[{"en":"involving the use of skill and the imagination to produce something new or a work of art","cn":"创造（性）的；创作的","g":"[only before noun]","lab":"informal","ex":{"en":"a course on creative writing (= writing stories, plays and poems)","cn":"创意写作课程"}},{"en":"having the skill and ability to produce something new, especially a work of art; showing this ability","cn":"有创造力的；（尤指艺术作品）创作的；表现创造力的","ex":{"en":"She's very creative—she writes poetry and paints.","cn":"她极富创造力，既赋诗又作画。"}},{"en":"a person whose job involves creative work","cn":"搞创作的人；创意工作者","g":"[countable]","ex":{"en":"The exhibition features the paintings of local creatives.","cn":"这个展览会展出的是当地画家的作品。"},"pos":"noun"},{"en":"creative ideas or material","cn":"创意；创作素材","g":"[uncountable]","ex":{"en":"We need to produce better creative if we want to attract big clients.","cn":"要吸引大客户，我们就得拿出更好的创意。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指在艺术方面)有创造力的，有想象力的","en":"A creative person has the ability to invent and develop original ideas, especially in the arts.","ex":{"en":"Like so many creative people he was never satisfied.","cn":"像许多富于创造力的人一样，他从不满足。"}},{"pos":"ADJ 形容词","cn":"创造(性)的;创作的","en":"Creative activities involve the inventing and making of new kinds of things.","ex":{"en":"...creative writing","cn":"创造性写作"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"创新的;富有创意的","en":"If you use something in a creative way, you use it in a new way that produces interesting and unusual results.","ex":{"en":"...his creative use of words.","cn":"他对词语的创造性运用"}},{"pos":"N-COUNT 可数名词","cn":"(尤指广告)创意人员，创作者","en":"A creative is someone whose job is to be creative, especially someone who creates advertisements.","ex":{"en":"Along with scores of other advertising creatives, he will be taking part in an exhibition at the Saatchi gallery.","cn":"他将和许多广告创意人员一起参加在萨奇画廊举行的画展。"}}]},"examples":[{"en":"We need to produce better creative if we want to attract big clients.","cn":"要吸引大客户，我们就得拿出更好的创意。"},{"en":"The exhibition features the paintings of local creatives.","cn":"这个展览会展出的是当地画家的作品。"}]},"cradle":{"media":{"img":["media/pic/beds_comp.jpg","media/thumb/cradle.jpg"],"uk":"media/uk/cradle__gb_1.mp3","us":"media/us/cradle__us_1.mp3"},"oxford":{"phon":"ˈkreɪdl","pos":"noun","senses":[{"en":"a small bed for a baby that can be pushed gently from side to side","cn":"摇篮","ex":{"en":"She rocked the baby to sleep in its cradle.","cn":"她摇动摇篮哄婴儿入睡。"}},{"en":"the place where something important began","cn":"策源地；发源地；发祥地","g":"[usually singular]","ex":{"en":"Greece, the cradle of Western civilization","cn":"希腊，西方文明的摇篮"}},{"en":"a small platform that can be moved up and down the outside of a high building, used by people cleaning windows, etc.","cn":"（高楼外供清洁窗户等用的）吊架，托架，吊篮","lab":"British English"},{"en":"the part of a phone on which the handset rests","cn":"（电话机的）听筒架，叉托支架"},{"en":"to hold somebody/something gently in your arms or hands","cn":"轻轻抱着","ex":{"en":"The old man cradled the tiny baby in his arms.","cn":"老汉把幼小的婴儿轻轻抱在怀里。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"摇篮","en":"A cradle is a baby's bed with high sides. Cradles often have curved bases so that they rock from side to side."},{"pos":"N-COUNT 可数名词","cn":"(电话机的)听筒架","en":"The cradle is the part of a telephone on which the receiver rests while it is not being used.","ex":{"en":"I dropped the receiver back in the cradle.","cn":"我把听筒放回听筒架上。"}},{"pos":"N-COUNT 可数名词","cn":"支架;护架","en":"A cradle is a frame which supports or protects something.","ex":{"en":"He fixed the towing cradle round the hull.","cn":"他把牵引支架固定在船体上。"}},{"pos":"N-COUNT 可数名词","cn":"发源地;发祥地","en":"A place that is referred to as the cradle of something is the place where it began.","ex":{"en":"Mali is the cradle of some of Africa's richest civilizations.","cn":"马里是非洲一些最悠久的文明的发祥地。"}},{"pos":"VERB 动词","cn":"轻轻抱着(或捧着)","en":"If you cradle someone or something in your arms or hands, you hold them carefully and gently.","ex":{"en":"I cradled her in my arms","cn":"我把她轻轻地抱在怀里。"}},{"pos":"PHRASE 短语","cn":"一生;一世;从生到死","en":"If something affects you from the cradle to the grave, it affects you throughout your life.","ex":{"en":"The bond of brotherhood was one to last from the cradle to the grave.","cn":"兄弟之情会延续一辈子。"}}]},"examples":[{"en":"The old man cradled the tiny baby in his arms.","cn":"老汉把幼小的婴儿轻轻抱在怀里。"},{"en":"She rocked the baby to sleep in its cradle.","cn":"她摇动摇篮哄婴儿入睡。"}]},"crate":{"media":{"uk":"media/uk/crate__gb_1.mp3","us":"media/us/crate__us_1.mp3","img":["media/ldoce/img/crate.jpg"]},"oxford":{"phon":"kreɪt","pos":"noun","senses":[{"en":"a large wooden container for transporting goods","cn":"大木箱，板条箱（运货用）","ex":{"en":"The spider was found hiding in a crate of bananas.","cn":"发现蜘蛛藏在一只装着香蕉的箱子里。"}},{"en":"a container made of plastic or metal divided into small sections, for transporting or storing bottles","cn":"塑料分格箱，金属分格箱（运送或存放瓶子用）","ex":{"en":"An old man was sitting on an upturned beer crate.","cn":"一个老人坐在一只倒放的啤酒箱上。"}},{"en":"the amount of something contained in a crate","cn":"一箱（的量）","ex":{"en":"They drank two crates of beer.","cn":"他们喝了两箱啤酒。"}},{"en":"to pack something in a crate","cn":"把…装入大木箱（或板条箱、分格箱）","ex":{"en":"Any extra parts will have to be crated and shipped separately.","cn":"任何额外的部件都必须单独装箱和运输。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(运输或储藏物品的)板条箱，大木箱","en":"A crate is a large box used for transporting or storing things.","ex":{"en":"...a pile of wooden crates","cn":"一堆大木箱"}},{"pos":"VERB 动词","cn":"把…装进木箱(或板条箱)","en":"If something is crated, it is packed in a crate so that it can be transported or stored somewhere safely.","ex":{"en":"The much repaired plane was crated for the return journey.","cn":"经过大修的刨子被装入木箱运回去。"}},{"pos":"N-COUNT 可数名词","cn":"(运送瓶子用的)塑料分格箱，金属分隔箱","en":"A crate is a plastic or wire box divided into sections which is used for carrying bottles.","ex":{"en":"We've also got a bonus quiz with crates of beer as prizes!","cn":"我们还获得了一次参加有奖智力竞赛的机会，奖品是成箱的啤酒！"}}]},"examples":[{"en":"They drank two crates of beer.","cn":"他们喝了两箱啤酒。"},{"en":"a crate of bananas","cn":"一箱香蕉"}]},"crack":{"oxford":{"phon":"kræk","pos":"verb","senses":[{"en":"to break without dividing into separate parts; to break something in this way","cn":"破裂；裂开；断裂","g":"[intransitive, transitive]","sc":"break","ex":{"en":"The ice cracked as I stepped onto it.","cn":"我一踩冰就裂了。"}},{"en":"to break open or into pieces; to break something in this way","cn":"砸开；破开；砸碎；打碎","g":"[intransitive, transitive]","lab":"figurative","sc":"break","ex":{"en":"A chunk of the cliff had cracked off in a storm.","cn":"悬崖上的一块石头在暴风雨中崩塌下来。"}},{"en":"to hit something/somebody in a short hard manner","cn":"重击；猛击","g":"[transitive]","sc":"hit","ex":{"en":"I cracked my head on the low ceiling.","cn":"我的头撞上了低矮的天花板。"}},{"en":"to make a sharp sound; to make something do this","cn":"（使）发出爆裂声，噼啪作响","g":"[intransitive, transitive]","sc":"make sound","ex":{"en":"A shot cracked across the ridge.","cn":"一颗炮弹飞过山脊爆炸了。"}},{"en":"if your voice cracks, it changes in depth, volume, etc. suddenly and in a way that you cannot control","cn":"（突然）变嘶哑，变沙哑","g":"[intransitive]","sc":"of voice","ex":{"en":"In a voice cracking with emotion, he told us of his son's death.","cn":"他悲恸失声地告诉我们他儿子去世的消息。"}},{"en":"to no longer be able to function normally because of pressure","cn":"（因压力而）吃不消，崩溃，瓦解","g":"[intransitive]","sc":"under pressure","ex":{"en":"Things are terrible at work and people are cracking under the strain.","cn":"工作情况很糟糕，人们因过度紧张越来越吃不消了。"}},{"en":"to find the solution to a problem, etc; to find the way to do something difficult","cn":"找到解决（难题等的）方法","g":"[transitive]","lab":"informal","sc":"find solution","ex":{"en":"to crack the enemy’s code","cn":"破译敌人的密码"}},{"en":"to find a way of stopping or defeating a criminal or an enemy","cn":"阻止，打击，击败，战胜（罪犯或敌人）","g":"[transitive]","sc":"stop somebody/something","ex":{"en":"Police have cracked a major drugs ring.","cn":"警方破获了一个大贩毒集团。"}},{"en":"to open a bottle, especially of wine, and drink it","cn":"开瓶；（尤指）开瓶饮酒","g":"[transitive]","lab":"informal","sc":"open bottle"},{"en":"to tell a joke","cn":"说（笑话）；开（玩笑）","g":"[transitive]","lab":"informal","sc":"a joke"},{"en":"a line on the surface of something where it has broken but not split into separate parts","cn":"裂纹；裂缝","g":"[countable]","lab":"figurative","sc":"break","ex":{"en":"This cup has a crack in it.","cn":"这杯子有一道裂痕。"},"pos":"noun"},{"en":"a narrow space or opening","cn":"缝隙；狭缝；窄缝","g":"[countable]","sc":"narrow opening","ex":{"en":"She peeped through the crack in the curtains.","cn":"她透过窗帘的缝隙窥视。"},"pos":"noun"},{"en":"a sudden loud noise","cn":"（突然的）爆裂声，噼啪声","g":"[countable]","sc":"sound","ex":{"en":"There was a deafening crack of thunder and the heavens opened.","cn":"一声震耳欲聋的雷声响起，天开了。"},"pos":"noun"},{"en":"a sharp, hard hit that can be heard","cn":"（可听到响声的）重击，猛击","g":"[countable]","sc":"hit","ex":{"en":"She fell over and got a nasty crack on the head.","cn":"她跌倒了，脑袋重重地磕了一下。"},"pos":"noun"},{"en":"an occasion when you try to do something","cn":"尝试；试做","g":"[countable]","lab":"informal","sc":"attempt","ex":{"en":"She hopes to have another crack at the world record this year.","cn":"她希望今年再一次冲击世界纪录。"},"pos":"noun"},{"en":"a powerful, illegal drug that is a form of cocaine","cn":"强效可卡因","g":"[uncountable]","sc":"drug","ex":{"en":"a crack addict","cn":"吸强效可卡因成瘾的人"},"pos":"noun"},{"en":"a joke, especially a critical one","cn":"（尤指挖苦人的）玩笑，俏皮话","g":"[countable]","lab":"informal","sc":"joke","ex":{"en":"He made a very unfair crack about her looks.","cn":"他开玩笑地损了一下她的长相，言语很是刻薄。"},"pos":"noun"},{"en":"a good time; friendly, lively talk","cn":"好时光；友好愉快的交谈","g":"[uncountable, singular]","lab":"Irish English, informal，，","sc":"conversation","ex":{"en":"Where's the crack tonight?","cn":"今晚去哪里逍遥？"},"pos":"noun"},{"en":"expert and highly trained; excellent at something","cn":"训练有素的；技艺高超的；优秀的；一流的","ex":{"en":"crack troops","cn":"精锐部队"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)破裂;(使)裂开;(使)断裂","en":"If something hard cracks, or if you crack it, it becomes slightly damaged, with lines appearing on its surface.","ex":{"en":"A gas main had cracked under my neighbour's garage and gas had seeped into our homes","cn":"邻居车库下面的煤气总管裂开了，煤气渗入了我们家。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)发出爆裂声;(使)噼啪作响","en":"If something cracks, or if you crack it, it makes a sharp sound like the sound of a piece of wood breaking.","ex":{"en":"Thunder cracked in the sky","cn":"空中雷声咔嚓作响。"}},{"pos":"VERB 动词","cn":"重击;猛击","en":"If you crack a hard part of your body, such as your knee or your head, you hurt it by accidentally hitting it hard against something.","ex":{"en":"He cracked his head on the pavement and was knocked cold.","cn":"他一头撞到人行道上，不省人事了。"}},{"pos":"VERB 动词","cn":"打破;砸开;砸碎","en":"When you crack something that has a shell, such as an egg or a nut, you break the shell in order to reach the inside part.","ex":{"en":"Crack the eggs into a bowl.","cn":"把鸡蛋打在一个碗中。"}},{"pos":"VERB 动词","cn":"(尤指经过反复思考)找到…的解决办法，破译(密码)","en":"If you crack a problem or a code, you solve it, especially after a lot of thought.","ex":{"en":"He has finally cracked the system after years of painstaking research.","cn":"经过多年的努力研究，他终于找到了破解这个系统的办法。"}},{"pos":"VERB 动词","cn":"(因压力大而)失控，崩溃，瓦解","en":"If someone cracks, they lose control of their emotions or actions because they are under a lot of pressure.","ex":{"en":"She's calm and strong, and she is just not going to crack","cn":"她镇定而且坚强，绝不会垮掉。"}},{"pos":"VERB 动词","cn":"(因感情强烈而嗓音)变嘶哑，变沙哑","en":"If your voice cracks when you are speaking or singing, it changes in pitch because you are feeling a strong emotion.","ex":{"en":"Her voice cracked and she began to cry.","cn":"她的声音变得沙哑，继而哭了起来。"}},{"pos":"VERB 动词","cn":"说(笑话);开(玩笑)","en":"If you crack a joke, you tell it.","ex":{"en":"He cracked jokes and talked about beer and girls.","cn":"他爱说笑话，喜欢谈论啤酒和姑娘。"}},{"pos":"PHRASE 短语","cn":"不如别人说的那么好","en":"If you say that something is not all it's cracked up to be, you mean that it is not as good as other people have said it is.","ex":{"en":"Package holidays are not always all they're cracked up to be.","cn":"全包旅游并不总像人们说的那么好。"}},{"pos":"","cn":"","en":"相关词组：crack down crack up"},{"pos":"N-COUNT 可数名词","cn":"缝隙;狭缝;窄缝","en":"A crack is a very narrow gap between two things, or between two parts of a thing.","ex":{"en":"Kathryn had seen him through a crack in the curtains.","cn":"凯瑟琳透过窗帘缝看见了他。"}},{"pos":"N-SING 单数名词","cn":"(门或窗户打开的)缝隙，窄缝","en":"If you open something such as a door, window, or curtain a crack, you open it only a small amount.","ex":{"en":"He went to the door, opened it a crack, and listened.","cn":"他朝门走去，打开一条门缝听着。"}},{"pos":"N-COUNT 可数名词","cn":"裂纹;裂缝","en":"A crack is a line that appears on the surface of something when it is slightly damaged.","ex":{"en":"The plate had a crack in it","cn":"盘子上有一道裂纹。"}},{"pos":"N-COUNT; SOUND 可数名词；声音词","cn":"爆裂声;噼啪声","en":"A crack is a sharp sound, like the sound of a piece of wood breaking.","ex":{"en":"Suddenly there was a loud crack and glass flew into the car","cn":"突然发出一声巨大的爆裂声，玻璃碎片飞进了车里。"}},{"pos":"N-SING 单数名词","cn":"尝试;试图","en":"If you have or take a crack at something, you make an attempt to do or achieve something.","ex":{"en":"I should love to have a crack at the Olympia title in my last year","cn":"我非常愿意在我职业生涯的最后一年向奥林匹亚大赛冠军头衔发起冲击。"}},{"pos":"N-COUNT 可数名词","cn":"(略显粗鲁或刻薄的)笑话，俏皮话","en":"A crack is a slightly rude or cruel joke.","ex":{"en":"When Paul made the crack about the 'famous girl detective', I began to suspect that he had it in for you.","cn":"当保罗挖苦你是“著名的女侦探”时，我开始怀疑他是不是故意刁难你。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"强效可卡因;强力古柯碱","en":"Crack is a very pure form of the drug cocaine."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(士兵或运动员)训练有素的，一流的","en":"A crack soldier or sportsman is highly trained and very skilful.","ex":{"en":"...a crack undercover police officer","cn":"训练有素的便衣警察"}},{"pos":"PHRASE 短语","cn":"黎明;破晓;清晨","en":"If you say that someone does something at the crack of dawn, you are emphasizing that they do it very early in the morning.","ex":{"en":"I often start work at the crack of dawn when there is a big order to get out.","cn":"有大笔订单要处理时，我经常会清晨便开始工作。"}},{"pos":"PHRASE 短语","cn":"掩盖错误","en":"If you paper over the cracks, you try to hide all the things that are wrong with something.","ex":{"en":"The meeting was stormy, and the two sides managed only to paper over the cracks on some issues.","cn":"会议很激烈，但双方只是在试图掩盖某些问题上的错误。"}},{"pos":"PHRASE 短语","cn":"合理的机会;均等的机会","en":"If you get a fair crack of the whip, you are allowed a reasonable opportunity to succeed at something.","ex":{"en":"None of them is expecting any favours, just a fair crack of the whip.","cn":"他们谁也不期望受到任何特殊照顾，只希望机会均等。"}}]},"media":{"uk":"media/uk/crack__gb_1.mp3","us":"media/us/crack__us_1.mp3"},"examples":[{"en":"Things are terrible at work and people are cracking under the strain.","cn":"工作情况很糟糕，人们因过度紧张越来越吃不消了。"},{"en":"( informal ) After a year in this job I think I've got it cracked!","cn":"干了一年后，我觉得我已知道怎样做好这项工作了！"}]},"cry":{"media":{"uk":"media/uk/cry__gb_1.mp3","us":"media/us/cry__us_1.mp3"},"oxford":{"phon":"kraɪ","pos":"verb","senses":[{"en":"to produce tears from your eyes because you are unhappy or hurt","cn":"哭；哭泣","g":"[intransitive, transitive]","lab":"informal","ex":{"en":"It's all right. Don't cry.","cn":"不要紧，别哭了。"}},{"en":"to shout loudly","cn":"喊叫；呼喊；呼叫","g":"[intransitive, transitive]","ex":{"en":"She ran to the window and cried for help.","cn":"她跑到窗口呼喊救命。"}},{"en":"to make a loud noise","cn":"鸣叫；吼叫","g":"[intransitive]","ex":{"en":"Seagulls followed the boat, crying loudly.","cn":"海鸥追随着那条船，高声鸣叫着。"}},{"en":"a loud sound without words that expresses a strong feeling","cn":"（表达强烈感情的）叫喊，叫声","g":"[countable]","ex":{"en":"to give a cry of anguish/despair/pain/joy/alarm, etc.","cn":"发出悲痛欲绝、绝望、痛苦、兴奋、惊恐等的叫声"},"pos":"noun"},{"en":"a loud shout","cn":"大喊；大叫；呼喊","g":"[countable]","ex":{"en":"With a cry of ‘Stop thief!’ he ran after the boy.","cn":"他一边喊“抓贼啊！”一边追赶那男孩。"},"pos":"noun"},{"en":"the sound made by a bird or an animal","cn":"（鸟的）鸣叫，啼叫；（动物的）嗥叫，吠","g":"[countable]","ex":{"en":"the cry of gulls circling overhead","cn":"海鸥在头顶上盘旋着发出的鸣叫"},"pos":"noun"},{"en":"a demand or request for something that is needed immediately","cn":"迫切的需要；紧急的需求","g":"[countable]","ex":{"en":"Her behaviour at school was really a cry for help.","cn":"她在学校的行为确实是在寻求帮助。"},"pos":"noun"},{"en":"an action or a period of crying","cn":"哭；一阵哭泣","g":"[singular]","ex":{"en":"I felt a lot better after a good long cry.","cn":"我痛痛快快哭了一场，好受多了。"},"pos":"noun"},{"en":"a word or phrase that expresses a group’s beliefs and calls people to action","cn":"口号","g":"[countable]","ex":{"en":"a battle cry","cn":"战斗口号"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"哭;哭泣","en":"When you cry, tears come from your eyes, usually because you are unhappy or hurt.","ex":{"en":"I hung up the phone and started to cry","cn":"我挂断电话，开始哭了起来。"}},{"pos":"VERB 动词","cn":"喊叫;呼喊;高声说","en":"If you cry something, you shout it or say it loudly.","ex":{"en":"'Nancy Drew,' she cried, 'you're under arrest!'","cn":"“南茜·朱尔，”她喊道，“你被捕了！”"}},{"pos":"N-COUNT 可数名词","cn":"(表达强烈感情的)叫喊，叫声","en":"A cry is a loud, high sound that you make when you feel a strong emotion such as fear, pain, or pleasure.","ex":{"en":"A cry of horror broke from me","cn":"我吓得大叫了一声。"}},{"pos":"N-COUNT 可数名词","cn":"喊叫;呼喊","en":"A cry is a shouted word or phrase, usually one that is intended to attract someone's attention.","ex":{"en":"Thousands of Ukrainians burst into cries of 'bravo' on the steps of the parliament","cn":"成千上万的乌克兰人聚集在议会门前高喊“好啊”。"}},{"pos":"N-COUNT 可数名词","cn":"抗议;请求","en":"You can refer to a public protest about something or an appeal for something as a cry of some kind.","ex":{"en":"There have been cries of outrage about this expenditure","cn":"这项开支遭到了一些人愤怒的指责。"}},{"pos":"N-COUNT 可数名词","cn":"(鸟的)鸣叫，啼叫;(动物的)嗥叫，吠","en":"A bird's or animal's cry is the loud, high sound that it makes.","ex":{"en":"...the cry of a seagull.","cn":"海鸥的鸣叫"}},{"pos":"PHRASE 短语","cn":"(与…)大相径庭，相去甚远","en":"Something that is a far cry from something else is very different from it.","ex":{"en":"Their lives are a far cry from his own poor childhood.","cn":"他们的生活与他那贫苦的童年生活相比大相径庭。"}},{"pos":"PHRASE 短语","cn":"大声疾呼;激情呐喊","en":"When someone is in full cry, they are expressing their views very strongly or are very active.","ex":{"en":"The main opposition party is already in full cry over this mishandling of security.","cn":"主要反对党已经对这起安全事故的错误处理进行了猛烈抨击。"}},{"pos":"EXCLAM 感叹语","cn":"天啊，哎呀，岂有此理(用来表示恼怒或不耐烦，或加强提问或请求的语气)","en":"You use the expression for crying out loud in order to show that you are annoyed or impatient, or to add force to a question or request.","ex":{"en":"I mean, what's he ever done in his life, for crying out loud?","cn":"我的意思是，天啊，他一生中到底做过什么呀？"}},{"pos":"","cn":"","en":"to cry your eyes out→see: ; a shoulder to cry on→see: ;"},{"pos":"","cn":"","en":"相关词组：cry off cry out cry out for"}]},"examples":[{"en":"She said she was coming to the party, but cried off at the last moment.","cn":"她说过她要来参加聚会，可到最后一刻又变卦了。"},{"en":"to give a cry of anguish/despair/relief/surprise/terror, etc.","cn":"发出痛苦、绝望、如释重负、惊讶、恐怖等的叫声"}]},"craving":{"media":{"uk":"media/uk/craving__gb_1.mp3","us":"media/us/craving__us_1.mp3"},"oxford":{"phon":"ˈkreɪvɪŋ","pos":"noun","senses":[{"en":"a strong desire for something","cn":"渴望；热望","ex":{"en":"a craving for chocolate","cn":"非常想吃巧克力"}}]},"examples":[{"en":"a desperate craving to be loved","cn":"对被爱的极度渴望"},{"en":"a craving for chocolate","cn":"非常想吃巧克力"}]},"crunch":{"media":{"uk":"media/uk/crunch__gb_1.mp3","us":"media/us/crunch__us_1.mp3"},"oxford":{"phon":"krʌntʃ","pos":"noun","senses":[{"en":"a noise like the sound of something hard being pressed or crushed","cn":"压碎声；碎裂声","g":"[countable, usually singular]","ex":{"en":"the crunch of feet on snow","cn":"脚踩着雪发出的嘎吱嘎吱声"}},{"en":"an important and often unpleasant situation or piece of information","cn":"紧要关头；困境；症结；令人不快的重要消息","g":"[singular]","lab":"informal","ex":{"en":"The crunch came when she returned from America.","cn":"她从美国回来以后，危机就出现了。"}},{"en":"a situation in which there is suddenly not enough of something, especially money","cn":"（突发的）不足，短缺；（尤指）缺钱","g":"[countable, usually singular]","ex":{"en":"the budget/energy/housing crunch","cn":"预算／能源／住房短缺"}},{"en":"an exercise for making your stomach muscles strong, in which you lie on your back on the floor and raise the top part of your body to a sitting position","cn":"仰卧起坐","g":"[countable]"},{"en":"to bite something noisily between your teeth when you are eating","cn":"嘎吱嘎吱地嚼","g":"[transitive, intransitive]","ex":{"en":"She crunched her apple noisily.","cn":"她吃苹果发出嘎嚓嘎嚓的声音。"},"pos":"verb"},{"en":"to make a noise like something hard being pressed or crushed; to cause something to make a noise like this","cn":"（使）嘎吱作响","g":"[intransitive, transitive]","ex":{"en":"The snow crunched under our feet.","cn":"积雪在我们脚下嘎吱作响。"},"pos":"verb"},{"en":"to move over a surface, making a noise like the sound of something hard being pressed or crushed","cn":"嘎吱嘎吱地走过（或碾过）","g":"[intransitive]","ex":{"en":"I crunched across the gravel to the front door.","cn":"我嘎吱嘎吱走过石子路来到前门。"},"pos":"verb"},{"en":"to deal with large amounts of data very quickly","cn":"（快速大量地）处理信息；数字捣弄","g":"[transitive]","lab":"computing","ex":{"en":"We are waiting for the results officials who are still crunching numbers.","cn":"我们正在等待结果，官员们仍在处理数字。"},"pos":"verb"},{"en":"a crunch meeting, sports game, etc. is very important and may be the last chance to succeed","cn":"（会议、体育竞赛等）至关重要的，最后一线胜机的","ex":{"en":"Sunday’s crunch game with Leeds","cn":"星期天与利兹队决一雌雄的比赛"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"嘎吱嘎吱地嚼","en":"If you crunch something hard, such as a sweet, you crush it noisily between your teeth.","ex":{"en":"She sucked an ice cube into her mouth, and crunched it loudly","cn":"她吸了块冰块到嘴里，嘎嘣嘎嘣地大声嚼着。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)发出碎裂声;(使)嘎吱作响","en":"If something crunches or if you crunch it, it makes a breaking or crushing noise, for example when you step on it.","ex":{"en":"A piece of china crunched under my foot","cn":"我踩碎了一块瓷片。"}},{"pos":"VERB 动词","cn":"(在小石子铺成的路上)嘎吱嘎吱地行进","en":"If you crunch across a surface made of very small stones, you move across it causing it to make a crunching noise.","ex":{"en":"I crunched across the gravel.","cn":"我嘎吱嘎吱地走过石子路。"}},{"pos":"N-SING 单数名词","cn":"紧要关头;重要事件","en":"You can refer to an important time or event, for example when an important decision has to be made, as the crunch .","ex":{"en":"Tomorrow, though, is the crunch","cn":"明天可就是紧要关头了。"}},{"pos":"VERB 动词","cn":"(用计算器或计算机大量地)处理(数字)","en":"To crunch numbers means to do a lot of calculations using a calculator or computer.","ex":{"en":"I pored over the books with great enthusiasm, often crunching the numbers until 1:00 a.m.","cn":"我兴致勃勃地研究这些账簿，经常计算到凌晨1点。"}},{"pos":"N-COUNT 可数名词","cn":"缺少资金;经济收缩;财政困难","en":"A situation in which a business or economy has very little money can be referred to as a crunch .","ex":{"en":"The UN is facing a cash crunch.","cn":"联合国面临着现金短缺问题。"}}]},"examples":[{"en":"He always says he'll help but when it comes to the crunch (= when it is time for action) he does nothing.","cn":"他口口声声说一定帮忙，然而到关键时候却不会行动。"},{"en":"The car drew up with a crunch of gravel.","cn":"那辆汽车在沙砾路上嘎吱一声停了下来。"}]},"cruel":{"oxford":{"phon":"ˈkruːəl","pos":"adjective","senses":[{"en":"having a desire to cause physical or mental pain and make somebody suffer","cn":"残酷的；冷酷的；残忍的；残暴的","ex":{"en":"He was known to be a cruel dictator.","cn":"他是一个出了名的残暴独裁者。"}},{"en":"causing physical or mental pain and making somebody suffer","cn":"引起痛苦的；令人难受的；残忍的","ex":{"en":"a cruel joke/hoax","cn":"残酷的笑话／恶作剧"}},{"en":"to negatively affect an opportunity or a chance of success","cn":"搞糟；使机会丧失","ex":{"en":"He cruelled his interview by arriving late and being completely unprepared.","cn":"他迟到了，而且完全没有准备，把面试搞砸了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"残酷的;冷酷的;残忍的;残暴的","en":"Someone who is cruel deliberately causes pain or distress to people or animals.","ex":{"en":"Children can be so cruel","cn":"孩子有时可能会相当残忍。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(处境或事件)引起痛苦的，残酷的","en":"A situation or event that is cruel is very harsh and causes people distress.","ex":{"en":"...struggling to survive in a cruel world with which they cannot cope","cn":"在一个难以应付的残酷世界里拼命求生"}}]},"media":{"uk":"media/uk/cruel__gb_1.mp3","us":"media/us/cruel__us_1.mp3"},"examples":[{"en":"Sometimes you have to be cruel to be kind (= make sb suffer because it will be good for them later).","cn":"有时候为了某人好你就得对他狠。"},{"en":"I can't stand people who are cruel to animals.","cn":"我无法容忍虐待动物的人。"}]},"creativity":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to use your imagination to produce new ideas, make things etc","cn":"独创性﹐创造性﹐创造力"}]},"examples":[{"en":"Teachers have been attacked for stifling creativity in their pupils.","cn":"教师被批评压抑了学生的创造力。","src":"ld"},{"en":"Editors complain about the lack of creativity in the ideas put to them.","cn":"编辑们抱怨说交给他们的选题缺乏创意。","src":"ld"}],"media":{"uk":"media/uk/creativity__gb_1.mp3","us":"media/us/creativity__us_1.mp3"},"oxford":{"phon":"ˌkriːeɪˈtɪvəti","pos":"noun","senses":[{"en":"the use of skill and imagination to produce something new or to produce art","cn":"创造力；创意；创造","ex":{"en":"Creativity and originality are more important than technical skill.","cn":"创造力和原创性比技巧更重要。"}}]}},"creature":{"media":{"uk":"media/uk/creature__gb_1.mp3","us":"media/us/creature__us_1.mp3"},"oxford":{"phon":"ˈkriːtʃə(r)","pos":"noun","senses":[{"en":"a living thing, real or imaginary, that can move around, such as an animal","cn":"生物；动物","ex":{"en":"respect for all living creatures","cn":"对所有生物的尊重"}},{"en":"a person, considered in a particular way","cn":"（具有某种特征的）人","ex":{"en":"You pathetic creature!","cn":"你这可怜的家伙！"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指不熟悉或想象中的)生物，动物","en":"You can refer to any living thing that is not a plant as a creature, especially when it is of an unknown or unfamiliar kind. People also refer to imaginary animals and beings as creatures .","ex":{"en":"Alaskan Eskimos believe that every living creature possesses a spirit","cn":"阿拉斯加的爱斯基摩人认为每一个活着的生物都有灵魂。"}},{"pos":"N-COUNT 可数名词","cn":"(具有某种特征的)人","en":"If you say that someone is a particular type of creature, you are focusing on a particular quality they have. a creature of habit→see: ;","ex":{"en":"She's charming, a sweet creature","cn":"她很迷人，是个可人儿。"}},{"pos":"N-COUNT 可数名词","cn":"傀儡;奴才;走狗","en":"If you describe someone as someone else's creature, you mean that they are controlled by or depend on that person.","ex":{"en":"We are not creatures of the Conservative government.","cn":"我们不是保守派政府的傀儡。"}}]},"examples":[{"en":"She was an exotic creature with long red hair and brilliant green eyes.","cn":"她长着红色长发、明亮碧眼，是个少见的大美人。"},{"en":"He always goes to bed at ten — he's a creature of habit (= he likes to do the same things at the same time every day).","cn":"他总在十点钟上床睡觉，是个严守生活习惯的人。"}]},"crackdown":{"oxford":{"phon":"ˈkrækdaʊn","pos":"noun","senses":[{"en":"severe action taken to limit the activities of criminals or of people opposed to the government or somebody in authority","cn":"严厉的打击；镇压","ex":{"en":"a military crackdown on student protesters","cn":"对抗议的学生实行的军事镇压"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"严惩;严厉打击;镇压","en":"A crackdown is strong official action that is taken to punish people who break laws.","ex":{"en":"...anti-government unrest that ended with the violent army crackdown.","cn":"最终被军队严厉镇压的反政府动乱"}}]},"media":{"uk":"media/uk/crackdown__gb_1.mp3","us":"media/us/crackdown__us_1.mp3"},"examples":[{"en":"a military crackdown on student protesters","cn":"对抗议的学生实行的军事镇压"},{"en":"a crackdown on crime","cn":"对犯罪的严厉打击"}]},"cross":{"media":{"uk":"media/uk/cross__gb_1.mp3","us":"media/us/cross__us_1.mp3"},"oxford":{"phon":"krɒs","pos":"verb","senses":[{"en":"to go across; to pass or stretch from one side to the other","cn":"穿越；越过；横过；渡过","g":"[intransitive, transitive]","sc":"go/put across","ex":{"en":"As soon as traffic slowed down enough to safely cross, I started walking.","cn":"往来车辆的车速刚刚减慢到行人可以安全通过时，我便走了起来。"}},{"en":"to pass across each other","cn":"交叉；相交","g":"[intransitive, transitive]","sc":"go/put across","ex":{"en":"The roads cross just outside the town.","cn":"这些道路正好在城外交叉。"}},{"en":"to put or place something across or over something else","cn":"使交叉；使交叠","g":"[transitive]","sc":"go/put across","ex":{"en":"to cross your arms/legs (= place one arm or leg over the other)","cn":"交叉两臂／双腿"}},{"en":"to oppose somebody or speak against them or their plans or wishes","cn":"反对，反驳，否定（某人或计划、意愿）","g":"[transitive]","lab":"literary","sc":"oppose","ex":{"en":"She's really nice until you cross her.","cn":"她待人确实很好，除非你跟她作对。"}},{"en":"to make two different types of animal breed (= produce young) together; to mix two types of plant to form a new one","cn":"使杂交；使异种交配","g":"[transitive]","lab":"figurative","sc":"mix animals/plants","ex":{"en":"A mule is the product of a horse crossed with a donkey.","cn":"骡是马和驴杂交的产物。"}},{"en":"to kick or pass a ball to the side across the field","cn":"横传","g":"[intransitive, transitive]","sc":"in sport","ex":{"en":"Sissoko crossed from the left.","cn":"西索科从左侧传中。"}},{"en":"to draw a line across something","cn":"画横线于","g":"[transitive]","sc":"draw line","ex":{"en":"to cross your t’s (= the letters in writing)","cn":"写 t 上面的一横"}},{"en":"to make the sign of the cross (= the Christian symbol) on your chest","cn":"（在胸口上）画十字圣号","g":"[transitive]","sc":"make Christian symbol"},{"en":"a mark or an object formed by two lines crossing each other (X or +); the mark (X) is often used on paper to show something","cn":"叉字形记号；十字形记号","g":"[countable]","sc":"mark on paper","ex":{"en":"I've put a cross on the map to show where the hotel is.","cn":"我已在地图上打叉标出了旅馆的位置。"},"pos":"noun"},{"en":"a long straight piece of wood with one end in the ground and a shorter piece joined across it from side to side near the top. In ancient times people were hung on crosses and left to die as a punishment.","cn":"（旧时用以处死人的）十字架","g":"[countable]","sc":"for punishment","pos":"noun"},{"en":"the cross that Jesus Christ died on, used as a symbol of Christianity","cn":"（耶稣钉死在上面的）十字架","g":"[singular]","sc":"Christian symbol","ex":{"en":"The priest blessed her, and made the sign of the cross over her.","cn":"神父祝福她，并在她头顶上方画十字。"},"pos":"noun"},{"en":"an object, a design, a piece of jewellery, etc. in the shape of a cross, used as a symbol of Christianity","cn":"十字架物品（或设计、首饰等）","g":"[countable]","sc":"Christian symbol","ex":{"en":"She wore a small gold cross on a chain around her neck.","cn":"她脖子上戴了一条项链，上面挂着个金的小十字架。"},"pos":"noun"},{"en":"a small decoration in the shape of a cross that is given to somebody as an honour for doing something very brave","cn":"（表彰英勇行为的）十字勋章","g":"[countable]","sc":"medal","ex":{"en":"He was awarded the Military Cross.","cn":"他被授予十字勋章"},"pos":"noun"},{"en":"a mixture of two different things, breeds (= types) of animal, etc.","cn":"混合物；（动物等的）杂种，杂交品种","g":"[countable, usually singular]","sc":"mixture","ex":{"en":"The play was a cross between a farce and a tragedy.","cn":"这出戏把闹剧和悲剧交织为一体。"},"pos":"noun"},{"en":"a kick or hit of the ball across the field rather than up or down it","cn":"横传","g":"[countable]","sc":"in sport","ex":{"en":"Webster's low cross was fired into the net by Varney.","cn":"韦伯斯特的下底传中被瓦尼射进了球门。"},"pos":"noun"},{"en":"annoyed or quite angry","cn":"恼怒的；十分愤怒的；生气的","lab":"especially North American English","ex":{"en":"I was cross with him for being late.","cn":"我因他迟到而十分生气。"},"pos":"adjective"},{"en":"involving movement or action from one thing to another or between two things","cn":"从一事物到另一事物的运动（或动作）；两事物间的运动（或动作）；横过；穿越","ex":{"en":"cross-Channel ferries","cn":"横渡英吉利海峡的渡船"},"pos":"combining form"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"穿越;越过;横过;渡过","en":"If you cross something such as a room, a road, or an area of land or water, you move or travel to the other side of it. If you cross to a place, you move or travel over a room, road, or area of land or water in order to reach that place.","ex":{"en":"She was partly to blame for failing to look as she crossed the road","cn":"她过马路时没注意看，负有部分责任。"}},{"pos":"VERB 动词","cn":"(公路、铁路或桥)穿过，越过","en":"A road, railway, or bridge that crosses an area of land or water passes over it.","ex":{"en":"The Defford to Eckington road crosses the river half a mile outside Eckington.","cn":"从迪福德到埃金顿的路穿过那条距埃金顿半英里的河。"}},{"pos":"V-RECIP 相互动词","cn":"交叉;相交","en":"Lines or roads that cross meet and go across each other.","ex":{"en":"...the intersection where Main and Center streets cross","cn":"主街和中心街的交叉路口"}},{"pos":"VERB 动词","cn":"超过，超出(极限或范围)","en":"If someone or something crosses a limit or boundary, for example the limit of acceptable behaviour, they go beyond it.","ex":{"en":"I normally never write into magazines but Mr Stubbs has finally crossed the line","cn":"我向来不给杂志写信，但是斯塔布斯先生最后做得太过火了。"}},{"pos":"VERB 动词","cn":"(表情)掠过，闪过","en":"If an expression crosses someone's face, it appears briefly on their face.","ex":{"en":"Berg tilts his head and a mischievous look crosses his face","cn":"伯格侧着头，脸上掠过一丝调皮的神情。"}},{"pos":"N-COUNT 可数名词","cn":"十字形，十字架(基督教最重要的标记)","en":"A cross is a shape that consists of a vertical line or piece with a shorter horizontal line or piece across it. It is the most important Christian symbol.","ex":{"en":"Round her neck was a cross on a silver chain","cn":"她脖子上戴着一条银项链，上面挂着个十字架。"}},{"pos":"VERB 动词","cn":"(基督教徒)画十字","en":"If Christians cross themselves, they make the sign of a cross by moving their hand across the top half of their body.","ex":{"en":"'Holy Mother of God!' Marco crossed himself.","cn":"“圣母啊！”马尔科画着十字说道。"}},{"pos":"N-COUNT 可数名词","cn":"麻烦;不利","en":"If you describe something as a cross that someone has to bear, you mean it is a problem or disadvantage which they have to deal with or bear.","ex":{"en":"My wife is much cleverer than me; it is a cross I have to bear.","cn":"妻子比我聪明很多，这让我很难接受。"}},{"pos":"N-COUNT 可数名词","cn":"叉字形记号;十字形记号","en":"A cross is a written mark in the shape of an X. You can use it, for example, to indicate that an answer to a question is wrong, to mark the position of something on a map, or to indicate your vote on a ballot paper.","ex":{"en":"Put a tick next to those activities you like and a cross next to those you dislike.","cn":"在你喜欢的活动旁打钩，在不喜欢的活动旁画叉。"}},{"pos":"VERB 动词","cn":"在(支票)上画两条平行线(使支票只能划入银行账户，不能兑现)","en":"If a cheque is crossed, two parallel lines are drawn across it or printed on it to indicate that it must be paid into a bank account and cannot be cashed.","ex":{"en":"Cheques/postal orders should be crossed and made payable to Newmarket Promotions.","cn":"应在支票/邮政汇票上画线，并使之可用于新市场促销活动的支付。"}},{"pos":"VERB 动词","cn":"使交叉;使交叠","en":"If you cross your arms, legs, or fingers, you put one of them on top of the other.","ex":{"en":"Jill crossed her legs and rested her chin on one fist, as if lost in deep thought","cn":"吉尔盘着腿，一个拳头支着下巴，仿佛陷入了沉思。"}},{"pos":"VERB 动词","cn":"反对;拒绝","en":"If you cross someone who is likely to get angry, you oppose them or refuse to do what they want.","ex":{"en":"If you ever cross him, forget it, you're finished.","cn":"如果你曾经跟他作过对，就别想了，你没戏了。"}},{"pos":"N-SING 单数名词","cn":"混合物;杂交品种","en":"Something that is a cross between two things is neither one thing nor the other, but a mixture of both.","ex":{"en":"'Ha!' It was a cross between a laugh and a bark","cn":"“哈！”那声音听起来既像在笑又像在叫。"}},{"pos":"N-COUNT 可数名词","cn":"(足球、曲棍球等球队运动中的)横传","en":"In some team sports such as football and hockey, a cross is the passing of the ball from the side of the field to a player in the centre, usually in front of the goal.","ex":{"en":"Le Tissier hit an accurate cross to Groves.","cn":"勒蒂西耶将球准确地横传给了格罗夫斯。"}},{"pos":"ADJ 形容词","cn":"(街道)交叉的，十字的","en":"A cross street is a road that crosses another more important road.","ex":{"en":"The Army boys had personnel carriers blockading the cross streets.","cn":"陆军士兵用运兵车封锁了十字路口。"}},{"pos":"See also:","cn":"","en":"to cross your fingers→see: ; cross my heart→see: ; to cross your mind→see: ; people's paths cross→see: ; to cross the Rubicon→see: ; to cross swords→see: ;"},{"pos":"","cn":"","en":"相关词组：cross off cross out"},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"生气的;愤怒的","en":"Someone who is cross is rather angry or irritated.","ex":{"en":"The women are cross and bored","cn":"这个女人很生气，烦透了。"}}]},"examples":[{"en":"She wore a small gold cross on a chain around her neck.","cn":"她脖子上戴了一条项链，上面挂着个金的小十字架。"},{"en":"( BrE ) to cross a cheque (= to draw two lines across it so that it can only be paid through a bank account)","cn":"在支票上画线（使支票只能经银行账户兑现）"}]},"cream":{"media":{"uk":"media/uk/cream__gb_1.mp3","us":"media/us/cream__us_1.mp3"},"oxford":{"phon":"kriːm","pos":"noun","senses":[{"en":"the thick white or pale yellow fatty liquid that rises to the top of milk, used in cooking or as a type of sauce to put on fruit, etc.","cn":"奶油；乳脂","g":"[uncountable]","lab":"British English","ex":{"en":"We had strawberries and cream for dessert.","cn":"我们的甜点是加奶油的草莓。"}},{"en":"a sweet that has a soft substance like cream inside","cn":"奶油夹心糖","g":"[countable]","ex":{"en":"a chocolate/peppermint cream","cn":"巧克力／薄荷奶油夹心糖"}},{"en":"a soft substance or thick liquid used on your skin to protect it or make it feel soft; a similar substance used for cleaning things","cn":"护肤霜；洁净剂；清洗液","g":"[uncountable, countable]","ex":{"en":"moisturizing cream","cn":"润肤霜"}},{"en":"a pale colour between yellow and white","cn":"奶油色；乳白色","g":"[uncountable]","ex":{"en":"Do you have this blouse in cream?","cn":"这种衬衫有奶油色的吗？"}},{"en":"the best people or things in a particular group","cn":"精英；精华；精髓","ex":{"en":"the cream of New York society","cn":"纽约社会的精英"}},{"en":"between yellow and white in colour","cn":"奶油色的；乳白色的","ex":{"en":"a cream linen suit","cn":"米色的亚麻布套装"},"pos":"adjective"},{"en":"to mix things together into a soft smooth mixture","cn":"把…搅成糊状（或奶油状）混合物","ex":{"en":"Cream the butter and sugar together.","cn":"把黄油和糖搅成糊状。"},"pos":"verb"},{"en":"to completely defeat somebody","cn":"彻底打败；狠揍","lab":"North American English, informal，，","ex":{"en":"We got creamed in the first round.","cn":"我们在第一轮就被彻底打败了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(用于烹饪或放于水果或甜点上的)奶油，乳脂","en":"Cream is a thick yellowish-white liquid taken from milk. You can use it in cooking or put it on fruit or desserts.","ex":{"en":"...strawberries and cream.","cn":"奶油草莓"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(用于含奶油或牛奶的汤的名称中)","en":"Cream is used in the names of soups that contain cream or milk.","ex":{"en":"...cream of mushroom soup.","cn":"奶油蘑菇汤"}},{"pos":"N-VAR 可变名词","cn":"护肤霜;润肤霜;药膏","en":"A cream is a substance that you rub into your skin, for example to keep it soft or to heal or protect it.","ex":{"en":"Gently apply the cream to the affected areas.","cn":"把药膏轻轻涂抹在患处。"}},{"pos":"COLOUR 颜色词","cn":"奶油色;淡黄色;米色","en":"Something that is cream is yellowish-white in colour.","ex":{"en":"...cream silk stockings.","cn":"米色丝袜"}},{"pos":"N-SING-COLL 单数集合名词","cn":"精英;精华","en":"Cream is used in expressions such as the cream of society and the cream of British athletes to refer to the best people or things of a particular kind.","ex":{"en":"The Ball was attended by the cream of Hollywood society.","cn":"好莱坞的大牌影星们出席了那个舞会。"}},{"pos":"","cn":"","en":"相关词组：cream off"}]},"examples":[{"en":"The best students were creamed off by the grammar schools.","cn":"最好的学生都已被文法学校录取。"},{"en":"We got creamed in the first round.","cn":"我们在第一轮就被彻底打败了。"}]},"create":{"media":{"uk":"media/uk/create__gb_1.mp3","us":"media/us/create__us_1.mp3"},"oxford":{"phon":"kriˈeɪt","pos":"verb","senses":[{"en":"to make something happen or exist","cn":"创造；创作；创建","ex":{"en":"Scientists disagree about how the universe was created.","cn":"科学家对宇宙是怎样形成的有分歧。"}},{"en":"to produce a particular feeling or impression","cn":"造成，引起，产生（感觉或印象）","ex":{"en":"He's eager to create a good impression at work.","cn":"他渴望在工作中给人留下好印象。"}},{"en":"to give somebody a particular rank or title","cn":"授予；册封","ex":{"en":"The government has created eight new peers.","cn":"政府新封了八个贵族。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"创造;使发生;创建","en":"To create something means to cause it to happen or exist.","ex":{"en":"We set business free to create more jobs in Britain","cn":"我们放开对企业的限制以便在英国创造更多的就业机会。"}},{"pos":"VERB 动词","cn":"创造;发明;设计","en":"When someone creates a new product or process, they invent it or design it.","ex":{"en":"It is really great for a radio producer to create a show like this","cn":"电台监制能够制作出这样的节目真是不简单。"}}]},"examples":[{"en":"Create a new directory and put all your files into it.","cn":"创建一个新的目录，然后把你所有的文件都放进去。"},{"en":"The company is trying to create a young energetic image.","cn":"这家公司正试图塑造一个充满活力的年轻形象。"}]},"crabs":{"lemma":"crab"},"criticized":{"lemma":"criticize"},"crest":{"media":{"img":["media/pic/birds_comp.jpg","media/thumb/crest.jpg"],"uk":"media/uk/crest__gb_1.mp3","us":"media/us/crest__us_1.mp3"},"oxford":{"phon":"krest","pos":"noun","senses":[{"en":"the top part of a hill or wave","cn":"山顶；顶峰；波峰；浪尖","g":"[usually singular]","ex":{"en":"surfers riding the crest of the wave","cn":"正在浪峰上冲浪的运动员"}},{"en":"a design used as the symbol of a particular family, organization, etc., especially one that has a long history","cn":"（尤指象征历史悠久的家族、机构等的）饰章，纹章","ex":{"en":"the university crest","cn":"大学的徽章"}},{"en":"a group of feathers that stand up on top of a bird’s head","cn":"鸟冠；羽冠","ex":{"en":"The male is recognizable by its yellow crest.","cn":"雄性可通过其黄色冠来识别。"}},{"en":"to reach the top of a hill, mountain or wave","cn":"到达山顶（或浪峰）","g":"[transitive]","lab":"formal","ex":{"en":"He slowed the pace as they crested the ridge.","cn":"当他们到达山脊时，他放慢了步伐。"},"pos":"verb"},{"en":"to reach its highest level before it falls again","cn":"到达洪峰；达到顶点","g":"[intransitive]","lab":"North American English","ex":{"en":"The level of debt crested at a massive $290 billion in 2009.","cn":"2009 年的巨额债务高达 2 900 亿美元。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"山顶;波峰;浪尖","en":"The crest of a hill or a wave is the top of it.","ex":{"en":"The band are riding on the crest of a wave with the worldwide success of their number one selling single.","cn":"该乐队正处于巅峰时期，单曲唱片销量世界排名第一。"}},{"pos":"VERB 动词","cn":"到达山顶","en":"When someone crests a hill, they reach the top of it.","ex":{"en":"The first wave of marchers crested the hill.","cn":"第一批游行示威者登上了山顶。"}},{"pos":"N-COUNT 可数名词","cn":"鸟冠;羽冠","en":"A bird's crest is a group of upright feathers on the top of its head.","ex":{"en":"Both birds had a dark blue crest.","cn":"两种鸟都长着深蓝色的羽冠。"}},{"pos":"N-COUNT 可数名词","cn":"(贵族家庭、城镇或组织的)饰章，纹章","en":"A crest is a design that is the symbol of a noble family, a town, or an organization.","ex":{"en":"On the wall is the family crest.","cn":"墙上挂着那个家族的饰章。"}}]},"examples":[{"en":"( figurative ) The level of debt crested at a massive $290 billion in 2009. * 2009","cn":"年的巨额债务高达 2 900 亿元。"},{"en":"He slowed the pace as they crested the ridge.","cn":"当他们到达山脊时，他放慢了步伐。"}]},"crab":{"oxford":{"phon":"kræb","pos":"noun","senses":[{"en":"a sea creature with a hard shell, eight legs and two pincers (= curved and pointed arms for catching and holding things). Crabs move sideways (= towards the side) on land.","cn":"蟹；螃蟹","g":"[countable]"},{"en":"meat from a crab, used for food","cn":"蟹肉","g":"[uncountable]","ex":{"en":"dressed crab","cn":"经加工的螃蟹"}},{"en":"the condition caused by having lice (called crab lice) in the hair around the genitals","cn":"阴虱病","lab":"informal"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蟹;螃蟹","en":"A crab is a sea creature with a flat round body covered by a shell, and five pairs of legs with large claws on the front pair. Crabs usually move sideways."}]},"media":{"img":["media/ldoce/img/crab.jpg","media/pic/crustaceans_comp.jpg"],"uk":"media/uk/crab__gb_1.mp3","us":"media/us/crab__us_1.mp3"},"examples":[{"en":"dressed crab","cn":"经加工的螃蟹"},{"en":"dressed crab (= prepared for eating )","cn":"填在蟹壳里的熟蟹肉"}]},"crosses":{"lemma":"cross","media":{"uk":"media/uk/cross__gb_1.mp3","us":"media/us/cross__us_1.mp3"}},"craftsman":{"media":{"uk":"media/uk/craftsman__gb_1.mp3","us":"media/us/craftsman__us_1.mp3"},"oxford":{"phon":"ˈkrɑːftsmən","pos":"noun","senses":[{"en":"a person with a special skill, especially one who makes beautiful things by hand","cn":"工匠；手艺人；工艺师","ex":{"en":"rugs handmade by local craftsmen","cn":"由当地工艺师手工制作的小地毯"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"工匠;手艺人;工艺师","en":"A craftsman is a man who makes things skilfully with his hands.","ex":{"en":"The table in the kitchen was made by a local craftsman.","cn":"厨房里的桌子是本地一位工匠制作的。"}}]},"examples":[{"en":"It is clearly the work of a master craftsman.","cn":"很明显这是工艺大师的作品。"},{"en":"rugs handmade by local craftsmen","cn":"由当地工艺师手工制作的小地毯"}]},"cross-section":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"典型的一群人(或事物)","en":"If you refer to a cross-section of particular things or people, you mean a group of them that you think is typical or representative of all of them.","ex":{"en":"I was surprised at the cross-section of people there","cn":"那里的一些典型人物让我感到惊讶。"}},{"pos":"N-COUNT 可数名词","cn":"横截面;剖面","en":"A cross-section of an object is what you would see if you could cut straight through the middle of it.","ex":{"en":"...a cross-section of an airplane","cn":"飞机剖面图"}}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41cross-section.mp3","us":"media/ldoce/hwd/ame/7/laadcross_section.mp3"},"examples":[{"en":"a cross-section of a plant stem","cn":"植物茎的横截面（图）"},{"en":"The roof beams were 50 centimetres square in cross-section.","cn":"顶梁的横截面有50平方厘米。"}],"oxford":{"phon":"ˈkrɒs sekʃn","pos":"noun","senses":[{"en":"what you see when you cut through the middle of something so that you can see the different layers it is made of; a drawing of this view","cn":"横截面（图）；剖面（图）；断面（图）","g":"[countable, uncountable]","ex":{"en":"a diagram representing a cross section of the human eye","cn":"表现人眼的剖面图"}},{"en":"a group of people or things that are typical of a larger group","cn":"典型的一群人（或事物）","g":"[countable, usually singular]","ex":{"en":"a representative cross section of society","cn":"一群具有代表性的社会典型人物"}}]}},"crib":{"media":{"img":["media/pic/beds_comp.jpg","media/thumb/cot.jpg","media/ldoce/img/cot.jpg"],"uk":"media/uk/crib__gb_1.mp3","us":"media/us/crib__us_1.mp3"},"oxford":{"phon":"krɪb","pos":"noun","senses":[{"en":"a small bed with high sides for a baby or young child","cn":"（有围栏的）幼儿床","lab":"North American English"},{"en":"a long open box that horses and cows can eat from","cn":"（马、牛的）饲料槽"},{"en":"a model of the scene of Jesus Christ’s birth, placed in churches and homes at Christmas","cn":"圣诞马槽（表现耶稣诞生的情景）","lab":"British English"},{"en":"a set of notes to help you remember important information, especially one taken secretly into an exam room","cn":"备忘纸条；（尤指考试作弊用的）纸条，夹带","lab":"informal","ex":{"en":"crib notes","cn":"小抄"}},{"en":"a card game in which players score points by collecting different combinations of cards. The score is kept by putting small pegs in holes in a board.","cn":"克里比奇牌戏（用小木钉插在有孔的木板上记分）"},{"en":"the house, flat, etc. where somebody lives","cn":"住所；公寓；居所","lab":"North American English, informal，，"},{"en":"to dishonestly copy work from another student or from a book","cn":"（学生在考试或做作业时）抄袭，剽窃","g":"[intransitive, transitive]","lab":"old-fashioned","pos":"verb"},{"en":"to complain about somebody/something in an angry way","cn":"抱怨；发牢骚","g":"[intransitive]","lab":"British English, old-fashioned or Indian English，，","ex":{"en":"Every time we met up, she would start cribbing.","cn":"每次我们见面，她都会开始抱怨。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"婴儿床","en":"A crib is a bed for a small baby."},{"pos":"VERB 动词","cn":"抄袭;剽窃","en":"If you crib, you copy something that someone else has written and pretend that it is your own work.","ex":{"en":"You have been cribbing from Bennett","cn":"你一直在抄袭贝内特。"}}]},"examples":[{"en":"a crib sheet","cn":"夹带的答案纸"},{"en":"I’m not at my crib, I’m at Jed’s house.","cn":"我不在自己的住处﹐我在杰德家。"}]},"crisp":{"oxford":{"phon":"krɪsp","pos":"adjective","senses":[{"en":"pleasantly hard and dry","cn":"脆的；酥脆的","lab":"approving","ex":{"en":"Bake until the pastry is golden and crisp.","cn":"把油酥面团烤至金黄酥脆。"}},{"en":"fairly hard and fresh","cn":"鲜脆的；脆嫩的","lab":"approving","ex":{"en":"a crisp apple/lettuce","cn":"新鲜脆生的苹果／生菜"}},{"en":"fresh and clean; new and slightly stiff without any folds in it","cn":"洁净的；挺括的","lab":"approving","ex":{"en":"a crisp new $5 bill","cn":"一张崭新挺括的 5 美元钞票"}},{"en":"pleasantly dry and cold","cn":"凉爽的；清新的；干燥寒冷让人舒畅的","lab":"approving","ex":{"en":"It was a crisp winter morning.","cn":"那是一个清冷干爽的冬日早晨。"}},{"en":"hard or dry and making a pleasant noise under pressure","cn":"（踩踏时发出）脆响的","lab":"approving","ex":{"en":"deep, crisp snow","cn":"踩上去咯吱作响的厚积雪"}},{"en":"pleasantly clear and sharp","cn":"清脆悦耳的；清晰分明的","lab":"approving","ex":{"en":"The recording sounds very crisp, considering its age.","cn":"考虑到这录音已年代久远，听起来声音还是挺清楚的。"}},{"en":"quick and confident in a way that suggests that the person is busy or is not being friendly","cn":"简短干脆的（表明某人忙或不友好）","lab":"sometimes disapproving","ex":{"en":"Her answer was crisp, and she gave no details.","cn":"她的回答简短而干脆，没有提供细节。"}},{"en":"a thin round slice of potato that is fried until hard then dried and eaten cold. Crisps are sold in bags and are made to taste of many different foods.","cn":"炸薯片（零食商品）","g":"[countable]","lab":"both British English","ex":{"en":"a packet of smoky bacon crisps","cn":"一包熏肉味薯片"},"pos":"noun"},{"en":"a dessert (= a sweet dish) made from fruit that is covered with a rough mixture of flour, butter and sugar, cooked in the oven and usually served hot","cn":"酥皮水果甜点（通常烤熟趁热吃）","g":"[uncountable, countable]","lab":"North American English","ex":{"en":"apple crisp","cn":"苹果酥"},"pos":"noun"},{"en":"to give food a crisp surface by putting it in an oven or under a grill; to develop a crisp surface in this way","cn":"将（食物的）表皮烤酥脆；表皮变酥脆","ex":{"en":"Crisp the pastry in the oven.","cn":"将糕点放入烤箱中酥脆。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)脆的，酥脆的","en":"Food that is crisp is pleasantly hard, or has a pleasantly hard surface.","ex":{"en":"Bake the potatoes for 15 minutes, till they're nice and crisp.","cn":"将土豆片烤15分钟，直至酥脆。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(用加热等方法)(使)变脆","en":"If food crisps or if you crisp it, it becomes pleasantly hard, for example because you have heated it at a high temperature.","ex":{"en":"Cook the bacon until it begins to crisp","cn":"把熏肉烹至酥脆。"}},{"pos":"N-COUNT 可数名词","cn":"(当零食吃的)油炸土豆片，炸薯片","en":"Crisps are very thin slices of fried potato that are eaten cold as a snack.","ex":{"en":"...a packet of crisps.","cn":"一袋炸薯片"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(天气)清新的，凉爽的，干燥的","en":"Weather that is pleasantly fresh, cold, and dry can be described as crisp .","ex":{"en":"...a crisp autumn day.","cn":"秋高气爽的一天"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(布或纸)洁净的，挺括的","en":"Crisp cloth or paper is clean and has no creases in it.","ex":{"en":"He wore a panama hat and a crisp white suit","cn":"他戴着一顶巴拿马草帽，穿着一身挺括的白西装。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(树叶或雪)发出脆响的，咯吱作响的","en":"Leaves or snow that make a loud noise when you walk on them can be described as crisp .","ex":{"en":"...crisp autumn leaves","cn":"踩上去发出脆响的秋叶"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(写作或讲话)简短干脆的(可能显得不友好)","en":"If you describe someone's writing or speech as crisp, you mean they write or speak very clearly, without mentioning unnecessary details. This may make them seem unfriendly.","ex":{"en":"'Very well,' I said, adopting a crisp authoritative tone.","cn":"“很好，”我用干脆的命令性的语气说道。"}},{"pos":"PHRASE 短语","cn":"完全烧毁;付之一炬","en":"If something is burnt to a crisp, it is completely burnt."}]},"media":{"img":["media/pic/chips_crisps.jpg","media/thumb/crisps.jpg","media/ldoce/img/crisps.jpg"],"uk":"media/uk/crisp__gb_1.mp3","us":"media/us/crisp__us_1.mp3"},"examples":[{"en":"The recording sounds very crisp, considering its age.","cn":"考虑到这录音已年代久远，听起来声音还是挺清楚的。"},{"en":"Her answer was crisp, and she gave no details.","cn":"她的回答简短而干脆，没有提供细节。"}]},"crushed":{"lemma":"crush"},"crudity":{"media":{"uk":"media/uk/crudity__gb_1.mp3","us":"media/us/crudity__us_1.mp3"},"oxford":{"phon":"ˈkruːdəti","pos":"noun","senses":[{"en":"the fact of being crude; an example of something crude","cn":"粗糙，简陋，粗俗，粗鲁（的事例）","ex":{"en":"Despite the crudity of their methods and equipment, the experiment was a considerable success.","cn":"尽管他们的方法和设备较为粗陋，那次实验却相当成功。"}}]},"examples":[{"en":"Despite the crudity of their methods and equipment, the experiment was a considerable success.","cn":"尽管他们的方法和设备较为粗陋，那次实验却相当成功。"},{"en":"The crudity of her language shocked him.","cn":"她粗鄙的语言使他感到震惊。"}]},"crossroads":{"media":{"uk":"media/uk/crossroads__gb_1.mp3","us":"media/us/crossroads__us_1.mp3"},"oxford":{"phon":"ˈkrɒsrəʊdz","pos":"noun","senses":[{"en":"a place where two roads meet and cross each other","cn":"十字路口","lab":"figurative","ex":{"en":"At the next crossroads, turn right.","cn":"在下一个十字路口向右拐。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"十字路口","en":"A crossroads is a place where two roads meet and cross each other.","ex":{"en":"Turn right at the first crossroads.","cn":"在第一个十字路口向右转。"}},{"pos":"N-SING 单数名词","cn":"(发展的)关键时刻，紧要关头","en":"If you say that something is at a crossroads, you mean that it has reached a very important stage in its development where it could go one way or another.","ex":{"en":"The company was clearly at a crossroads","cn":"该公司显然处于发展的关键时刻。"}},{"pos":"N-SING 单数名词","cn":"核心地区;汇集地","en":"A crossroads is an important or central place.","ex":{"en":"...Mulberry, a small town at the crossroads of agriculture in central Florida.","cn":"马尔伯里，一个位于佛罗里达州中部农业集中区的小镇"}}]},"examples":[{"en":"( figurative ) He has reached a career crossroads (= he must decide which way to go next in his career).","cn":"他的事业发展到了一个十字路口。"},{"en":"At the next crossroads, turn right.","cn":"在下一个十字路口向右拐。"}]},"criminals":{"lemma":"criminal"},"crop":{"oxford":{"phon":"krɒp","pos":"noun","senses":[{"en":"a plant that is grown in large quantities, especially as food","cn":"庄稼；作物","g":"[countable]","lab":"North American English","sc":"plants for food","ex":{"en":"Sugar cane is an important crop on the island.","cn":"甘蔗是岛上的重要农作物。"}},{"en":"the amount of grain, fruit, etc. that is grown in one season","cn":"（谷物、水果等一季的）收成，产量","g":"[countable]","sc":"plants for food","ex":{"en":"a fall in this year’s coffee crop","cn":"今年咖啡产量的下降"}},{"en":"a group of people who do something at the same time; a number of things that happen at the same time","cn":"（同时做某事的）一群人，一批人；（同时发生的）一些事情","g":"[singular]","sc":"group of people","ex":{"en":"the current crop of trainees","cn":"现在的这批实习生"}},{"en":"a short whip used by horse riders","cn":"（骑手的）短马鞭","g":"[countable]","sc":"whip","ex":{"en":"a riding crop","cn":"骑马用的短马鞭"}},{"en":"a very short hairstyle","cn":"短发","g":"[countable]","sc":"hair","ex":{"en":"She has her hair cut in a short crop.","cn":"她剪了短发。"}},{"en":"hair that is short and thick","cn":"短而密的头发","g":"[singular]","sc":"hair","ex":{"en":"He had a thick crop of black curly hair.","cn":"他有一头浓黑鬈曲的短发。"}},{"en":"a part of a bird’s throat that has the shape of a bag where food is stored before it passes into the stomach","cn":"嗉囊","lab":"specialist","sc":"of bird"},{"en":"to cut somebody’s hair very short","cn":"剪短","g":"[transitive]","sc":"hair","ex":{"en":"closely cropped hair","cn":"剪得很短的头发"},"pos":"verb"},{"en":"to cut off part of a photograph, picture or image","cn":"剪裁，裁切（图片）","g":"[transitive]","lab":"specialist","sc":"image","pos":"verb"},{"en":"to bite off and eat the tops of plants, especially grass","cn":"啃吃（青草或其他植物上面的部分）","g":"[transitive]","sc":"of animals","ex":{"en":"The horses were quietly cropping the grass.","cn":"马儿正在静静地割草。"},"pos":"verb"},{"en":"to produce a crop","cn":"有收成","g":"[intransitive]","sc":"plants","ex":{"en":"The potatoes cropped well this year.","cn":"今年马铃薯丰收。"},"pos":"verb"},{"en":"to use land to grow crops","cn":"种地；种庄稼","g":"[transitive]","sc":"plants","ex":{"en":"The river valley is intensively cropped.","cn":"河谷里种满了庄稼。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"庄稼;作物","en":"Crops are plants such as wheat and potatoes that are grown in large quantities for food.","ex":{"en":"Rice farmers here still plant and harvest their crops by hand","cn":"这里种植水稻的农场主仍是人工种植和收割庄稼。"}},{"pos":"N-COUNT 可数名词","cn":"(谷物或水果的)收成，产量","en":"The plants or fruits that are collected at harvest time are referred to as a crop .","ex":{"en":"Each year it produces a fine crop of fruit","cn":"这里每年水果都大丰收。"}},{"pos":"N-SING 单数名词","cn":"(在一起的)一群（人）;(同时发生的)一些（事情）","en":"You can refer to a group of people or things that have appeared together as a crop of people or things.","ex":{"en":"The present crop of books and documentaries about Marilyn Monroe exploit the thirtieth anniversary of her death","cn":"时下出现的这些有关玛丽莲·梦露的书和纪录片是借她逝世30周年之际推出的。"}},{"pos":"VERB 动词","cn":"结果实;有收成","en":"When a plant crops, it produces fruits or parts which people want.","ex":{"en":"Although these vegetables adapt well to our temperate climate, they tend to crop poorly.","cn":"虽然这些蔬菜作物很适应我们这里温和的气候，它们的收成却很差。"}},{"pos":"VERB 动词","cn":"收割;收获","en":"When you crop something that you have planted, you collect the fruits or parts that you want from it.","ex":{"en":"I started cropping my beans in July.","cn":"我7月份开始收割豆类作物。"}},{"pos":"VERB 动词","cn":"(牛、马等)啃吃(树叶或植物)","en":"When an animal such as a cow or horse crops leaves or plants, it eats them.","ex":{"en":"I let the horse drop his head to crop the spring grass.","cn":"我让马低下头啃吃春天的青草。"}},{"pos":"VERB 动词","cn":"剪短(头发)","en":"To crop someone's hair means to cut it short.","ex":{"en":"She cropped her hair and dyed it blonde.","cn":"她把头发剪短并染成了金黄色。"}},{"pos":"N-COUNT 可数名词","cn":"短发","en":"A crop is a short hairstyle.","ex":{"en":"She had her long hair cut into a boyish crop.","cn":"她把长发剪成了男孩子般的短发。"}},{"pos":"VERB 动词","cn":"剪裁，裁切(照片)","en":"If you crop a photograph, you cut part of it off, in order to get rid of part of the picture or to be able to frame it.","ex":{"en":"I decided to crop the picture just above the water line","cn":"我决定把这张照片水印以下的部分裁掉。"}},{"pos":"","cn":"","en":"the cream of the crop→see: ;"},{"pos":"","cn":"","en":"相关词组：crop up"}]},"media":{"uk":"media/uk/crop__gb_1.mp3","us":"media/us/crop__us_1.mp3"},"examples":[{"en":"I'll be late — something's cropped up at home.","cn":"我要晚一点来，家里突然出了点事。"},{"en":"Sugar is an important crop on the island.","cn":"甘蔗是这个岛上的一种重要作物。"}]},"criticizing":{"lemma":"criticize"},"crazy":{"media":{"uk":"media/uk/crazy__gb_1.mp3","us":"media/us/crazy__us_1.mp3"},"oxford":{"phon":"ˈkreɪzi","pos":"adjective","senses":[{"en":"not sensible; stupid","cn":"不理智的；疯狂的；愚蠢的；傻的","ex":{"en":"Are you crazy? We could get killed doing that.","cn":"你疯了？我们那样做会丧命的。"}},{"en":"very angry","cn":"非常愤怒的","lab":"especially North American English","ex":{"en":"That noise is driving me crazy.","cn":"那噪声吵得我快发疯了。"}},{"en":"very enthusiastic or excited about something","cn":"热衷的；狂热的","ex":{"en":"The crowd went crazy when the band came on stage.","cn":"乐队出场时，观众欣喜若狂。"}},{"en":"liking somebody very much; in love with somebody","cn":"迷恋的；爱上的","ex":{"en":"I've been crazy about him since the first time I saw him.","cn":"我从第一次见到他就爱上他了。"}},{"en":"having a mental illness that makes somebody unable to think or behave normally","cn":"精神失常的；精神错乱的","lab":"often offensive","ex":{"en":"I'd go crazy if I lived here.","cn":"如果我住在这里，我会发疯的。"}},{"en":"an offensive word for a person who has strange ideas or who has a mental illness","cn":"精神失常的","pos":"noun"},{"en":"extremely","cn":"极其；难以置信地；惊人地","ex":{"en":"My job continues to be crazy busy.","cn":"我的工作仍然忙得要命。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不理智的;愚蠢的;古怪的","en":"If you describe someone or something as crazy, you think they are very foolish or strange.","ex":{"en":"People thought they were all crazy to try to make money from manufacturing","cn":"人们认为他们简直是疯了，竟然想从制造业中赚钱。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精神失常的;患精神病的","en":"Someone who is crazy is insane.","ex":{"en":"If I sat home and worried about all this stuff, I'd go crazy","cn":"如果整天坐在家里为这些事情担心，我会疯掉的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热衷的;狂热的","en":"If you are crazy about something, you are very enthusiastic about it. If you are not crazy about something, you do not like it.","ex":{"en":"He's still crazy about both his work and his hobbies","cn":"他对工作和个人爱好依然保持狂热。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"迷恋的;爱上的","en":"If you are crazy about someone, you are deeply in love with them.","ex":{"en":"None of that matters, because we're crazy about each other.","cn":"那些都不重要，因为我们深深地爱着对方。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极度烦恼的;非常生气的","en":"If something or someone makes you crazy or drives you crazy, they make you extremely annoyed or upset.","ex":{"en":"This sitting around is driving me crazy","cn":"老这样坐着无所事事快让我发疯了。"}},{"pos":"PHRASE 短语","cn":"拼命地;疯狂地","en":"You use like crazy to emphasize that something happens to a great degree.","ex":{"en":"The stuff was selling like crazy","cn":"这东西卖疯了。"}}]},"examples":[{"en":"Marie says he went crazy , and smashed the room up.","cn":"玛丽说他气得发疯，把房间里的东西都砸碎了。"},{"en":"He drove like an idiot, passing in the craziest places.","cn":"他像白痴一样净把车往最不可思议的地方开。"}]},"crew":{"media":{"uk":"media/uk/crew__gb_1.mp3","us":"media/us/crew__us_1.mp3"},"oxford":{"phon":"kruː","pos":"noun","senses":[{"en":"all the people working on a ship, plane, etc.","cn":"（轮船、飞机等上面的）全体工作人员","g":"[countable + singular or plural verb]","sc":"on ships and planes","ex":{"en":"crew members","cn":"全体机组人员"}},{"en":"all the people working on a ship, plane etc. except the officers who are in charge","cn":"（轮船、飞机等上面不包括高级职员的）全体船员，全体乘务员","g":"[countable + singular or plural verb]","sc":"on ships and planes","ex":{"en":"the officers and crew","cn":"负责人员和全体乘务员"}},{"en":"a group of people with special skills working together","cn":"技术人员团队；专业团队","g":"[countable + singular or plural verb]","lab":"North American English","sc":"skilled people","ex":{"en":"a film/camera/TV crew","cn":"电影摄制组；摄制组；电视摄制组"}},{"en":"a group of people","cn":"一群（或一帮、一伙）人","g":"[singular]","lab":"usually disapproving","sc":"group","ex":{"en":"The people she invited were a pretty motley crew (= a strange mix of types of people).","cn":"她邀请的人相当杂。"}},{"en":"a team of people who row boats in races","cn":"（赛艇的）划船队员，划船队","g":"[countable + singular or plural verb]","sc":"rowing and sailing","ex":{"en":"a member of the Cambridge crew","cn":"剑桥大学划船队的队员"}},{"en":"the sport of rowing with other people in a boat","cn":"赛艇运动","g":"[uncountable]","lab":"North American English","sc":"rowing and sailing","ex":{"en":"I’m thinking of going out for crew this semester (= joining the rowing team).","cn":"这学期我打算参加赛艇队。"}},{"en":"a person or team of people who sail boats in races or for pleasure (usually not including the captain)","cn":"帆船船员，帆船运动队队员（通常不包含船长）","g":"[countable + singular or plural verb]","sc":"rowing and sailing"},{"en":"to be part of a crew, especially on a ship","cn":"当（尤指船上的）工作人员","ex":{"en":"Normally the boat is crewed by five people.","cn":"通常这条船配有五名船员。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"(飞机、轮船、飞船等上的)全体工作人员","en":"The crew of a ship, an aircraft, or a spacecraft is the people who work on and operate it.","ex":{"en":"The mission for the crew of the space shuttle Endeavour is essentially over","cn":"“奋进号”航天飞机上全体机组人员的任务基本上已经完成了。"}},{"pos":"N-COUNT 可数名词","cn":"(有专门技术的)一组工作人员","en":"A crew is a group of people with special technical skills who work together on a task or project.","ex":{"en":"...a two-man film crew making a documentary","cn":"由两人组成的纪录片摄制组"}},{"pos":"VERB 动词","cn":"在…上当船员","en":"If you crew a boat, you work on it as part of the crew.","ex":{"en":"She was already a keen and experienced sailor, having crewed in both Merlin and Grayling","cn":"在“默林”号和“格雷林”号上工作过以后，她已经是一名头脑敏捷、经验丰富的水手了。"}},{"pos":"N-SING-COLL 单数集合名词","cn":"(不喜欢的)一帮人","en":"You can use crew to refer to a group of people you disapprove of.","ex":{"en":"...the motley crew of failed and aspiring actors who comprised the 'distinguished guests'","cn":"“贵宾”由一群形形色色的演员组成，有的郁郁不得志，有的胸怀抱负"}}]},"examples":[{"en":"I crewed for him on his yacht last summer.","cn":"去年夏天我在他的游艇上当船员。"},{"en":"None of the passengers and crew were injured.","cn":"没有一个乘客和机组人员受伤。"}]},"crimson":{"media":{"uk":"media/uk/crimson__gb_1.mp3","us":"media/us/crimson__us_1.mp3"},"oxford":{"phon":"ˈkrɪmzn","pos":"noun","senses":[{"en":"a dark red colour","cn":"紫红色；深红色"},{"en":"dark red in colour","cn":"深红色的；暗红色的","ex":{"en":"She went crimson (= her face became very red because she was embarrassed).","cn":"她的脸羞得通红。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"深红色;暗红色","en":"Something that is crimson is deep red in colour.","ex":{"en":"...a mass of crimson flowers.","cn":"一大片火红的花"}},{"pos":"ADJ 形容词","cn":"(因生气或害羞)脸通红的","en":"If a person goes crimson, their face becomes red because they are angry or embarrassed.","ex":{"en":"I used to refuse invitations to parties because I knew I'd go crimson every time someone talked to me.","cn":"我过去总是拒绝聚会邀请，因为我知道每当有人和我说话，我就会脸红。"}}]},"examples":[{"en":"She went crimson (= her face became very red because she was embarrassed).","cn":"她的脸变得通红。"},{"en":"The leaves turn crimson in autumn.","cn":"树叶在秋天变成了深红色。"}]},"cricket":{"oxford":{"phon":"ˈkrɪkɪt","pos":"noun","senses":[{"en":"a game played on grass by two teams of 11 players. Players score points (called runs) by hitting the ball with a wooden bat and running between two sets of vertical wooden sticks, called stumps.","cn":"板球（运动）","g":"[uncountable]","ex":{"en":"a cricket match/team/club/ball","cn":"板球比赛／运动队／俱乐部；板球"}},{"en":"a small brown jumping insect that makes a loud high sound by rubbing its wings together","cn":"蟋蟀；蛐蛐","g":"[countable]","ex":{"en":"the chirping of crickets","cn":"蟋蟀的唧唧叫声"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"板球(运动)","en":"Cricket is an outdoor game played between two teams. Players try to score points, called runs, by hitting a ball with a wooden bat.","ex":{"en":"During the summer term we would play cricket at the village ground.","cn":"在夏季学期，我们会在村里的空地上打板球。"}},{"pos":"PHRASE 短语","cn":"不公正;不光明正大;不光彩","en":"If you say that someone's behaviour is not cricket, you mean that they have not behaved fairly.","ex":{"en":"Their treatment of staff is definitely not cricket.","cn":"他们对待员工的方式绝对不公正。"}},{"pos":"N-COUNT 可数名词","cn":"蟋蟀;蛐蛐","en":"A cricket is a small jumping insect that produces short, loud sounds by rubbing its wings together."}]},"media":{"img":["media/pic/sports_comp.jpg","media/thumb/cricket.jpg"],"uk":"media/uk/cricket__gb_1.mp3","us":"media/us/cricket__us_1.mp3"},"examples":[{"en":"a cricket match/team/club/ball","cn":"板球比赛/运动队/俱乐部；板球"},{"en":"the chirping of crickets","cn":"蟋蟀的唧唧叫声"}]},"criminal":{"oxford":{"phon":"ˈkrɪmɪnl","pos":"noun","senses":[{"en":"a person who commits a crime","cn":"犯罪者；违法者；罪犯","lab":"especially North American English","ex":{"en":"a convicted criminal","cn":"已定罪的罪犯"}},{"en":"connected with or involving crime","cn":"犯罪的；犯法的；涉及犯罪的","g":"[usually before noun]","lab":"rather formal or law","ex":{"en":"criminal offences/activities","cn":"刑事犯罪；犯罪活动"},"pos":"adjective"},{"en":"connected to the laws that deal with crime","cn":"刑法的；刑事的","g":"[only before noun]","ex":{"en":"the criminal justice system","cn":"刑事审判制度"},"pos":"adjective"},{"en":"morally wrong","cn":"道德上错误的；不道德的","ex":{"en":"This is a criminal waste of resources.","cn":"这是一种浪费资源的可耻行为。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"罪犯","en":"A criminal is a person who regularly commits crimes.","ex":{"en":"A group of gunmen attacked a prison and set free nine criminals in Moroto.","cn":"一伙持枪歹徒袭击了莫罗托的一所监狱，放走了9名罪犯。"}},{"pos":"ADJ 形容词","cn":"犯罪的;犯法的","en":"Criminal means connected with crime.","ex":{"en":"Her husband faces various criminal charges","cn":"她丈夫面临多项犯罪指控。"}},{"pos":"ADJ 形容词","cn":"罪过的;严重错误的","en":"If you describe an action as criminal, you think it is very wrong or a serious mistake.","ex":{"en":"He said a full-scale dispute involving strikes would be criminal.","cn":"他说如果出现罢工等大规模纠纷那将是极不应该的。"}}]},"media":{"uk":"media/uk/criminal__gb_1.mp3","us":"media/us/criminal__us_1.mp3"},"examples":[{"en":"This is a criminal waste of resources.","cn":"这是一种浪费资源的可耻行为。"},{"en":"Society does not know how to deal with hardened criminals (= people who regularly commit crimes and are not sorry for what they do).","cn":"社会不知道怎样处置惯犯。"}]},"criticize":{"oxford":{"phon":"ˈkrɪtɪsaɪz","pos":"verb","senses":[{"en":"to say that you think somebody/something is bad; to say what you do not like or think is wrong about somebody/something","cn":"批评；批判；挑剔；指责","g":"[intransitive, transitive]","ex":{"en":"All you ever do is criticize!","cn":"你就只知道批评！"}},{"en":"to judge the good and bad qualities of something","cn":"评论；评价","g":"[transitive]","ex":{"en":"We were taught how to criticize poems.","cn":"我们学习了怎样评论诗歌。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"批评;指责;批判","en":"If you criticize someone or something, you express your disapproval of them by saying what you think is wrong with them.","ex":{"en":"His mother had rarely criticized him or any of her children","cn":"他母亲很少指责他或她的任何孩子。"}}]},"media":{"uk":"media/uk/criticize__gb_1.mp3","us":"media/us/criticize__us_1.mp3"},"examples":[{"en":"The government has been criticized for not taking the problem seriously.","cn":"政府因没有认真对待这个问题而受到指责。"},{"en":"The decision was criticized by environmental groups.","cn":"这个决定受到了环保团体的批评。"}]},"credentials":{"oxford":{"phon":"krəˈdenʃlz","pos":"noun","senses":[{"en":"the qualities, training or experience that make you suitable to do something","cn":"资格；资历","ex":{"en":"She has impeccable credentials as a researcher.","cn":"作为一名研究员，她拥有无可挑剔的资历。"}},{"en":"documents such as letters that prove that you are who you claim to be, and can therefore be trusted","cn":"资格证书；证明书；证件","ex":{"en":"to examine somebody’s credentials","cn":"检查某人的资历"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"资格;资历","en":"Someone's credentials are their previous achievements, training, and general background, which indicate that they are qualified to do something.","ex":{"en":"...her credentials as a Bach specialist","cn":"她作为巴赫研究专家的资历"}},{"pos":"N-PLURAL 复数名词","cn":"资格证书;证明书;证件","en":"Someone's credentials are a letter or certificate that proves their identity or qualifications.","ex":{"en":"Britain's new ambassador to Lebanon has presented his credentials to the President.","cn":"英国驻黎巴嫩的新任大使已将国书递交给总统。"}}]},"media":{"uk":"media/uk/credentials__gb_1.mp3","us":"media/us/credentials__us_1.mp3"},"examples":[{"en":"She will first have to establish her leadership credentials.","cn":"她得首先证明她有担任领导的资格。"},{"en":"He has all the credentials for the job.","cn":"他做这项工作完全够格。"}]},"criterion":{"media":{"uk":"media/uk/criterion__gb_1.mp3","us":"media/us/criterion__us_1.mp3"},"oxford":{"phon":"kraɪˈtɪəriən","pos":"noun","senses":[{"en":"a standard or principle by which something is judged, or with the help of which a decision is made","cn":"（评判或作决定的）标准，准则，原则","ex":{"en":"The main criterion is value for money.","cn":"主要的标准是要划算。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(判定的)标准，准则","en":"A criterion is a factor on which you judge or decide something.","ex":{"en":"The most important criterion for entry is that applicants must design and make their own work","cn":"最重要的参赛标准是申请者必须设计并制作自己的作品。"}}]},"examples":[{"en":"What criteria are used for assessing a student's ability?","cn":"用什么标准来评定一个学生的能力？"},{"en":"The main criterion is value for money.","cn":"主要的标准是要划算。"}]},"craftwork":{"media":{"uk":"media/uk/craftwork__gb_1.mp3","us":"media/us/craftwork__us_1.mp3"},"oxford":{"phon":"ˈkrɑːftwɜːk","pos":"noun","senses":[{"en":"work done by a craftsman","cn":"工艺品"}]}},"crowd":{"media":{"uk":"media/uk/crowd__gb_1.mp3","us":"media/us/crowd__us_1.mp3"},"oxford":{"phon":"kraʊd","pos":"noun","senses":[{"en":"a large number of people gathered together in a public place, for example in the streets or at a sports game","cn":"人群；观众","g":"[countable + singular or plural verb]","ex":{"en":"He pushed his way through the crowd.","cn":"他在人群中往前挤。"}},{"en":"a particular group of people","cn":"一伙人；一帮人","g":"[countable + singular or plural verb]","lab":"informal, often disapproving，，","ex":{"en":"Bob introduced her to some of the usual crowd (= people who often meet each other).","cn":"鲍勃把她介绍给常见面的几个朋友。"}},{"en":"ordinary people, not special or unusual in any way","cn":"群众；民众；老百姓；凡夫俗子","g":"[singular]","lab":"sometimes disapproving","ex":{"en":"We all like to think we stand out from the crowd (= are different from and better than other people).","cn":"我们都喜欢认为自己胜人一筹。"}},{"en":"to fill a place so there is little room to move","cn":"挤满；塞满；使…拥挤","ex":{"en":"Thousands of people crowded the narrow streets.","cn":"成千上万的人把狭窄的街道挤得水泄不通。"},"pos":"verb"},{"en":"to fill your mind so that you can think of nothing else","cn":"涌上（心头）；涌入（脑海）","ex":{"en":"Memories crowded his mind.","cn":"往事涌上他的心头。"},"pos":"verb"},{"en":"to stand very close to somebody so that they feel uncomfortable or nervous","cn":"挤，靠近，挤在一旁（以致使人不舒服或紧张）","lab":"informal","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"人群;观众","en":"A crowd is a large group of people who have gathered together, for example to watch or listen to something interesting, or to protest about something.","ex":{"en":"A huge crowd gathered in a square outside the Kremlin walls","cn":"一大群人聚集在克里姆林宫墙外的广场上。"}},{"pos":"N-COUNT 可数名词","cn":"(志趣相投或工作相同的)一伙人，一帮人","en":"A particular crowd is a group of friends, or a set of people who share the same interests or job.","ex":{"en":"All the old crowd have come out for this occasion.","cn":"那些老伙计们都来参加这一庆典。"}},{"pos":"VERB 动词","cn":"聚集在…周围;在…聚拢","en":"When people crowd around someone or something, they gather closely together around them.","ex":{"en":"The hungry refugees crowded around the tractors","cn":"饥饿的难民聚集到拖拉机周围。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)大批涌入","en":"If people crowd into a place or are crowded into a place, large numbers of them enter it so that it becomes very full.","ex":{"en":"Hundreds of thousands of people have crowded into the center of the Lithuanian capital, Vilnius","cn":"几十万人涌入立陶宛首都维尔纽斯的市中心。"}},{"pos":"VERB 动词","cn":"挤满;塞满;使…拥挤","en":"If a group of people crowd a place, there are so many of them there that it is full.","ex":{"en":"Thousands of demonstrators crowded the streets shouting slogans.","cn":"数千名高喊着口号的示威者把街道挤得水泄不通。"}},{"pos":"VERB 动词","cn":"逼近;靠近;围住","en":"If people crowd you, they stand very closely around you trying to see or speak to you, so that you feel uncomfortable.","ex":{"en":"It had been a tense, restless day with people crowding her all the time.","cn":"这是紧张、忙碌的一天，每时每刻都有人围在她身旁。"}},{"pos":"","cn":"","en":"相关词组：crowd in crowd out"}]},"examples":[{"en":"We all crowded into her office to sing ‘Happy Birthday’.","cn":"我们全都涌进她的办公室，唱“祝你生日快乐”。"},{"en":"Thousands of people crowded the narrow streets.","cn":"成千上万的人把狭窄的街道挤得水泄不通。"}]},"crept":{"lemma":"creep","media":{"uk":"media/uk/crept__gb_1.mp3","us":"media/us/crept__us_1.mp3"}},"crisis":{"media":{"uk":"media/uk/crisis__gb_1.mp3","us":"media/us/crisis__us_1.mp3"},"oxford":{"phon":"ˈkraɪsɪs","pos":"noun","senses":[{"en":"a time of great danger, difficulty or doubt when problems must be solved or important decisions must be made","cn":"危机；危急关头","ex":{"en":"an economic/a financial crisis","cn":"经济/金融危机"}},{"en":"a time when a problem, a bad situation or an illness is at its worst point","cn":"危难时刻；病危期","ex":{"en":"Their marriage has reached crisis point.","cn":"他们的婚姻已到了岌岌可危的地步。"}},{"en":"a British charity for homeless people that began in 1972, and that offers education, employment, housing and other services. Each year it also uses empty buildings in large cities to give people shelter, food and clothing in the time around Christmas. This service is run by Crisis at Christmas.","cn":"危机：1972年成立的英国慈善机构，主要为无家可归者提供教育，就业，住房和其他服务。每年，它还在圣诞节期间利用大城市的空楼为人们提供庇护，食物和衣服。该服务在圣诞节由Crisis提供。","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"危机;危急关头","en":"A crisis is a situation in which something or someone is affected by one or more very serious problems.","ex":{"en":"Natural disasters have obviously contributed to the continent's economic crisis","cn":"很显然，自然灾害也是造成该大陆经济危机的原因之一。"}}]},"examples":[{"en":"The business is still in crisis but it has survived the worst of the recession.","cn":"这家公司虽然仍处于危机之中，但已经挺过了经济衰退最严重的日子。"},{"en":"The party was suffering a crisis of confidence among its supporters (= they did not trust it any longer).","cn":"当时这个政党在其支持者中正遭受信任危机。"}]},"craft":{"oxford":{"phon":"krɑːft","pos":"noun","senses":[{"en":"an activity involving a special skill at making things with your hands","cn":"手艺；工艺","g":"[countable, uncountable]","ex":{"en":"traditional crafts like basket-weaving","cn":"像编篮子之类的传统工艺"}},{"en":"all the skills needed for a particular activity","cn":"技巧；技能；技艺","g":"[singular]","ex":{"en":"chefs who learned their craft in top hotels","cn":"在高级酒店学过烹调技艺的厨师"}},{"en":"skill in making people believe what you want them to believe","cn":"诡计；手腕；骗术","g":"[uncountable]","lab":"formal, disapproving，，","ex":{"en":"He knew how to win by craft and diplomacy what he could not gain by force.","cn":"他擅长通过计谋和外交手腕赢得他用武力无法得到的东西。"}},{"en":"a boat or ship","cn":"小船；船","g":"[countable]","lab":"formal","ex":{"en":"Hundreds of small craft bobbed around the liner as it steamed into the harbour.","cn":"班轮驶进港口时，周围的许多小船颠簸起来。"}},{"en":"an aircraft or spacecraft","cn":"飞行器；飞机；航天器；宇宙飞船；航天飞机","g":"[countable]"},{"en":"to make something using special skills, especially with your hands","cn":"（尤指用手工）精心制作","ex":{"en":"All the furniture is crafted from natural materials.","cn":"所有的家具均采用天然材料精心制作而成。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"船;航天器;飞行器;飞机","en":"You can refer to a boat, a spacecraft, or an aircraft as a craft .","ex":{"en":"With great difficulty, the fisherman manoeuvred his small craft close to the reef","cn":"渔夫费了很大的劲才把他的小船划到暗礁旁。"}},{"pos":"N-COUNT 可数名词","cn":"手艺;工艺","en":"A craft is an activity such as weaving, carving, or pottery that involves making things skilfully with your hands.","ex":{"en":"...the arts and crafts of the North American Indians","cn":"北美印第安人的手工艺"}},{"pos":"N-COUNT 可数名词","cn":"（需要技术的）行业，职业","en":"You can use craft to refer to any activity or job that involves doing something skilfully.","ex":{"en":"...the craft of writing","cn":"写作技巧"}},{"pos":"VERB 动词","cn":"精心制作；周密制订","en":"If something is crafted, it is made skilfully.","ex":{"en":"The windows would probably have been crafted in the latter part of the Middle Ages","cn":"这些窗户很可能是中世纪后期精心制作的。"}}]},"media":{"uk":"media/uk/craft__gb_1.mp3","us":"media/us/craft__us_1.mp3"},"examples":[{"en":"He knew how to win by craft and diplomacy what he could not gain by force.","cn":"他擅长于通过计谋和外交手腕赢得他用武力无法得到的东西。"},{"en":"Craft, Design and Technology (= a subject in some British schools)","cn":"工艺、设计与技术（英国某些学校中的科目）"}]},"credit":{"media":{"uk":"media/uk/credit__gb_1.mp3","us":"media/us/credit__us_1.mp3"},"oxford":{"phon":"ˈkredɪt","pos":"noun","senses":[{"en":"an arrangement that you make, with a shop for example, to pay later for something you buy","cn":"赊购；赊欠","g":"[uncountable]","sc":"buy now–pay later","ex":{"en":"to get credit","cn":"允许赊购"}},{"en":"money that you borrow from a bank; a loan","cn":"（从银行借的）借款；贷款","g":"[uncountable, countable]","lab":"informal","sc":"money borrowed","ex":{"en":"The bank refused further credit to the company.","cn":"银行拒绝再给那家公司提供贷款。"}},{"en":"the status of being trusted to pay back money to somebody who lends it to you","cn":"（偿还欠款的）信誉，信用","g":"[uncountable]","sc":"money borrowed","ex":{"en":"Her credit isn't good anywhere now.","cn":"她借钱不还，弄得声名狼藉。"}},{"en":"money that you have in your bank account; if you or your bank account are in credit, there is money in the account","cn":"结余","g":"[uncountable]","sc":"money in bank","ex":{"en":"You have a credit balance of £250.","cn":"你有 250 英镑的存款余额。"}},{"en":"a sum of money paid into a bank account; a record of the payment","cn":"（付入银行账户的）存款金额，贷记","g":"[countable, uncountable]","sc":"money in bank","ex":{"en":"a credit of £50","cn":"50 英镑的贷记"}},{"en":"the right to use a service up to a certain limit, paid for in advance","cn":"信用额度","g":"[uncountable]","sc":"money paid in advance","ex":{"en":"My phone's run out of credit.","cn":"我的电话欠费了。"}},{"en":"a payment that somebody has a right to for a particular reason","cn":"有权索要的款项","g":"[countable, uncountable]","lab":"specialist","sc":"money back","ex":{"en":"The child tax credit is subject to strict income limitations.","cn":"儿童税收抵免受到严格的收入限制。"}},{"en":"praise or approval because you are responsible for something good that has happened","cn":"赞扬；称赞；认可","g":"[uncountable]","sc":"praise","ex":{"en":"to get/deserve/receive/take/claim the credit","cn":"获得／值得／接受／索取称赞"}},{"en":"a person or thing whose qualities or achievements are praised and who therefore earns respect for somebody/something else","cn":"为…赢得荣誉的人（或事物）","g":"[singular]","sc":"praise","ex":{"en":"She is a credit to the school.","cn":"她为学校赢得了荣誉。"}},{"en":"the act of mentioning somebody who worked on a project such as a film or a television programme","cn":"（电影或电视节目演职人员的）片头字幕，片尾字幕","g":"[countable, usually plural]","sc":"movie/TV programme","ex":{"en":"She was given a programme credit for her work on the costumes for the play.","cn":"她为这出戏准备服装，被列入剧目制作人员名单。"}},{"en":"a film, play, television programme, etc. that somebody has worked on","cn":"参与制作的（影视）作品","sc":"movie/TV programme","ex":{"en":"His film credits included ‘The Witches’ and ‘Halloween III’.","cn":"他参与制作的电影包括《女巫》和《万圣节 3》。"}},{"en":"a unit of study at a college or university (in the US, also at a school); the fact of having successfully completed a unit of study","cn":"（大学以及美国中小学的）学习单元，学分","g":"[countable]","sc":"unit of study","ex":{"en":"My math class is worth three credits.","cn":"我的数学课为三个学分。"}},{"en":"to add an amount of money to somebody’s bank account","cn":"（给银行账户）存入金额；把…记入贷方；贷记（银行账户）","sc":"put money in bank","ex":{"en":"They credited my account two days later.","cn":"两天后他们就记入我的账户了。"},"pos":"verb"},{"en":"to believe or say that somebody is responsible for doing something, especially something good","cn":"认为是…的功劳；把…归于","g":"[usually passive]","sc":"with achievement","ex":{"en":"All the contributors are credited on the title page.","cn":"所有撰稿人的姓名均刊登在扉页上。"},"pos":"verb"},{"en":"to believe that somebody/something has a particular good quality or feature","cn":"认为…有（良好的品质或特点）","sc":"with quality","ex":{"en":"I credited you with a little more sense.","cn":"我认为你更有见识。"},"pos":"verb"},{"en":"to believe that somebody/something is of a particular type or quality","cn":"认为…属（某种类或性质）","g":"[usually passive]","sc":"with quality","ex":{"en":"The cheetah is generally credited as the world's fastest animal.","cn":"普遍认为猎豹是世界上跑得最快的动物。"},"pos":"verb"},{"en":"to believe something, especially something surprising or unexpected","cn":"相信（尤指令人惊奇或意外的事物）","lab":"British English","sc":"believe","ex":{"en":"He's been promoted—would you credit it?","cn":"他被擢升了，你相信吗？"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"赊购;赊欠","en":"If you are allowed credit, you are allowed to pay for goods or services several weeks or months after you have received them.","ex":{"en":"The group can't get credit to buy farming machinery","cn":"这些人无法赊购到农用机械。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"结余;存款","en":"If someone or their bank account is in credit, their bank account has money in it.","ex":{"en":"The idea that I could be charged when I'm in credit makes me very angry","cn":"想到账户里有余额时还要收费，我就非常气愤。"}},{"pos":"VERB 动词","cn":"(给账户)存(钱);把…记入贷方","en":"When a sum of money is credited to an account, the bank adds that sum of money to the total in the account.","ex":{"en":"She noticed that only $80,000 had been credited to her account","cn":"她注意到自己的账户里只存进了80,000美元。"}},{"pos":"N-COUNT 可数名词","cn":"存款金额;贷记","en":"A credit is a sum of money which is added to an account.","ex":{"en":"The statement of total debits and credits is known as a balance.","cn":"总借记和总贷记的结算即账户余额。"}},{"pos":"N-COUNT 可数名词","cn":"(给某人的)一笔钱","en":"A credit is an amount of money that is given to someone.","ex":{"en":"Senator Bill Bradley outlined his own tax cut, giving families $350 in tax credits per child","cn":"比尔·布拉德利参议员概述了自己的减税计划，提出每个孩子可为家庭减免350美元的课税。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赞扬;称赞;认可","en":"If you get the credit for something good, people praise you because you are responsible for it, or are thought to be responsible for it.","ex":{"en":"We don't mind who gets the credit so long as we don't get the blame","cn":"谁受到表扬无所谓，只要我们不挨批就好。"}},{"pos":"VERB 动词","cn":"认为是…的功劳;把…归于","en":"If people credit someone with an achievement or if it is credited to them, people say or believe that they were responsible for it.","ex":{"en":"The staff are crediting him with having saved Hythe's life","cn":"职员们称赞他救了海丝的命。"}},{"pos":"VERB 动词","cn":"认为…有(某种品质)","en":"If you credit someone with a quality, you believe or say that they have it.","ex":{"en":"I wonder why you can't credit him with the same generosity of spirit","cn":"我想知道你为什么不认为他具有同样崇高的思想境界。"}},{"pos":"N-SING 单数名词","cn":"为…赢得好感的人(或事物)","en":"If you say that someone is a credit to someone or something, you mean that their qualities or achievements will make people have a good opinion of the person or thing mentioned.","ex":{"en":"He is one of the greatest British players of recent times and is a credit to his profession.","cn":"他是近代英国最伟大的运动员之一，是这一体育运动的骄傲。"}},{"pos":"VERB 动词","cn":"相信;信任","en":"If you cannot credit something, you cannot believe that it is true.","ex":{"en":"Roosevelt either did not learn of the scandal or refused to credit what he heard","cn":"罗斯福要么是不知道那桩丑闻，要么是不相信他所听到的。"}},{"pos":"N-COUNT 可数名词","cn":"演职员表;摄制人员名单","en":"The list of people who helped to make a film, a CD, or a television programme is called the credits .","ex":{"en":"The star Marlon Brando wants his name removed from the credits.","cn":"影星马龙·白兰度要求把他的名字从演职员表中删掉。"}},{"pos":"N-COUNT 可数名词","cn":"(某些大学获得学位所必需的)学分，学习单元","en":"A credit is a successfully completed part of a higher education course. At some universities and colleges you need a certain number of credits to be awarded a degree."},{"pos":"PHRASE 短语","cn":"使值得赞扬(或仰慕)","en":"If you say that something does someone credit, you mean that they should be praised or admired because of it.","ex":{"en":"You're a nice girl, Lettie, and your kind heart does you credit.","cn":"你是个好女孩儿，莱蒂，你的善良值得称赞。"}},{"pos":"PHRASE 短语","cn":"（某人的成绩或优点）值得表扬，应予肯定","en":"If you say 'credit where credit's due', you are admitting that you ought to praise someone for something that they have done or for a good quality that they possess.","ex":{"en":"His gift was an extremely kind gesture. Credit where credit's due.","cn":"他的礼物是很友好的表示，这值得称赞。"}},{"pos":"PHRASE 短语","cn":"相信…具有(某种优良品质);称赞;认可","en":"To give someone credit for a good quality means to believe that they have it.","ex":{"en":"Bratbakk had more ability than the media gave him credit for.","cn":"布拉特巴克比媒体称赞的要有才华。"}},{"pos":"PHRASE 短语","cn":"(常用于提出缺点之后)就优点而言","en":"You say on the credit side in order to introduce one or more good things about a situation or person, usually when you have already mentioned the bad things about them.","ex":{"en":"On the credit side, he's always been wonderful with his mother.","cn":"就优点而言，他对母亲一直很孝顺。"}},{"pos":"PHRASE 短语","cn":"值得赞扬","en":"If something is to someone's credit, they deserve praise for it.","ex":{"en":"She had managed to pull herself together and, to her credit, continued to look upon life as a positive experience","cn":"她已经努力振作起来，而且值得称赞的是，她仍然积极乐观地看待生活。"}},{"pos":"PHRASE 短语","cn":"(成就)归于…；在…名下","en":"If you already have one or more achievements to your credit, you have achieved them.","ex":{"en":"I have twenty novels and countless magazine stories to my credit.","cn":"我著有20部小说，还在杂志上发表了无数篇文章。"}}]},"examples":[{"en":"I can't take all the credit for the show's success — it was a team effort.","cn":"演出成功不能都算成我一个人的功劳，这是集体努力的结果。"},{"en":"She was given a programme credit for her work on the costumes for the play.","cn":"她为这出戏准备服装，被列入剧目制作人员名单。"}]},"cross-check":{"oxford":{"phon":"ˌkrɒs ˈtʃek","pos":"verb","senses":[{"en":"to make sure that information, figures, etc. are correct by using a different method or system to check them","cn":"（用不同的方法或系统）核查，核对；交叉检查","ex":{"en":"Cross-check your answers with a calculator.","cn":"用计算器核对一下你的答案。"}},{"en":"an act of making sure that information, figures, etc. are correct by using a different method or system to check them","cn":"（用不同的方法或系统）核查，核对；交叉检查","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（用不同方法或从不同出处）反复核对,交叉检查","en":"If you cross-check information, you check that it is correct using a different method or source from the one originally used to obtain it.","ex":{"en":"You have to scrupulously check and cross-check everything you hear","cn":"你必须仔细检查并多方核对你所听到的每一件事。"}}]},"media":{"uk":"media/uk/cross_check_1_gb_1.mp3","us":"media/us/cross_check_1_us_1.mp3"},"examples":[{"en":"Baggage should be cross-checked against the names of individual passengers.","cn":"必须再把行李与各位旅客的姓名核对一遍。"},{"en":"Cross-check your answers with a calculator.","cn":"用计算器核对一下你的答案。"}]},"critical":{"media":{"uk":"media/uk/critical__gb_1.mp3","us":"media/us/critical__us_1.mp3"},"oxford":{"phon":"ˈkrɪtɪkl","pos":"adjective","senses":[{"en":"saying what you think is bad about somebody/something","cn":"批评的；挑剔的","sc":"expressing disapproval","ex":{"en":"You should just ignore any critical comments.","cn":"你应该不理睬任何批评意见。"}},{"en":"extremely important because a future situation will be affected by it","cn":"极重要的；关键的；至关紧要的","sc":"important","ex":{"en":"Industry leaders are working together to address this critical issue.","cn":"行业领导者正在共同努力解决这一关键问题。"}},{"en":"serious, uncertain and possibly dangerous","cn":"安危攸关的；危急的","sc":"serious/dangerous","ex":{"en":"One of the victims of the fire remains in a critical condition.","cn":"大火的一位受害者依然病情危急。"}},{"en":"involving making fair, careful judgements about the good and bad qualities of somebody/something","cn":"有判断力的；判断公正（或审慎）的","sc":"making careful judgements","ex":{"en":"Students are encouraged to develop critical thinking instead of accepting opinions without questioning them.","cn":"鼓励学生培养批判性思维，而非不加质疑地接受观点。"}},{"en":"according to the judgement of critics of art, music, literature, etc.","cn":"根据（艺术、音乐、文学等）评论家的","g":"[only before noun]","sc":"of art/music/books, etc.","ex":{"en":"the film director’s greatest critical success","cn":"那位电影导演从评论界获得的最大成功"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极重要的;关键的","en":"A critical time, factor, or situation is extremely important.","ex":{"en":"The incident happened at a critical point in the campaign","cn":"该事件发生在竞选活动的关键时期。"}},{"pos":"ADJ 形容词","cn":"(局势)严重的，有危险的","en":"A critical situation is very serious and dangerous.","ex":{"en":"The German authorities are considering an airlift if the situation becomes critical","cn":"如果局势变得危急，德国当局将考虑实施空运。"}},{"pos":"ADJ 形容词","cn":"(病情)危急的，严重的","en":"If a person is critical or in a critical condition in hospital, they are seriously ill.","ex":{"en":"Ten of the injured are said to be in critical condition.","cn":"据说伤者中有10人情况危急。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"批评的;挑剔的","en":"To be critical of someone or something means to criticize them.","ex":{"en":"His report is highly critical of the trial judge","cn":"他在报告中对主审法官有颇多批评。"}},{"pos":"ADJ 形容词","cn":"评判性的;审慎的","en":"A critical approach to something involves examining and judging it carefully.","ex":{"en":"We need to become critical text-readers","cn":"我们需要培养对文章的评判能力。"}},{"pos":"ADJ 形容词","cn":"评论家的;评论界的","en":"If something or someone receives critical acclaim, critics say that they are very good.","ex":{"en":"The film met with considerable critical and public acclaim","cn":"该影片受到了影评人和公众的高度评价。"}}]},"examples":[{"en":"Students are encouraged to develop critical thinking instead of accepting opinions without questioning them.","cn":"要鼓励学生培养判断力，而非不懂提问，只知接收意见。"},{"en":"In her day she never received the critical acclaim (= praise from the critics ) she deserved.","cn":"她一生从未受到过评论家应当给她的赞扬。"}]},"crow":{"oxford":{"phon":"krəʊ","pos":"noun","senses":[{"en":"a large bird, completely or mostly black, with a rough unpleasant call","cn":"乌鸦"},{"en":"a sound like that of a rooster (= an adult male chicken) crowing","cn":"（像雄鸡的）啼叫声，喔喔叫声","ex":{"en":"She gave a little crow of triumph.","cn":"她轻轻地发出了胜利的欢呼声。"}},{"en":"to make repeated loud high sounds, especially early in the morning","cn":"（尤指在清晨）啼叫，打鸣","g":"[intransitive]","ex":{"en":"A cock began to crow.","cn":"一只公鸡开始打鸣。"},"pos":"verb"},{"en":"to talk too proudly about something you have achieved, especially when somebody else has been unsuccessful","cn":"（尤指在其他人不成功时）扬扬自得地夸口，自鸣得意","g":"[intransitive, transitive]","lab":"disapproving","ex":{"en":"He won't stop crowing about his victory.","cn":"他滔滔不绝地夸耀自己的胜利。"},"pos":"verb"},{"en":"to make happy sounds","cn":"欢叫","g":"[intransitive]","lab":"British English","ex":{"en":"She gave the purse to Ruby, who crowed with delight.","cn":"她把钱包给了鲁比，鲁比高兴得叫了起来。"},"pos":"verb"},{"en":"a member of a native North American people, many of whom live in the US state of Montana","cn":"克劳人（美洲土著，很多居于美国蒙大拿州）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"乌鸦","en":"A crow is a large black bird which makes a loud, harsh noise."},{"pos":"VERB 动词","cn":"(公鸡)打鸣，啼叫","en":"When a cock crows, it makes a loud sound, often early in the morning.","ex":{"en":"The cock crows and the dawn chorus begins.","cn":"雄鸡报晓，鸟儿欢叫。"}},{"pos":"VERB 动词","cn":"对…洋洋自得;为…自鸣得意","en":"If you say that someone is crowing about something they have achieved or are pleased about, you disapprove of them because they keep telling people proudly about it.","ex":{"en":"Edwards is already crowing about his assured victory","cn":"爱德华兹已经在为自己确定无疑的胜利自鸣得意了。"}},{"pos":"VERB 动词","cn":"欢叫;高兴地说","en":"If someone crows, they make happy sounds or say something happily.","ex":{"en":"She was crowing with delight","cn":"她欢呼雀跃。"}},{"pos":"PHRASE 短语","cn":"成直线地;笔直地","en":"If you say that a place is a particular distance away as the crow flies, you mean that it is that distance away measured in a straight line.","ex":{"en":"I live at Mesa, Washington, about 10 miles as the crow flies from Hanford.","cn":"我住在华盛顿的梅萨，到汉福德的直线距离约为10英里。"}}]},"media":{"uk":"media/uk/crow__gb_1.mp3","us":"media/us/crow__us_1.mp3"},"examples":[{"en":"He crowed that they had sold out in one day.","cn":"他洋洋得意地炫耀他们一天内就全部售完了。"},{"en":"‘I've won, I've won!’ she crowed. “","cn":"我赢了，我赢了！”她得意忘形地叫道。"}]},"crops":{"lemma":"crop"},"creation":{"media":{"uk":"media/uk/creation__gb_1.mp3","us":"media/us/creation__us_1.mp3"},"oxford":{"phon":"kriˈeɪʃn","pos":"noun","senses":[{"en":"the act or process of making something that is new, or of causing something to exist that did not exist before","cn":"创造；创建","g":"[uncountable]","ex":{"en":"Job creation needs to be the top priority.","cn":"当务之急是创造就业机会。"}},{"en":"a thing that somebody has made, especially something that shows ability or imagination","cn":"作品；创作","g":"[countable]","lab":"often humorous","ex":{"en":"a literary creation","cn":"文学作品"}},{"en":"the making of the world, especially by God as described in the Bible","cn":"（尤指《圣经》所述由上帝）创造天地","g":"[singular]"},{"en":"the world and all the living things in it","cn":"世界；天地万物","g":"[uncountable]","ex":{"en":"We need to consider how we care for all creation.","cn":"我们需要考虑如何照顾所有的创造物。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(许多宗教中指上帝的)创世，创造天地","en":"In many religions, creation is the making of the universe, earth, and creatures by God.","ex":{"en":"...the Creation of the universe as told in Genesis Chapter One","cn":"《创世记》第一章所述的上帝创造世界万物"}},{"pos":"N-UNCOUNT 不可数名词","cn":"世界;天地万物；宇宙","en":"People sometimes refer to the whole universe as creation ."},{"pos":"N-COUNT 可数名词","cn":"创造物;(尤指)艺术作品，富于想象力的作品","en":"You can refer to something that someone has made as a creation, especially if it shows skill, imagination, or artistic ability.","ex":{"en":"The bathroom is entirely my own creation","cn":"浴室完全是由我设计的。"}}]},"examples":[{"en":"The cake was a delicious creation of sponge, cream and fruit.","cn":"这蛋糕是用松糕、奶油和水果制作的，又好吃，又好看。"},{"en":"He had been with the company since its creation in 1989.","cn":"他从 1989 年公司成立以来就一直在那里工作。"}]},"crying":{"media":{"uk":"media/uk/crying__gb_1.mp3","us":"media/us/crying__us_1.mp3"},"oxford":{"phon":"ˈkraɪɪŋ","pos":"noun","senses":[{"en":"the sound or act of crying","cn":"哭泣声；哭泣","ex":{"en":"the crying of terrified children","cn":"小孩受了惊吓的哭声"}}]},"collins":{"senses":[{"pos":"PHRASE 短语","cn":"迫切的需要","en":"If you say that there is a crying need for something, you mean that there is a very great need for it.","ex":{"en":"There is a crying need for more magistrates from the ethnic minority communities.","cn":"亟须更多来自少数民族群体的治安官。"}},{"pos":"PHRASE 短语","cn":"让人不安的事;使人烦恼的事;奇耻大辱","en":"You can say that something is a crying shame if you are annoyed and upset about it.","ex":{"en":"It's a crying shame that police have to put up with these mindless attacks.","cn":"令人气愤的是，警察不得不忍受这些无知的批评。"}}]},"examples":[{"en":"It's a crying shame to waste all that food.","cn":"把那些食物都浪费了，真是太不像话了。"},{"en":"the crying of terrified children","cn":"小孩受了惊吓的哭声"}],"base":"cry"},"crucial":{"media":{"uk":"media/uk/crucial__gb_1.mp3","us":"media/us/crucial__us_1.mp3"},"oxford":{"phon":"ˈkruːʃl","pos":"adjective","senses":[{"en":"extremely important, because it will affect other things","cn":"至关重要的；关键性的","ex":{"en":"The next few weeks are going to be crucial.","cn":"今后几个星期是关键。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"至关重要的;关键性的","en":"If you describe something as crucial, you mean it is extremely important.","ex":{"en":"He had administrators under him but took the crucial decisions himself","cn":"他手下有管理人员，但重要的决策仍由他自己来做。"}}]},"examples":[{"en":"Parents play a crucial role in preparing their child for school.","cn":"父母对孩子做好上学的准备起着至关重要的作用。"},{"en":"Winning this contract is crucial to the success of the company.","cn":"赢得这份合同对这家公司的成败至关重要。"}]},"crime":{"media":{"uk":"media/uk/crime__gb_1.mp3","us":"media/us/crime__us_1.mp3"},"oxford":{"phon":"kraɪm","pos":"noun","senses":[{"en":"activities that involve breaking the law","cn":"犯罪活动；不法行为","g":"[uncountable]","lab":"especially North American English","ex":{"en":"This month's figures show an increase in violent crime.","cn":"本月数字显示暴力犯罪在增加。"}},{"en":"an illegal act or activity that can be punished by law","cn":"罪；罪行","g":"[countable]","lab":"British English","ex":{"en":"There is no proof that he committed a crime (= did something illegal).","cn":"没有证据表明他犯了罪（=做了违法的事情）。"}},{"en":"an act that you think is morally wrong or is a big mistake","cn":"不道德的行为；罪过","g":"[singular]","lab":"informal","ex":{"en":"It's a crime to waste so much money.","cn":"浪费这么多钱是一种罪过。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"犯罪活动;罪行","en":"A crime is an illegal action or activity for which a person can be punished by law.","ex":{"en":"He and Lieutenant Cassidy were checking the scene of the crime","cn":"他和卡西迪中尉正在勘查犯罪现场。"}},{"pos":"N-COUNT 可数名词","cn":"罪过;严重错误","en":"If you say that doing something is a crime, you think it is very wrong or a serious mistake.","ex":{"en":"A language is a finely tuned instrument which it is a crime to damage","cn":"语言是一种精心调试的乐器，破坏它就是一种罪过。"}}]},"examples":[{"en":"Stores spend more and more on crime prevention every year.","cn":"商店每年在防止犯罪方面的花费越来越多。"},{"en":"The massacre was a crime against humanity.","cn":"这场大屠杀是一桩反人类的罪行。"}]},"critic":{"media":{"uk":"media/uk/critic__gb_1.mp3","us":"media/us/critic__us_1.mp3"},"oxford":{"phon":"ˈkrɪtɪk","pos":"noun","senses":[{"en":"a person who expresses opinions about the good and bad qualities of books, music, etc.","cn":"批评家；评论家；评论员","ex":{"en":"a film/an art/a music critic","cn":"电影／艺术／音乐评论家"}},{"en":"a person who expresses dislike of somebody/something and talks about their bad qualities, especially publicly","cn":"批评者；挑剔的人","ex":{"en":"She has become one of the ruling party's most outspoken critics.","cn":"她成为最直言不讳地批评执政党的人之一。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"批评家;评论家;评论员","en":"A critic is a person who writes about and expresses opinions about things such as books, films, music, or art.","ex":{"en":"Mather was film critic on the Daily Telegraph for many years","cn":"马瑟多年来一直担任《每日电讯报》的影评人。"}},{"pos":"N-COUNT 可数名词","cn":"批评者;反对者","en":"Someone who is a critic of a person or system disapproves of them and criticizes them publicly.","ex":{"en":"The newspaper has been the most consistent critic of the government","cn":"一直以来，该报批评政府的立场最为坚定。"}}]},"examples":[{"en":"She is one of the ruling party's most outspoken critics.","cn":"她是最直言不讳地批评执政党的其中一人。"},{"en":"a critic of private health care","cn":"对私营医疗保健服务持批评态度的人"}]},"crushing":{"oxford":{"phon":"ˈkrʌʃɪŋ","pos":"adjective","senses":[{"en":"used to emphasize how bad or severe something is","cn":"（强调糟糕或严重的程度）惨重的，毁坏性的","ex":{"en":"a crushing defeat in the election","cn":"在选举中的惨败"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"惨重的;毁灭性的;严重的","en":"A crushing defeat, burden, or disappointment is a very great or severe one.","ex":{"en":"...since their crushing defeat in the local elections.","cn":"自从他们在地方选举中惨败后"}}]},"media":{"uk":"media/uk/crushing__gb_1.mp3","us":"media/us/crushing__us_1.mp3"},"examples":[{"en":"The shipyard has been dealt another crushing blow with the failure to win this contract.","cn":"由于未能赢得这份合同，造船厂又遭到了一次惨重的打击。"},{"en":"a crushing defeat in the election","cn":"在选举中的惨败"}],"base":"crush"},"criticism":{"oxford":{"phon":"ˈkrɪtɪsɪzəm","pos":"noun","senses":[{"en":"the act of expressing disapproval of somebody/something and opinions about their faults or bad qualities; a statement showing this disapproval","cn":"批评；批判；责备；指责","g":"[uncountable, countable]","ex":{"en":"to draw/face/receive criticism","cn":"受到/面对/接受批评"}},{"en":"the work or activity of making fair, careful judgements about the good and bad qualities of somebody/something, especially books, music, etc.","cn":"（尤指对书、音乐等的）评论文章，评论","g":"[uncountable]","ex":{"en":"She has written several works of literary criticism.","cn":"她已经写了几本文学批评的著作。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"批评;批判;指责","en":"Criticism is the action of expressing disapproval of something or someone. A criticism is a statement that expresses disapproval.","ex":{"en":"This policy had repeatedly come under strong criticism on Capitol Hill","cn":"该政策在美国国会屡遭强烈批评。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(对书、戏剧等的)评论","en":"Criticism is a serious examination and judgment of something such as a book or play.","ex":{"en":"She has published more than 20 books including novels, poetry and literary criticism.","cn":"她已出版了包括小说、诗歌和文学评论在内的20多部著作。"}}]},"media":{"uk":"media/uk/criticism__gb_1.mp3","us":"media/us/criticism__us_1.mp3"},"examples":[{"en":"My only criticism of the house is that it is on a main road.","cn":"我对这座房子唯一的不满是它处于一条大路上。"},{"en":"There was widespread criticism of the government's handling of the disaster.","cn":"政府对灾难的处理方式遭到了普遍的批评。"}]},"crammed":{"media":{"uk":"media/uk/crammed__gb_1.mp3","us":"media/us/crammed__us_1.mp3"},"oxford":{"phon":"kræmd","pos":"adjective","senses":[{"en":"full of things or people","cn":"塞满的；挤满的","ex":{"en":"All the shelves were crammed with books.","cn":"所有的架子上都堆满了书。"}},{"en":"if people are crammed into a place, there is not much room for them in it","cn":"拥挤不堪","g":"[not before noun]","ex":{"en":"We were crammed four to an office.","cn":"我们四个人挤在一间办公室里。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"挤满的;塞满的","en":"If a place is crammed with things or people, it is full of them, so that there is hardly room for anything or anyone else.","ex":{"en":"The house is crammed with priceless furniture and works of art","cn":"房子里摆满了昂贵的家具和艺术品。"}},{"pos":"ADJ 形容词","cn":"拥挤不堪的","en":"If people or things are crammed into a place or vehicle, it is full of them.","ex":{"en":"Between two and three thousand refugees were crammed into the church buildings.","cn":"有两三千难民挤进教堂内。"}}]},"examples":[{"en":"We were crammed four to an office.","cn":"我们四个人挤在一间办公室里。"},{"en":"All the shelves were crammed with books.","cn":"所有的架子上都堆满了书。"}]},"crude":{"media":{"uk":"media/uk/crude__gb_1.mp3","us":"media/us/crude__us_1.mp3"},"oxford":{"phon":"kruːd","pos":"adjective","senses":[{"en":"in its natural state, before it has been processed or refined","cn":"天然的；自然的","g":"[usually before noun]","ex":{"en":"crude oil/metal","cn":"原油；未经提炼的金属"}},{"en":"not changed or corrected","cn":"原始的；未经加工的","lab":"statistics","ex":{"en":"the crude mortality rate","cn":"概约死亡率。"}},{"en":"offensive or rude, especially about sex","cn":"冒犯的，粗俗的，粗鲁的（尤其有关性的）","ex":{"en":"crude jokes/language","cn":"粗俗的笑话／语言"}},{"en":"simple and not very accurate but giving a general idea of something","cn":"粗略的；简略的；大概的","ex":{"en":"In crude terms, a heart attack is a plumbing problem in blood vessels around the heart.","cn":"简而言之，心脏病发作是心脏周围血管的管道问题。"}},{"en":"simply made, not showing much skill or attention to detail","cn":"粗糙的；粗制的","ex":{"en":"a crude drawing of a face","cn":"脸部的略图"}},{"en":"oil in its natural state, before it has been processed or refined","cn":"原油；石油","ex":{"en":"50 000 barrels of crude","cn":"5 万桶原油"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗略的;简略的;大概的","en":"A crude method or measurement is not exact or detailed, but may be useful or correct in a rough, general way.","ex":{"en":"Standard measurements of blood pressure are an important but crude way of assessing the risk of heart disease or strokes","cn":"标准的血压测量是评估患心脏病或中风几率的一个重要但不精确的方法。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗糙的;简陋的","en":"If you describe an object that someone has made as crude, you mean that it has been made in a very simple way or from very simple parts.","ex":{"en":"...crude wooden boxes.","cn":"简陋的木盒子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冒犯的;粗鲁的;不精明的","en":"If you describe someone as crude, you disapprove of them because they speak or behave in a rude, offensive, or unsophisticated way.","ex":{"en":"Nev! Must you be quite so crude?","cn":"尼夫！你非得那么粗俗吗？"}},{"pos":"ADJ 形容词","cn":"天然的;自然的","en":"Crude substances are in a natural or unrefined state, and have not yet been used in manufacturing processes.","ex":{"en":"...8.5 million tonnes of crude steel.","cn":"850万吨粗钢"}},{"pos":"N-MASS 物质名词","cn":"同 crude oil","en":"Crude is the same as crude oil ."}]},"examples":[{"en":"In crude terms, the causes of mental illness seem to be of three main kinds.","cn":"简略地说，导致精神病的原因看起来主要有三种。"},{"en":"To put it crudely, the poor are going without food so that the rich can drive cars.","cn":"简而言之，穷人无饭吃，富人才有车开。"}]},"crossing":{"media":{"uk":"media/uk/crossing__gb_1.mp3","us":"media/us/crossing__us_1.mp3"},"oxford":{"phon":"ˈkrɒsɪŋ","pos":"noun","senses":[{"en":"a place where you can safely cross a road, a river, etc., or from one country to another","cn":"（通过道路、河流等的）安全通行处；人行横道；渡口；（从一国到另一国的）过境处","ex":{"en":"The child was killed when a car failed to stop at the crossing.","cn":"汽车在人行横道线未能停车，结果把小孩撞死了。"}},{"en":"a journey across a sea or a wide river","cn":"（海洋或宽阔江河的）横渡","ex":{"en":"a three-hour ferry crossing","cn":"三小时的轮渡"}},{"en":"an act of going from one side to another","cn":"穿越；横越","ex":{"en":"attempted crossings of the border","cn":"穿越边境未遂"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"横渡","en":"A crossing is a journey by boat or ship to a place on the other side of a sea, river, or lake.","ex":{"en":"He made the crossing from Cape Town to Sydney in just over twenty-six days","cn":"他在短短26天内从开普敦横渡到悉尼。"}},{"pos":"N-COUNT 可数名词","cn":"(道路的)十字路口;(线的)交叉点","en":"A crossing is a place where two roads, paths, or lines cross."},{"pos":"N-COUNT 可数名词","cn":"同 pedestrian crossing","en":"A crossing is the same as a pedestrian crossing .","ex":{"en":"A car hit her on a crossing.","cn":"一辆汽车在人行横道上撞了她。"}},{"pos":"N-COUNT 可数名词","cn":"同 grade crossing 或 level crossing","en":"A crossing is the same as a grade crossing or a level crossing ."}]},"examples":[{"en":"The child was killed when a car failed to stop at the crossing.","cn":"汽车在人行横道线未能停车，结果把小孩撞死了。"},{"en":"The next crossing point is a long way downstream.","cn":"下一个渡口在下游方向很远的地方。"}],"base":"cross"},"crust":{"media":{"uk":"media/uk/crust__gb_1.mp3","us":"media/us/crust__us_1.mp3"},"oxford":{"phon":"krʌst","pos":"noun","senses":[{"en":"the hard outer surface of bread","cn":"面包皮","ex":{"en":"sandwiches with the crusts cut off","cn":"切掉面包皮的三明治"}},{"en":"a layer of pastry, especially on top of a pie","cn":"糕饼（尤指馅饼）酥皮","ex":{"en":"Bake until the crust is golden.","cn":"把糕饼烤至外皮呈金黄色。"}},{"en":"the outer layer of rock that forms the surface of the earth or another planet","cn":"地壳；（星球的）外壳","ex":{"en":"the earth’s crust","cn":"地壳"}},{"en":"a hard layer or surface, especially above or around something soft or liquid","cn":"（尤指软物或液体上面、周围的）硬层，硬表面","ex":{"en":"a thin crust of ice","cn":"一层薄冰"}},{"en":"to form a hard layer; to cover something with a hard layer","cn":"结硬皮；用外壳覆盖；生痂儿","ex":{"en":"Water was beginning to crust over with ice as temperatures dropped.","cn":"随着气温下降，水面上结了一层冰。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"面包皮","en":"The crust on a loaf of bread is the outside part."},{"pos":"N-COUNT 可数名词","cn":"(馅饼的)酥皮","en":"A pie's crust is its cooked pastry."},{"pos":"N-COUNT 可数名词","cn":"(尤指较软或较湿的物质上的)硬层，硬皮","en":"A crust is a hard layer of something, especially on top of a softer or wetter substance.","ex":{"en":"As the water evaporates, a crust of salt is left on the surface of the soil.","cn":"随着水分的蒸发，地面上留下了一层结晶盐。"}},{"pos":"N-COUNT 可数名词","cn":"地壳","en":"The earth's crust is its outer layer.","ex":{"en":"Earthquakes leave scars in the earth's crust.","cn":"地震会在地壳上留下裂痕。"}},{"pos":"PHRASE 短语","cn":"(尤指通过做不愿意做的工作)谋生","en":"If you earn a crust, you earn enough money to live on, especially by doing work you would prefer not to do.","ex":{"en":"In his early days, he would do almost anything to earn a crust from the sport.","cn":"早年为了能在体育界混口饭吃，他几乎什么都做。"}}]},"examples":[{"en":"Bake until the crust is golden.","cn":"把糕饼烤至外皮呈金黄色。"},{"en":"sandwiches with the crusts cut off","cn":"切掉面包皮的三明治"}]},"crunching":{"lemma":"crunch"},"crossed":{"lemma":"cross","media":{"uk":"media/ldoce/hwd/bre/3/crossed0205.mp3","us":"media/ldoce/hwd/ame/4/crossed.mp3"}},"crossovers":{"oxford":{"phon":"ˈkrɒsəʊvə(r)","pos":"noun","senses":[{"en":"the process or result of changing from one area of activity or style of doing sth to another （","cn":"活动范围或风格的）改变，转型，变化"}]}},"cruising":{"lemma":"cruise","media":{"uk":"media/ldoce/hwd/bre/2/ld41cruising.mp3","us":"media/ldoce/hwd/ame/7/laadcruising.mp3"}},"crawled":{"lemma":"crawl"},"critics":{"lemma":"critic"},"creating":{"lemma":"create"},"cranking":{"oxford":{"phon":"kræŋk","pos":"noun","senses":[{"en":"( disapproving ) a person with ideas that other people find strange （","cn":"想法）古怪的人"},{"en":"( NAmE ) a person who easily gets angry or annoyed","cn":"脾气坏的人；容易恼怒的人"}]}},"crates":{"lemma":"crate"},"crooks":{"lemma":"crook"},"crowds":{"lemma":"crowd"},"created":{"lemma":"create"},"crawling":{"lemma":"crawl"},"crashed":{"lemma":"crash"},"craziest":{"lemma":"crazy"},"creatures":{"lemma":"creature"},"cries":{"lemma":"cry"},"crews":{"lemma":"crew"},"creates":{"lemma":"create"},"crowding":{"lemma":"crowd"},"crimes":{"lemma":"crime"},"crevasses":{"oxford":{"phon":"krəˈvæs","pos":"noun","senses":[{"en":"a deep open crack, especially in ice, for example in a glacier （","cn":"尤指冰川等的）裂缝，裂隙，冰隙"}]}},"crayon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"彩色铅笔(或蜡笔)","en":"A crayon is a pencil containing coloured wax or clay, or a rod of coloured wax used for drawing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a stick of coloured wax or chalk that children use to draw pictures","cn":"彩色蜡笔﹔彩色粉笔"},{"en":"to draw something with a crayon","cn":"用彩色蜡笔[粉笔]画（画）"}]},"collocations":{"phrases":["ADJ. coloured | wax","QUANT. box","VERB + CRAYON colour sth in with, draw (sth) with, use She coloured the picture in with crayons.","CRAYON + NOUN drawing","PREP. in ~ The notice was written in crayon."]},"media":{"img":["media/ldoce/img/crayons.jpg"],"uk":"media/ldoce/hwd/bre/2/crayon_n0205.mp3","us":"media/ldoce/hwd/ame/1/crayon1.mp3"},"oxford":{"phon":"ˈkreɪən","pos":"verb","senses":[{"en":"to draw or colour something using a crayon","cn":"使用蜡笔绘画或上色"},{"en":"a coloured pencil or stick of soft coloured chalk or wax, used for drawing","cn":"蜡笔","ex":{"en":"She coloured the picture in with crayons.","cn":"她用蜡笔给图画着色。"},"pos":"noun"}]}},"credibility":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"信用;可信性;可靠性","en":"If someone or something has credibility, people believe in them and trust them.","ex":{"en":"The police have lost their credibility","cn":"警方已经失去了公众的信任。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of deserving to be believed and trusted","cn":"可信度﹔可靠性"},{"en":"the difference between what someone says and what they do","cn":"信用差距〔指言行不一致〕"}]},"vocab":{"pos":"n","senses":[{"en":"You have credibility when you seem totally trustworthy or believable. You lose it when you start lying, cheating and acting rather shady."}]},"collocations":{"phrases":["VERB + CREDIBILITY carry, have The certificate has great credibility in France and Germany. | be lacking in, lack | gain, regain The governm","CREDIBILITY + VERB suffer The prime minister's credibility suffered in his handling of the crisis.","CREDIBILITY + NOUN gap Newspapers were talking of a credibility gap between her policies and her achievements. | problem Athletics' anti-dop","PREP. ~ among, ~ as her credibility as a witness | ~ for There is little credibility among scientists for the book's claims."]},"media":{"uk":"media/ldoce/hwd/bre/4/credibility0205.mp3","us":"media/ldoce/hwd/ame/7/credibility.mp3"},"examples":[{"en":"Newspapers were talking of a credibility gap between what he said and what he did.","cn":"各家报纸都在议论他言行不一。"},{"en":"The prosecution did its best to undermine the credibility of the witness.","cn":"原告竭力削弱证人的可信性。"}],"oxford":{"phon":"ˌkredəˈbɪləti","pos":"noun","senses":[{"en":"the quality that somebody/something has that makes people believe or trust them","cn":"可信性；可靠性","ex":{"en":"to gain/lack/lose credibility","cn":"获取／缺乏／失去信任"}}]}},"cruiser":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(可供住宿的)舱式游艇","en":"A cruiser is a motor boat which has an area for people to live or sleep.","ex":{"en":"...a motor cruiser.","cn":"电动游艇"}},{"pos":"N-COUNT 可数名词","cn":"巡洋舰","en":"A cruiser is a large fast warship.","ex":{"en":"Italy had lost three cruisers and two destroyers.","cn":"意大利损失了3艘巡洋舰和2艘驱逐舰。"}},{"pos":"N-COUNT 可数名词","cn":"巡逻警车","en":"A cruiser is a police car."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large fast ship used by the navy","cn":"巡洋舰"},{"en":"a boat used for pleasure","cn":"游艇"},{"en":"a police car","cn":"警车"}]},"collocations":{"phrases":["ADJ. battle, heavy, light, merchant | cabin, motor, pleasure, sailing","PREP. on a/the ~ He served on a merchant cruiser."]},"media":{"uk":"media/ldoce/hwd/bre/2/cruiser0205.mp3","us":"media/ldoce/hwd/ame/a/cruiser.mp3","img":["media/thumb/cruiser.jpg"]},"examples":[{"en":"a battle cruiser","cn":"战列巡洋舰"}],"oxford":{"phon":"ˈkruːzə(r)","pos":"noun","senses":[{"en":"a large fast ship used in war","cn":"巡洋舰","ex":{"en":"He served on a battle cruiser.","cn":"他在一艘战列巡洋舰上服役。"}},{"en":"a boat with a motor and room for people to sleep, used for pleasure trips","cn":"（可住宿的）舱式游艇","ex":{"en":"a luxury 20-foot cabin cruiser","cn":"一艘20英尺长的豪华舱式游艇"}},{"en":"a police car","cn":"巡逻警车","lab":"North American English"}]}},"crumb":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"食物碎屑;面包屑;糕饼屑","en":"Crumbs are tiny pieces that fall from bread, biscuits, or cake when you cut it or eat it.","ex":{"en":"I stood up, brushing crumbs from my trousers.","cn":"我站起来，掸掉裤子上的碎屑。"}},{"pos":"N-COUNT 可数名词","cn":"一点;少许","en":"A crumb of something, for example information, is a very small amount of it.","ex":{"en":"At last Andrew gave them a crumb of information","cn":"最后，安德鲁向他们透露了一点信息。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece that has broken off something, especially something hard","cn":""},{"en":"a very small piece of bread, cake etc","cn":""},{"en":"a piece of something such as dirt or dust which is so small you almost cannot see it","cn":""}]},"collocations":{"phrases":["ADJ. biscuit, bread (also breadcrumb ), cake","VERB + CRUMB brush (away), sweep (away) She brushed the cake crumbs off the table. | drop, scatter He bit into the roll, scattering crumbs.","PREP. ~ of a few crumbs of bread"]},"media":{"uk":"media/ldoce/hwd/bre/5/crumb0205.mp3","us":"media/ldoce/hwd/ame/7/crumb.mp3"},"examples":[{"en":"The government's only crumb of comfort is that their opponents are as confused as they are.","cn":"政府唯一聊以自慰的是反对派与他们一样困惑不解。"},{"en":"She stood up and brushed the crumbs from her sweater.","cn":"她站起身掸掉了毛衣上的面包屑。"}],"oxford":{"phon":"krʌm","pos":"noun","senses":[{"en":"a very small piece of food, especially of bread or cake, that has fallen off a larger piece","cn":"食物碎屑；（尤指）面包屑，糕饼屑","ex":{"en":"She stood up and brushed the crumbs from her sweater.","cn":"她站起身掸掉了毛衣上的面包屑。"}},{"en":"a small piece or amount","cn":"一点；少许；少量","ex":{"en":"I managed to pick up a few crumbs of useful information.","cn":"我设法收集了一些有用的信息。"}}]}},"creamy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"含奶油的;含乳脂多的","en":"Food or drink that is creamy contains a lot of cream or milk.","ex":{"en":"...rich, creamy coffee.","cn":"香浓诱滑的咖啡"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(食物)光滑细腻的，柔软滑腻的","en":"Food that is creamy has a soft smooth texture and appearance.","ex":{"en":"...creamy mashed potato","cn":"柔软滑腻的土豆泥"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a thick liquid flows slowly because it is almost solid","cn":""},{"en":"a liquid that is lumpy contains small solid pieces, so it is not as smooth as it should be","cn":""},{"en":"thick and smooth like cream","cn":"似奶油的﹔软厚平滑的﹐光滑细软的"}]},"collocations":{"phrases":["VERBS be, look, seem, taste Stir the mixture until it looks creamy. It tastes deliciously creamy.","ADV. deliciously, very, wonderfully","PHRASES creamy white creamy white flowers"]},"media":{"uk":"media/ldoce/hwd/bre/8/ld44creamy.mp3","us":"media/ldoce/hwd/ame/b/creamy.mp3"},"examples":[{"en":"a creamy sauce/soup","cn":"奶油沙司/汤羹"},{"en":"creamy skin","cn":"淡黄色的皮肤"}],"oxford":{"phon":"ˈkriːmi","pos":"adjective","senses":[{"en":"thick and smooth like cream; containing a lot of cream","cn":"像奶油的；光滑细腻的；含乳脂的","ex":{"en":"a creamy sauce/soup","cn":"奶油调味汁／汤羹"}},{"en":"between yellow and white in colour","cn":"奶油色的；乳白色的","ex":{"en":"creamy skin","cn":"乳白色的皮肤"}}]}},"crossword":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"纵横字谜;纵横填字游戏","en":"A crossword or crossword puzzle is a word game in which you work out the answers and write them in the white squares of a pattern of small black and white squares."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a word game in which you write the answers to questions in a pattern of numbered boxes","cn":"纵横字谜﹐纵横填字（游戏）"}]},"collocations":{"phrases":["ADJ. cryptic, quick","VERB + CROSSWORD do, fill in, solve","CROSSWORD + NOUN clue, puzzle"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdecrossword.mp3","us":"media/ldoce/hwd/ame/f/crossword.mp3","img":["media/thumb/crossword.jpg"]},"examples":[{"en":"I've finished the crossword apart from 3 across and 10 down.","cn":"这份纵横字谜除横 3 竖 10 以外我都填完了。"},{"en":"to do a/the crossword","cn":"做纵横填字游戏"}],"oxford":{"phon":"ˈkrɒswɜːd","pos":"noun","senses":[{"en":"a game in which you have to fit words across and downwards into spaces with numbers in a square diagram. You find the words by solving clues.","cn":"纵横字谜；纵横填字游戏","ex":{"en":"to do a/the crossword","cn":"做纵横填字游戏"}}]}},"crash":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"撞车;碰撞;相撞","en":"A crash is an accident in which a moving vehicle hits something and is damaged or destroyed.","ex":{"en":"His elder son was killed in a car crash a few years ago.","cn":"他的长子几年前死于车祸。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)碰撞;(使)撞毁","en":"If a moving vehicle crashes or if the driver crashes it, it hits something and is damaged or destroyed.","ex":{"en":"The plane crashed mysteriously near the island of Ustica.","cn":"那架飞机在乌斯蒂卡岛附近神秘坠毁了。"}},{"pos":"VERB 动词","cn":"猛撞;撞击","en":"If something crashes somewhere, it moves and hits something else violently, making a loud noise.","ex":{"en":"The door swung inwards to crash against a chest of drawers behind it","cn":"门朝里摆去，撞到了后面的大衣柜。"}},{"pos":"N-COUNT 可数名词","cn":"(突然间响起的)巨大声响","en":"A crash is a sudden, loud noise.","ex":{"en":"Two people in the flat recalled hearing a loud crash about 1.30 a.m.","cn":"公寓楼里有两个人回想起凌晨1点半听见了一声巨响。"}},{"pos":"VERB 动词","cn":"(生意或金融体制)倒闭，破产，失败","en":"If a business or financial system crashes, it fails suddenly, often with serious effects.","ex":{"en":"When the market crashed, they assumed the deal would be cancelled.","cn":"当市场崩溃时，他们认为交易会被取消。"}},{"pos":"VERB 动词","cn":"(计算机或计算机程序)崩溃，瘫痪","en":"If a computer or a computer program crashes, it fails suddenly.","ex":{"en":"...after the computer crashed for the second time in 10 days.","cn":"电脑在10天内第二次死机后"}},{"pos":"","cn":"","en":"相关词组：crash out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit another vehicle, a tree, the ground etc, with a lot of force, causing a lot of damage","cn":""},{"en":"to move into something quickly and with force","cn":""},{"en":"if two cars, trains, planes etc collide, they hit each other, especially when they are moving in opposite directions","cn":""}]},"vocab":{"pos":"1 v n 2 v n 3 v n 4 ","senses":[{"en":"Boom! Bam! Pow! A crash is when two things collide, or smash, into each other. Crash and smash have similar meanings and sounds."}]},"collocations":{"phrases":["ADJ. almighty, deafening, great, loud, thunderous | distant | sickening, terrible There was a sickening crash as her head hit the ground.","VERB + CRASH hear","PREP. with a ~ The plates fell to the floor with an almighty crash. | ~ of a distant crash of thunder","PHRASES a crash of thunder, the crash of the waves 2 car/plane, etc. accident","ADJ. horrific, major, serious a major air crash | fatal | head-on | high-speed | car, coach, helicopter, plane, train | air, motorway, rail,","VERB + CRASH cause","CRASH + VERB happen, occur | involve sth a crash involving two cars and a lorry | kill sb | claim sth The crash claimed three lives.","CRASH + NOUN victim | site | landing | barrier"]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdecrash.mp3","us":"media/ldoce/hwd/ame/b/crash1.mp3"},"examples":[{"en":"They crashed out of the World Cup after a 2-1 defeat to Brazil.","cn":"他们以 1:2 输给巴西队之后在世界杯赛中淘汰出局。"},{"en":"The company crashed with debts of £50 million.","cn":"那家公司由于负债 5 000 万英镑而告破产。"}],"oxford":{"phon":"kræʃ","pos":"noun","senses":[{"en":"an accident in which a vehicle hits something, for example another vehicle, usually causing damage and often injuring or killing the passengers","cn":"撞车；碰撞；相撞","lab":"North American English also","sc":"vehicle accident","ex":{"en":"a car/plane crash","cn":"汽车撞车事故；飞机失事"}},{"en":"a sudden loud noise made, for example, by something falling or breaking","cn":"（倒下、破碎等突然的）碰撞声，破裂声，碎裂声","g":"[usually singular]","sc":"loud noise","ex":{"en":"The tree fell with a great crash.","cn":"那棵树哗啦一声倒了。"}},{"en":"a sudden serious fall in the price or value of something; the occasion when a business, etc. fails","cn":"暴跌；倒闭；破产；失败","sc":"in finance/business","ex":{"en":"Some economists have been predicting another crash for years.","cn":"多年来一些经济学家一直预测会有另一场经济崩溃。"}},{"en":"a sudden failure of a machine or system, especially of a computer or computer system","cn":"（机器或系统，尤指计算机或计算机系统的）崩溃","sc":"computing","ex":{"en":"Users won't lose important data if a hardware problem causes a crash.","cn":"如果硬件问题导致系统崩溃，用户不会丢失重要数据。"}},{"en":"if a vehicle crashes or the driver crashes it, it hits an object or another vehicle, causing damage","cn":"碰撞；撞击","g":"[intransitive, transitive]","sc":"of vehicle","ex":{"en":"I was terrified that the plane would crash.","cn":"飞机可能会失事，我吓坏了。"},"pos":"verb"},{"en":"to hit something hard while moving, causing noise and/or damage; to make something hit somebody/something in this way","cn":"（使）猛撞，碰撞","g":"[intransitive, transitive]","sc":"hit hard/loud noise","ex":{"en":"A brick crashed through the window.","cn":"砖块哗啦一声砸入了窗户。"},"pos":"verb"},{"en":"to make a loud noise","cn":"发出巨响","g":"[intransitive]","sc":"hit hard/loud noise","ex":{"en":"Thunder crashed overhead.","cn":"头顶上雷声隆隆。"},"pos":"verb"},{"en":"to lose value or fail suddenly and quickly","cn":"（突然）贬值，倒闭，失败；暴跌","g":"[intransitive]","sc":"in finance/business","ex":{"en":"Share prices crashed to an all-time low yesterday.","cn":"昨天股票价格暴跌到了历史最低。"},"pos":"verb"},{"en":"if a computer crashes or you crash a computer, it stops working suddenly","cn":"崩溃","g":"[intransitive, transitive]","sc":"computing","ex":{"en":"Files can be lost if the system suddenly crashes.","cn":"要是计算机系统突然崩溃，文件就可能丢失。"},"pos":"verb"},{"en":"gatecrash (= to go to a party or social event without being invited)","cn":"未获邀请而参加（或出席）；做（聚会等的）不速之客","g":"[transitive]","lab":"informal","sc":"party","pos":"verb"},{"en":"to lose very badly in a sports game","cn":"（比赛中）溃败，惨败","g":"[intransitive]","lab":"especially British English","sc":"in sport","ex":{"en":"The team crashed to their worst defeat this season.","cn":"那支队遭受了本赛季最严重的一次惨败。"},"pos":"verb"},{"en":"to go to sleep, especially suddenly or in a place where you do not usually sleep","cn":"（尤指在自己不常睡的地方）倒头便睡","g":"[intransitive]","lab":"informal","sc":"sleep","ex":{"en":"I was so tired I crashed out on the sofa.","cn":"我累极了，在沙发上就睡着了。"},"pos":"verb"},{"en":"if somebody crashes, their heart stops beating","cn":"心脏停止跳动","g":"[intransitive]","sc":"medical","pos":"verb"},{"en":"involving hard work or a lot of effort over a short period of time in order to achieve quick results","cn":"应急的；速成的","ex":{"en":"a crash course in computer programming","cn":"计算机编程速成课程"},"pos":"adjective"}]}},"creditable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"值得赞扬的;应当认可的","en":"A creditable performance or achievement is of a reasonably high standard.","ex":{"en":"They turned out a quite creditable performance","cn":"他们上演了一场相当精彩的表演。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合乎道德的;高尚的","en":"If you describe someone's actions or aims as creditable, you mean that they are morally good.","ex":{"en":"Not a very creditable attitude, I'm afraid.","cn":"这种态度恐怕不怎么道德。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"deserving praise or approval","cn":"值得赞扬的﹔应当认可的"}]},"collocations":{"phrases":["VERBS be, seem | make sth","ADV. highly, very She gave a highly creditable performance as the wicked queen."]},"media":{"uk":"media/ldoce/hwd/bre/8/creditable0205.mp3","us":"media/ldoce/hwd/ame/9/creditable.mp3"},"examples":[{"en":"It was a very creditable result for the team.","cn":"对这支队来说，这比赛结果是十分值得称道的。"},{"en":"There was nothing very creditable in what he did.","cn":"他这事做得可实在不怎么样。"}],"oxford":{"phon":"ˈkredɪtəbl","pos":"adjective","senses":[{"en":"of a quite good standard and deserving praise or approval","cn":"值得赞扬的；应当认可的","ex":{"en":"It was a very creditable result for the team.","cn":"对这支队来说，这个比赛结果是十分值得称道的。"}},{"en":"morally good","cn":"道德上好的；高尚的","ex":{"en":"There was nothing very creditable in what he did.","cn":"他这事做得可实在不怎么样。"}}]}},"crystal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"结晶;晶体","en":"A crystal is a small piece of a substance that has formed naturally into a regular symmetrical shape.","ex":{"en":"...salt crystals.","cn":"盐晶体"}},{"pos":"N-VAR 可变名词","cn":"水晶","en":"Crystal is a transparent rock that is used to make jewellery and ornaments.","ex":{"en":"...a strand of crystal beads.","cn":"一串水晶珠子"}},{"pos":"N-UNCOUNT 不可数名词","cn":"水晶玻璃","en":"Crystal is a high quality glass, usually with patterns cut into its surface.","ex":{"en":"Some of the finest drinking glasses are made from lead crystal.","cn":"一些最高档的酒杯是用铅晶质玻璃制成的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"水晶玻璃杯;水晶玻璃容器","en":"Glasses and other containers made of crystal are referred to as crystal .","ex":{"en":"Get out your best china and crystal.","cn":"拿出你最好的瓷器和水晶玻璃器皿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"very high quality clear glass","cn":"水晶玻璃"},{"en":"a small regular-shaped piece of a substance, formed naturally when this substance becomes solid","cn":"结晶（体）"},{"en":"rock that is clear, or a piece of this （","cn":"一块）水晶"}]},"vocab":{"pos":"1 n 2 n 3 n 4 n 5 n","senses":[{"en":"Various solid substances that glitter because their surfaces are made up of planes that catch the light are called crystals . If you leave your ice cream in the freezer too long, you may find a coating of ice crystals on top."}]},"collocations":{"phrases":["ADJ. single | quartz, rock, etc. | ice, snow","CRYSTAL + VERB form, grow Ice crystals had formed on the window."]},"media":{"uk":"media/ldoce/hwd/bre/8/crystal_las2_br.mp3","us":"media/ldoce/hwd/ame/4/crystal.mp3"},"examples":[{"en":"a crystal chandelier/vase","cn":"水晶玻璃枝形吊灯/花瓶"},{"en":"ice/salt crystals","cn":"冰/盐的结晶体"}],"oxford":{"phon":"ˈkrɪstl","pos":"noun","senses":[{"en":"a small piece of a substance with many even sides, that is formed naturally when the substance becomes solid","cn":"结晶；晶体","g":"[countable]","ex":{"en":"ice/salt crystals","cn":"冰／盐的结晶体"}},{"en":"a clear mineral, such as quartz, used in making jewellery and attractive objects","cn":"水晶（如石英，用于制作珠宝饰物）","g":"[uncountable, countable]","ex":{"en":"crystal earrings","cn":"水晶耳环"}},{"en":"glass of very high quality","cn":"水晶玻璃","g":"[uncountable]","ex":{"en":"a crystal chandelier/vase","cn":"水晶玻璃枝形吊灯／花瓶"}},{"en":"a small piece of a mineral that some people believe has the power to bring health or happiness","cn":"（水晶）吉祥物","g":"[countable]","ex":{"en":"Smoky Quartz is a powerful healing crystal.","cn":"烟晶是一种强大的治疗水晶。"}},{"en":"a piece of glass or plastic that covers the face of a watch","cn":"石英玻璃表护面；塑料表护面；表蒙子","g":"[countable]"},{"en":"a powerful illegal drug, methamphetamine, that looks like small pieces of glass","cn":"冰毒（即甲基苯丙胺）","lab":"informal"}]}},"crusade":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(长期坚定不移的)斗争，运动","en":"A crusade is a long and determined attempt to achieve something for a cause that you feel strongly about.","ex":{"en":"Footballers launched an unprecedented crusade against racism on the terraces","cn":"足球运动员们对阶梯看台上的种族歧视发起了一场空前的运动。"}},{"pos":"VERB 动词","cn":"长期坚定不移地奋斗","en":"If you crusade for a particular cause, you make a long and determined effort to achieve something for it.","ex":{"en":"...a newspaper that has crusaded against the country's cocaine traffickers.","cn":"坚决抨击该国可卡因毒贩的报纸"}},{"pos":"N-PROPER-PLURAL 专有复数名词","cn":"(发生于11世纪至13世纪的)十字军东征","en":"The Crusades were the wars that were fought by Christians in Palestine against the Muslims during the eleventh, twelfth, and thirteenth centuries."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process in which people try to stop something bad from happening or to improve a situation","cn":""},{"en":"a fight to change a situation or deal with a problem in society","cn":""},{"en":"a planned series of actions intended to achieve something","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"If you go on a crusade against vegetables, you are waging a long-term battle against leafy greens. A crusade is a passionate struggle against something or someone."}]},"collocations":{"phrases":["ADJ. great | moral, personal","VERB + CRUSADE embark on, launch, mount The charity tonight launched its great crusade against homelessness. | be engaged in, carry out, con","PREP. on a ~ He is on a crusade to take the church to the people. | ~ against urging parents to join a crusade against crime | ~ for For 23 "]},"media":{"uk":"media/ldoce/hwd/bre/b/crusade_n0205.mp3","us":"media/ldoce/hwd/ame/7/crusade1.mp3"},"examples":[{"en":"to lead a crusade against crime","cn":"领导打击犯罪活动的运动"},{"en":"a moral crusade","cn":"提倡道德的运动"}],"oxford":{"phon":"kruːˈseɪd","pos":"noun","senses":[{"en":"a long and determined effort to achieve something that you believe to be right or to stop something that you believe to be wrong","cn":"（长期坚定不移的）斗争，运动","ex":{"en":"to lead a crusade against crime","cn":"领导打击犯罪活动的运动"}},{"en":"any of the wars fought in Palestine by European Christian countries against the Muslims in the Middle Ages","cn":"（中世纪的）十字军东征"},{"en":"to make a long and determined effort to achieve something that you believe to be right or to stop something you believe to be wrong","cn":"长期坚定不移地奋斗","ex":{"en":"a crusading environmentalist","cn":"坚持不懈的环保主义者"},"pos":"verb"}]}},"crawl":{"collins":{"senses":[{"pos":"VERB 动词","cn":"爬;爬行;匍匐前进","en":"When you crawl, you move forward on your hands and knees.","ex":{"en":"Don't worry if your baby seems a little reluctant to crawl or walk","cn":"如果你的宝宝不爱爬也不爱走，不要担心。"}},{"pos":"VERB 动词","cn":"(昆虫)爬行","en":"When an insect crawls somewhere, it moves there quite slowly.","ex":{"en":"I watched the moth crawl up the outside of the lampshade.","cn":"我看着飞蛾爬到灯罩外面。"}},{"pos":"VERB 动词","cn":"缓慢行进;艰难前进","en":"If someone or something crawls somewhere, they move or progress slowly or with great difficulty.","ex":{"en":"I crawled out of bed at nine-thirty","cn":"我9点半才勉强从床上爬起来。"}},{"pos":"VERB 动词","cn":"挤满，爬满(人或动物)","en":"If you say that a place is crawling with people or animals, you are emphasizing that it is full of them.","ex":{"en":"This place is crawling with police.","cn":"这个地方全是警察。"}},{"pos":"N-SING 单数名词","cn":"爬泳;自由泳","en":"The crawl is a kind of swimming stroke which you do lying on your front, swinging one arm over your head, and then the other arm."},{"pos":"PHRASE 短语","cn":"使震惊;使生厌","en":"If something makes your skin crawl or makes your flesh crawl, it makes you feel shocked or disgusted.","ex":{"en":"I hated this man, his very touch made my skin crawl.","cn":"我讨厌这个男人，他碰我一下我都觉得恶心。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"be full of people, animals, insects etc all moving around","cn":""},{"en":"to be very full of animals, people, insects etc, all moving around very quickly or busily - use this especially when you think this is unpleasant in some way","cn":""},{"en":"to be full of a lot of people standing or sitting very close together","cn":""}]},"collocations":{"phrases":["ADV. slowly | about, along, around/round, away, back, fowards, through We spent an hour crawling around on our hands and knees looking for t","VERB + CRAWL manage to As night fell, we managed to crawl back to our lines. | start to Has the baby started to crawl yet?","PREP. across, along, into, over, out of, under, up There's an insect crawling up your leg!","PHRASES crawl on (your) hands and knees"]},"media":{"img":["media/ldoce/img/crawl.jpg","media/thumb/crawl.jpg"],"uk":"media/ldoce/hwd/bre/a/crawl_n0205.mp3","us":"media/ldoce/hwd/ame/2/crawl1.mp3"},"examples":[{"en":"A man was crawling away from the burning wreckage.","cn":"一个男人正从燃烧着的残骸爬着往外逃。"},{"en":"There's a spider crawling up your leg.","cn":"有只蜘蛛正顺着你的腿往上爬。"}],"oxford":{"phon":"krɔːl","pos":"verb","senses":[{"en":"to move forward on your hands and knees or with your body close to the ground","cn":"爬；爬行；匍匐行进","g":"[intransitive]","ex":{"en":"Our baby is just starting to crawl.","cn":"我们的宝宝刚开始会爬。"}},{"en":"when an insect, a spider, etc. crawls, it moves forward on its legs","cn":"（昆虫、蜘蛛等）爬行","g":"[intransitive]","ex":{"en":"There's a spider crawling up your leg.","cn":"有只蜘蛛正顺着你的腿往上爬。"}},{"en":"to move forward very slowly","cn":"缓慢行进","g":"[intransitive]","ex":{"en":"The traffic was crawling along.","cn":"来往车辆缓缓而行。"}},{"en":"to be too friendly or helpful to somebody in authority, in a way that is not sincere, especially in order to get an advantage from them","cn":"卑躬屈膝；谄媚；巴结；拍马屁","g":"[intransitive]","lab":"informal, disapproving，，","ex":{"en":"She's always crawling to the boss.","cn":"她对老板总是谄媚奉承。"}},{"en":"a very slow speed","cn":"缓慢的速度","g":"[singular]","ex":{"en":"The traffic slowed to a crawl.","cn":"来往的车辆放缓速度慢慢前行。"},"pos":"noun"},{"en":"a fast swimming stroke that you do lying on your front moving one arm over your head, and then the other, while kicking with your feet","cn":"爬泳；自由泳","g":"[singular, uncountable]","ex":{"en":"a swimmer doing the crawl","cn":"游自由泳的运动员"},"pos":"noun"}]}},"critique":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"评论;评论文章","en":"A critique is a written examination and judgment of a situation or of a person's work or ideas.","ex":{"en":"She had brought a book, a feminist critique of Victorian lady novelists.","cn":"她带来了一本书，这本书从女性主义视角对维多利亚时代女性小说家进行了评论。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to form an opinion about a person or situation, using your knowledge, experience, and intelligence","cn":""},{"en":"to consider someone's work, ideas, or products, or to consider a situation or event, in order to judge how good they are, what standard they have reached, or how useful they might be to you","cn":""},{"en":"to carefully consider how useful or valuable an activity, plan, or suggestion is, especially in order to decide whether or not to start doing it or continue doing it","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"As a verb, critique means to review or examine something critically. As a noun, a critique is that review or examination, like an art essay or a book report."}]},"collocations":{"phrases":["ADJ. detailed, devastating, effective, far-reaching, penetrating, radical, searching, telling, thorough, trenchant, wide-ranging | feminist,","VERB + CRITIQUE give, present, provide","PREP. ~ of The book provides a thorough critique of current theories."]},"media":{"uk":"media/ldoce/hwd/bre/8/critique_las3_br.mp3","us":"media/ldoce/hwd/ame/f/critique.mp3"},"examples":[{"en":"a feminist critique of Freud's theories","cn":"从女权主义的角度对弗洛伊德理论所作的批评"},{"en":"Her job involves critiquing designs by fashion students.","cn":"她的工作包括评判时装专业学生的设计。"}],"oxford":{"phon":"krɪˈtiːk","pos":"noun","senses":[{"en":"a piece of written criticism of a set of ideas, a work of art, etc.","cn":"评论；评论文章","ex":{"en":"She wrote a feminist critique of Freud's theories.","cn":"她写了一篇从女权主义角度评论弗洛伊德理论的文章。"}},{"en":"to write or give your opinion of, or reaction to, a set of ideas, a work of art, etc.","cn":"写评论；对…发表评论；评判","ex":{"en":"Her job involves critiquing designs by fashion students.","cn":"她的工作包括评判时装专业学生的设计。"},"pos":"verb"}]}},"creditor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"债权人;债主;贷方","en":"Your creditors are the people who you owe money to.","ex":{"en":"The company said it would pay in full all its creditors.","cn":"该公司称将偿清所有债权人的债务。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person or organization that lends money","cn":""},{"en":"a person or business that is owed money by another person or business","cn":""},{"en":"a person or small business that lends money, at extremely high interest rates - use this when you disapprove of people who make money in this way","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If Joe loans you two dollars so you can buy a cup of coffee, Joe is your creditor — you owe him two dollars and a big thank you!"}]},"collocations":{"phrases":["VERB + CREDITOR pay (off), repay They agreed to repay their creditors over a period of three years."]},"media":{"uk":"media/ldoce/hwd/bre/5/creditor0205.mp3","us":"media/ldoce/hwd/ame/e/creditor.mp3"},"oxford":{"phon":"ˈkredɪtə(r)","pos":"noun","senses":[{"en":"a person, company, etc. that somebody owes money to","cn":"债权人；债主；贷方","ex":{"en":"The property will be sold to pay off their creditors.","cn":"卖掉财产以偿债给他们的债主。"}}]}},"crease":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(衣服或纸的)褶痕，皱痕","en":"Creases are lines that are made in cloth or paper when it is crushed or folded.","ex":{"en":"She stood up, frowning at the creases in her silk dress","cn":"她站起身来，看到丝裙上的褶痕皱起了眉头。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)起皱;(使)起褶","en":"If cloth or paper creases or if you crease it, lines form in it when it is crushed or folded.","ex":{"en":"Most outfits crease a bit when you are travelling","cn":"旅行时大多数服装都会略微起褶。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(皮肤因为皱眉或微笑而)起皱纹;使(皮肤)起皱纹","en":"If your face creases or if an expression creases it, lines appear on it because you are frowning or smiling.","ex":{"en":"His ruddy face still routinely creases with mirth","cn":"他红润的脸庞仍旧时常笑得堆起褶子。"}},{"pos":"N-COUNT 可数名词","cn":"(皮肤上的)皱纹","en":"Creases in someone's skin are lines which form where their skin folds when they move.","ex":{"en":"...the tiny creases at the corners of his eyes","cn":"他眼角的细纹"}},{"pos":"N-SING 单数名词","cn":"(板球场上击球手的)位置线，击球线","en":"In cricket, the crease is a line on the playing surface where the batsman stands.","ex":{"en":"Haynes was still at the crease, unbeaten on 84.","cn":"海恩斯还在击球线上，他已经得了84分了。"}},{"pos":"","cn":"","en":"相关词组：crease up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thin mark on a piece of paper, the ground, or another surface","cn":""},{"en":"a thin line that has been cut into a surface","cn":""},{"en":"a deep line in the ground which has been made by the wheels of vehicles","cn":""}]},"collocations":{"phrases":["ADV. badly, easily This material creases very easily. | a bit, slightly His shirt had creased a bit in the suitcase.","PHRASES be/get creased Her clothes were badly creased."]},"media":{"uk":"media/ldoce/hwd/bre/d/crease_n0205.mp3","us":"media/ldoce/hwd/ame/5/crease1.mp3"},"examples":[{"en":"Pack your suit carefully so that you don't crease it.","cn":"把你的西装小心装好以免弄皱。"},{"en":"A frown creased her forehead.","cn":"她一皱眉，额头显出了皱纹。"}],"oxford":{"phon":"kriːs","pos":"noun","senses":[{"en":"an untidy line that is made in cloth or paper when it is pressed or folded without care","cn":"褶痕；皱痕","ex":{"en":"She smoothed the creases out of her skirt.","cn":"她把裙子上的皱褶弄平。"}},{"en":"a neat line that you make in something, for example when you fold paper or iron clothes","cn":"褶缝；褶线","ex":{"en":"trousers with a sharp crease in the legs","cn":"裤线笔挺的裤子"}},{"en":"a line in the skin, especially on the face","cn":"（皮肤上，尤指脸上的）皱纹","ex":{"en":"creases around the eyes","cn":"眼睛周围的皱纹"}},{"en":"a white line on the ground near each wicket that marks the position of the bowler and the batsman","cn":"（投手和击球员的）位置线，区域线；投球线；击球线","ex":{"en":"He spent six hours at the crease (= he was batting) for six hours.","cn":"他击球六个小时。"}},{"en":"to make lines on cloth or paper by folding or pressing it; to develop lines in this way","cn":"弄皱；压褶；（使）起褶子","g":"[transitive, intransitive]","ex":{"en":"Pack your suit carefully so that you don't crease it.","cn":"把你的西装小心装好以免弄皱。"},"pos":"verb"},{"en":"to make lines in the skin; to develop lines in the skin","cn":"（皮肤）皱起；（使）起皱纹","g":"[transitive, intransitive]","ex":{"en":"A frown creased her forehead.","cn":"她一皱眉，额头显出了皱纹。"},"pos":"verb"}]}},"cruelty":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"残暴;残忍;残酷","en":"Cruelty is behaviour that deliberately causes pain or distress to people or animals.","ex":{"en":"Britain had laws against cruelty to animals but none to protect children","cn":"英国有禁止虐待动物的法律，但却没有保护儿童的法律。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"cruel treatment or behaviour","cn":""},{"en":"deliberately cruel treatment of someone, especially someone in your family that you are supposed to care for","cn":""},{"en":"cruel treatment of someone who is smaller, younger, or weaker - use this especially about children being cruel to other children","cn":""}]},"collocations":{"phrases":["ADJ. extreme, great an act of extreme cruelty | deliberate | mental | animal, child Cases of child cruelty occur more often than they are ob","VERB + CRUELTY inflict, show (sb) How can you inflict such cruelty on a child? Her stepmother showed her nothing but cruelty. | suffer The c","PREP. ~ to/towards cruelty to animals"]},"media":{"uk":"media/ldoce/hwd/bre/6/cruelty0205.mp3","us":"media/ldoce/hwd/ame/1/cruelty.mp3"},"examples":[{"en":"The deliberate cruelty of his words cut her like a knife.","cn":"他故意说的冷言冷语对她像刀割一样。"},{"en":"the cruelties of life","cn":"生活中的种种不公"}],"oxford":{"phon":"ˈkruːəlti","pos":"noun","senses":[{"en":"behaviour that causes physical or mental pain to others and makes them suffer, especially deliberately","cn":"（尤指蓄意的）残酷，残忍，残暴","g":"[uncountable]","ex":{"en":"cruelty to animals","cn":"对动物的虐待"}},{"en":"a cruel action","cn":"残暴的行为","g":"[countable, usually plural]","ex":{"en":"Frightening cruelties were inflicted on child factory workers well into the 19th century.","cn":"直到 19 世纪，工厂童工仍遭受可怕的残酷对待。"}},{"en":"something that happens that seems unfair","cn":"不公；不平","g":"[countable, uncountable]","ex":{"en":"the cruelties of life","cn":"生活中的种种不公"}}]}},"credulity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"轻信;易信","en":"Credulity is a willingness to believe that something is real or true.","ex":{"en":"The plot does stretch credulity.","cn":"这种情节确实让人难以置信。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"willingness or ability to believe that something is true","cn":"轻信﹐易信"},{"en":"→ incredulity : Advertisers were accused of exploiting consumers’ credulity.","cn":"广告商被指责利用了客户对他们的轻信。 strain/stretch credulity (= seem very difficult to believe ) It strained credulity to believe that a "}]},"vocab":{"pos":"n","senses":[{"en":"Did you know that if you say credulity ten times fast it starts to sound like orange ? If you believe that, then you have a lot of credulity . Credulity means gullibility, or a willingness to believe anything."}]},"collocations":{"phrases":["VERB + CREDULITY strain, stretch The plot of the novel stretches credulity to the limit."]},"media":{"uk":"media/ldoce/hwd/bre/d/credulity0205.mp3","us":"media/ldoce/hwd/ame/a/laadcredulity.mp3"},"examples":[{"en":"The plot of the novel stretches credulity to the limit (= it is almost impossible to believe).","cn":"这部小说的情节牵强得几乎令人无法相信。"}],"oxford":{"phon":"krɪˈdjuːləti","pos":"noun","senses":[{"en":"the ability or the wish to believe that something is real or true","cn":"轻信","ex":{"en":"The plot of the novel stretches credulity to the limit (= it is almost impossible to believe).","cn":"这部小说的情节牵强得几乎令人无法相信。"}}]}},"cripple":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"瘸子;残疾人","en":"A person with a physical disability or a serious permanent injury is sometimes referred to as a cripple .","ex":{"en":"She has gone from being a healthy, fit, and sporty young woman to being a cripple.","cn":"她从一个健康、强壮、爱好运动的年轻女性变成了一个跛子。"}},{"pos":"VERB 动词","cn":"使残疾;使成为跛子","en":"If someone is crippled by an injury, it is so serious that they can never move their body properly again.","ex":{"en":"Mr Easton was seriously crippled in an accident and had to leave his job","cn":"伊斯顿先生在一次事故中重度伤残，不得不离职。"}},{"pos":"N-COUNT 可数名词","cn":"(心理上或情感上)有缺陷的人","en":"If you describe someone as an emotional cripple, you mean that they have a particular psychological or emotional problem which prevents them from living a normal life."},{"pos":"VERB 动词","cn":"使(心理上或情感上)出现问题","en":"If something cripples a person, it causes them severe psychological or emotional problems.","ex":{"en":"Howard wanted to be a popular singer, but stage fright crippled him","cn":"霍华德想成为流行歌手，但因怯场而心生畏惧。"}},{"pos":"VERB 动词","cn":"严重毁坏(机器);破坏(组织、体系)","en":"To cripple a machine, organization, or system means to damage it severely or prevent it from working properly.","ex":{"en":"Let's try to cripple their communications","cn":"我们试着破坏他们的通讯设备吧。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to injure someone's legs or back so that they can never move or walk properly again","cn":""},{"en":"to injure someone very seriously and permanently, especially in an accident or deliberate attack","cn":""},{"en":"to hurt someone badly so that they cannot walk properly","cn":"使跛﹐使瘸"}]},"vocab":{"pos":"v n","senses":[{"en":"To cripple is to leave someone unable to walk. Terrible car accidents, for example, can sometimes cripple their victims."}]},"collocations":{"phrases":["ADV. for life, permanently As a child she contracted polio and was crippled for life.","PHRASES be crippled with He's eighty and crippled with arthritis. | leave sb crippled The disease left him crippled. 2 damage","ADV. financially The industry has been financially crippled by these policies."]},"media":{"uk":"media/ldoce/hwd/bre/c/cripple_n0205.mp3","us":"media/ldoce/hwd/ame/3/cripple1.mp3"},"examples":[{"en":"He was crippled by polio as a child.","cn":"他幼年患过小儿麻痹症，结果腿就瘸了。"},{"en":"The pilot tried to land his crippled plane.","cn":"飞行员试图驾驶损坏严重的飞机着陆。"}],"oxford":{"phon":"ˈkrɪpl","pos":"verb","senses":[{"en":"to damage somebody’s body so that they cannot walk or move well","cn":"使残废；使跛；使成瘸子","g":"[usually passive]","ex":{"en":"He was crippled by polio as a child.","cn":"他幼年患过小儿麻痹症，结果腿就瘸了。"}},{"en":"to seriously damage or harm somebody/something","cn":"严重毁坏（或损害）","g":"[usually passive]","ex":{"en":"The industry has been financially crippled by these policies.","cn":"该行业因这些政策陷入财务困境。"}},{"en":"an offensive word for a person who is physically disabled, especially one who cannot walk well or at all","cn":"伤残人；残疾人；跛子；瘸子","pos":"noun"}]}},"creep":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(人或动物)悄悄地缓慢行进，蹑手蹑脚地移动","en":"When people or animals creep somewhere, they move quietly and slowly.","ex":{"en":"Back I go to the hotel and creep up to my room","cn":"我回到旅馆，蹑手蹑脚地上楼回到房间。"}},{"pos":"VERB 动词","cn":"缓慢移动","en":"If something creeps somewhere, it moves very slowly.","ex":{"en":"Mist had crept in again from the sea.","cn":"薄雾又从海面上弥漫过来了。"}},{"pos":"VERB 动词","cn":"不知不觉地发生","en":"If something creeps in or creeps back, it begins to occur or becomes part of something without people realizing or without them wanting it.","ex":{"en":"Insecurity might creep in","cn":"可能会不知不觉地产生不安全感。"}},{"pos":"VERB 动词","cn":"(比率或数值)逐渐增长","en":"If a rate or number creeps up to a higher level, it gradually reaches that level.","ex":{"en":"The inflation rate has been creeping up to 9.5 per cent","cn":"通货膨胀率已攀升至9.5%。"}},{"pos":"N-COUNT 可数名词","cn":"讨厌鬼; (尤指)讨好卖乖的人，马屁精","en":"If you describe someone as a creep, you mean that you dislike them a great deal, especially because they are insincere and flatter people."},{"pos":"PHRASE 短语","cn":"吓人;使惊慌;使心里发毛","en":"If someone or something gives you the creeps, they make you feel very nervous or frightened.","ex":{"en":"I always hated that statue. It gave me the creeps.","cn":"我一直都很讨厌那座雕像。它让我心里发毛。"}},{"pos":"","cn":"","en":"to make someone's flesh creep→see: ;"},{"pos":"","cn":"","en":"相关词组：creep up on"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to walk quietly and carefully on your toes because you do not want to make a noise","cn":""},{"en":"to walk quietly and slowly because you do not want anyone to see or hear you","cn":""},{"en":"to walk quietly so that no one notices you, especially because you are doing something you should not do","cn":""}]},"vocab":{"pos":"1 v n 2 v 3 n 4 n","senses":[{"en":"A beetle creeps along the ground. Moving slowly and silently, it creeps up on you. When you feel the touch of tiny insect legs on your skin, you shudder, because bugs give you the creeps ."}]},"collocations":{"phrases":["ADV. quietly | slowly | stealthily | about, around, back, in, out, up I could hear someone creeping around downstairs. He crept up behind me","PREP. along He crept stealthily along the corridor. | down, into (figurative) Suspicion crept into her voice. | over (figurative) A feeling "]},"media":{"uk":"media/ldoce/hwd/bre/4/creep_v0205.mp3","us":"media/ldoce/hwd/ame/0/creep1.mp3"},"examples":[{"en":"The World Bank has been accused of mission creep when seeking to address these concerns.","cn":"世界银行被指控在寻求处理这些重大事务时偏离使命。"},{"en":"The inclusion of health data on identity cards was condemned as function creep.","cn":"在身分证中包含健康资料被谴责为超出功能范围。"}],"oxford":{"phon":"kriːp","pos":"verb","senses":[{"en":"to move slowly, quietly and carefully, because you do not want to be seen or heard","cn":"悄悄地缓慢行进；蹑手蹑脚地移动","g":"[intransitive]","ex":{"en":"I crept up the stairs, trying not to wake my parents.","cn":"为了尽量不吵醒父母，我蹑手蹑脚地上了楼。"}},{"en":"to move with your body close to the ground; to move slowly on your hands and knees","cn":"匍匐行进；爬行","g":"[intransitive]","lab":"North American English"},{"en":"to move or develop very slowly","cn":"非常缓慢地行进；不知不觉产生；渐渐出现","g":"[intransitive]","ex":{"en":"Her arms crept around his neck.","cn":"她的双臂慢慢地搂住了他的脖子。"}},{"en":"to grow along the ground or up walls using long stems or roots","cn":"蔓生；蔓延","g":"[intransitive]"},{"en":"to be too friendly or helpful to somebody in authority in a way that is not sincere, especially in order to get an advantage from them","cn":"谄媚；巴结；拍马屁","g":"[intransitive]","lab":"British English, informal, disapproving，，，，","ex":{"en":"He's always creeping to the boss.","cn":"他总是偷偷摸摸地去找老板。"}},{"en":"a person that you dislike very much and find very unpleasant","cn":"讨厌鬼","g":"[countable]","lab":"informal","ex":{"en":"He's a nasty little creep!","cn":"他这小子真让人讨厌！"},"pos":"noun"},{"en":"a person who is not sincere but tries to win your approval by being nice to you","cn":"讨好卖乖的人；谄媚奉承的人；马屁精","g":"[countable]","lab":"British English, informal，，","ex":{"en":"He’s the sort of creep who would do that kind of thing!","cn":"他就是那种会做出这种事的变态！"},"pos":"noun"},{"en":"the development of a project beyond the goal that was originally agreed","cn":"（对既定目标的）偏离","g":"[uncountable]","lab":"often disapproving","ex":{"en":"The World Bank has been accused of mission creep when seeking to address these concerns.","cn":"世界银行被指控在寻求处理这些重大事务时偏离使命。"},"pos":"noun"}]}},"creed":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"信条;原则;纲领","en":"A creed is a set of beliefs, principles, or opinions that strongly influence the way people live or work.","ex":{"en":"...their devotion to their creed of self-help.","cn":"他们坚信自力更生的原则"}},{"pos":"N-COUNT 可数名词","cn":"宗教","en":"A creed is a religion.","ex":{"en":"The centre is open to all, no matter what race or creed.","cn":"该中心向所有人开放，不论种族和宗教信仰如何。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of beliefs about a god, and the ceremonies and customs that go with these beliefs. Also used when talking about all religions in general","cn":""},{"en":"a religion, especially one of the large important world religions. Also used when talking about religious belief in general","cn":""},{"en":"the act of believing in a god or gods, or the ideas that someone believes because of their religion","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Without reading the long document about the group's beliefs — its creed — he knew he didn't fit in, because he just couldn't bow to the 12-foot statue of a rabbit, no matter what it symbolized."}]},"collocations":{"phrases":["ADJ. political, religious","VERB + CREED adopt, embrace Other countries have adopted this political creed enthusiastically. | reject"]},"media":{"uk":"media/ldoce/hwd/bre/3/creed0205.mp3","us":"media/ldoce/hwd/ame/c/creed.mp3"},"examples":[{"en":"people of all races, colours and creeds","cn":"各种种族、肤色和宗教信仰的人"},{"en":"What is his political creed?","cn":"他的政治信仰是什么？"}],"oxford":{"phon":"kriːd","pos":"noun","senses":[{"en":"a set of principles or religious beliefs","cn":"信念；原则；纲领；宗教信仰","g":"[countable]","ex":{"en":"We welcome people of all races, colours and creeds.","cn":"我们欢迎所有种族、肤色和信仰的人们。"}},{"en":"a statement of Christian belief that is spoken as part of some church services","cn":"（基督教）信经","g":"[singular]"}]}},"crook":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"骗子;罪犯","en":"A crook is a dishonest person or a criminal.","ex":{"en":"The man is a crook and a liar","cn":"那人是个骗子，满嘴谎言。"}},{"pos":"N-COUNT 可数名词","cn":"(肘或膝盖的)内侧","en":"The crook of your arm or leg is the soft inside part where you bend your elbow or knee.","ex":{"en":"She hid her face in the crook of her arm.","cn":"她把脸掩在臂弯里。"}},{"pos":"VERB 动词","cn":"弯曲(手臂或手指)","en":"If you crook your arm or finger, you bend it.","ex":{"en":"He crooked his finger: 'Come forward,' he said.","cn":"他勾勾手指说：“过来。”"}},{"pos":"N-COUNT 可数名词","cn":"(主教或牧羊人用的)曲柄杖","en":"A crook is a long pole with a large hook at the end. A crook is carried by a bishop in religious ceremonies, or by a shepherd.","ex":{"en":"...a shepherd's crook.","cn":"牧羊人的曲柄杖"}},{"pos":"PHRASE 短语","cn":"想方设法;不择手段","en":"If someone says they will do something by hook or by crook, they are determined to do it, even if they have to make a great effort or use dishonest means.","ex":{"en":"They intend to get their way, by hook or by crook.","cn":"为达到目的，他们不择手段。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is involved in illegal activities or has been proved guilty of a crime. Criminal is used especially about someone who often does things that are illegal","cn":""},{"en":"someone who breaks the law","cn":""},{"en":"a dishonest person, especially one who steals money and who you cannot trust","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A crook is long staff that’s bent at one end, like something you might see a shepherd carrying. A crook can also be a criminal — a person who’s dishonest, or bent, just like the staff."}]},"collocations":{"phrases":["ADJ. small-time","VERB + CROOK catch"]},"media":{"uk":"media/ldoce/hwd/bre/c/crook_v0205.mp3","us":"media/ldoce/hwd/ame/3/crook1.mp3"},"examples":[{"en":"That salesman is a real crook.","cn":"那推销员真是个骗子。"},{"en":"The crooks got away across the park.","cn":"那些骗子穿过公园跑掉了。"}],"oxford":{"phon":"krʊk","pos":"noun","senses":[{"en":"a dishonest person","cn":"骗子","lab":"informal","ex":{"en":"That salesman is a real crook.","cn":"那推销员真是个骗子。"}},{"en":"the place where your arm bends at the elbow","cn":"臂弯；肘弯","ex":{"en":"He was carrying a gun in the crook of his arm.","cn":"他臂弯里挎着一把枪。"}},{"en":"a long stick with a hook (= a curved part) at one end, used by shepherds for catching sheep","cn":"（牧羊人捕羊用的）曲柄杖"},{"en":"to bend your finger or arm","cn":"使（手指或手臂）弯曲","ex":{"en":"She winked and crooked a finger at him.","cn":"她眨了眨眼睛，对他伸出一根手指。"},"pos":"verb"},{"en":"ill","cn":"生病；不舒服","ex":{"en":"I’m feeling a bit crook.","cn":"我感到有点不适。"},"pos":"adjective"},{"en":"bad or unpleasant","cn":"坏的；令人不愉快的","ex":{"en":"It can be hard to stay positive when times are crook.","cn":"当形势不妙时，很难保持积极的态度。"},"pos":"adjective"},{"en":"dishonest; illegal","cn":"骗子","ex":{"en":"Everybody thinks horse racing is crook anyway.","cn":"无论如何，每个人都认为赛马是骗人的。"},"pos":"adjective"}]}},"crux":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(难题或辩论的)关键，最难点，症结","en":"The crux of a problem or argument is the most important or difficult part of it which affects everything else.","ex":{"en":"He said the crux of the matter was economic policy.","cn":"他说问题的症结在于经济政策。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the most important part of a difficult problem, a question, or an argument etc that must be dealt with or understood before any further progress can be made","cn":""},{"en":"the main feature or quality that gives something its own special character","cn":""},{"en":"the most important part of a problem, consideration, question etc","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The essential point or problem is the crux . People are always trying to get to the crux of a matter or the crux of a problem, while others try to distract them."}]},"collocations":{"phrases":["CRUX + VERB lie The crux of the matter lies in our lack of expert knowledge.","PHRASES the crux of the matter/problem"]},"media":{"uk":"media/ldoce/hwd/bre/5/crux0205.mp3","us":"media/ldoce/hwd/ame/9/crux.mp3"},"examples":[{"en":"Now we come to the crux of the matter.","cn":"现在我们来谈问题的症结。"},{"en":"The crux of the matter is how do we prevent a flood occurring again?","cn":"问题的关键是我们如何预防洪水再次发生？"}],"oxford":{"phon":"krʌks","pos":"noun","senses":[{"en":"the most important or difficult part of a problem or an issue","cn":"（难题或问题的）关键，最难点，症结","ex":{"en":"Now we come to the crux of the matter.","cn":"现在我们来谈问题的症结。"}}]}},"cross-eyed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"内斜视的;对眼的;斗鸡眼的","en":"Someone who is cross-eyed has eyes that seem to look towards each other."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having eyes that both look in towards the nose","cn":"内斜视的﹐斗鸡眼的"}]},"collocations":{"phrases":["VERBS be, look | go You'll go cross-eyed if you try to look at things so close to you.","ADV. slightly"]},"media":{"uk":"media/ldoce/hwd/bre/6/cross_eyed0205.mp3","us":"media/ldoce/hwd/ame/9/cross-eyed.mp3"},"oxford":{"phon":"ˌkrɒs ˈaɪd","pos":"adjective","senses":[{"en":"having one or both eyes looking towards the nose","cn":"内斜视的；对眼的；斗鸡眼的","ex":{"en":"I’m going cross-eyed, working on those handwritten texts all day.","cn":"我会斗鸡眼，整天处理那些手写的文字。"}}]}},"cruise":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"乘船游览;航游","en":"A cruise is a holiday during which you travel on a ship or boat and visit a number of places.","ex":{"en":"He and his wife were planning to go on a world cruise","cn":"他和太太计划乘船环游世界。"}},{"pos":"VERB 动词","cn":"乘船游览;航游","en":"If you cruise a sea, river, or canal, you travel around it or along it on a cruise.","ex":{"en":"She wants to cruise the canals of France in a barge","cn":"她想乘驳船游览法国的运河。"}},{"pos":"VERB 动词","cn":"(车、船或飞机)以平稳且舒适的速度行驶，缓慢行进","en":"If a car, ship, or aircraft cruises somewhere, it moves there at a steady comfortable speed.","ex":{"en":"A black and white police car cruised past.","cn":"一辆黑白相间的警车缓慢驶过。"}},{"pos":"VERB 动词","cn":"（球队或运动员）轻而易举赢得，轻取","en":"If a team or sports player cruises to victory, they win easily.","ex":{"en":"Graf looked in awesome form as she cruised to an easy victory.","cn":"格拉芙轻松取胜，看上去状态极佳。"}},{"pos":"VERB 动词","cn":"(在公共场所，尤指男同性恋者)寻找性伙伴，猎艳","en":"If a gay man is cruising, he is searching in public places for a sexual partner.","ex":{"en":"...gay men cruising on Clapham Common.","cn":"在克拉珀姆公地寻找性伙伴的男同性恋者"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a journey by air","cn":""},{"en":"a long journey over the sea","cn":""},{"en":"a short journey by boat from one piece of land to another","cn":""}]},"vocab":{"pos":"1 v n 2 v","senses":[{"en":"If your mom announces “We’re taking a cruise !” then pack your bags. A cruise is a vacation spent on a ship that sails the ocean, periodically stopping in ports for sightseeing."}]},"collocations":{"phrases":["ADJ. leisurely, luxury, pleasure a pleasure cruise around the bay | Caribbean, Mediterranean, world, etc.","VERB + CRUISE go on, take She used all her savings to go on a world cruise.","CRUISE + NOUN liner, operator, ship","PREP. on a/the~ They met on a cruise. | ~ along a cruise along the coast | ~ around/round"]},"media":{"uk":"media/ldoce/hwd/bre/d/cruise_n0205.mp3","us":"media/ldoce/hwd/ame/b/cruise1.mp3"},"examples":[{"en":"a light aircraft cruising at 4 000 feet","cn":"一架在 4 000 英尺高度巡航的轻型飞机"},{"en":"She cruised around the block looking for a parking space.","cn":"她绕着那个街区慢慢行驶，想找个停车的地方。"}],"oxford":{"phon":"kruːz","pos":"noun","senses":[{"en":"a journey by sea, visiting different places, especially as a holiday","cn":"乘船游览；航行","lab":"British English","ex":{"en":"I'd love to go on a round-the-world cruise.","cn":"我很想乘船周游世界。"}},{"en":"to travel in a ship or boat visiting different places, especially as a holiday","cn":"乘船游览","g":"[intransitive, transitive]","ex":{"en":"They cruised down the Nile.","cn":"他们沿尼罗河而下乘船游览。"},"pos":"verb"},{"en":"to travel at a steady speed","cn":"以平稳的速度行驶","g":"[intransitive]","ex":{"en":"a light aircraft cruising at 4 000 feet","cn":"一架在 4 000 英尺高度巡航的轻型飞机"},"pos":"verb"},{"en":"to drive along slowly, especially when you are looking at or for something","cn":"（尤指查看或寻找时）慢速行驶，巡行","g":"[intransitive, transitive]","ex":{"en":"She cruised around the block looking for a parking space.","cn":"她绕着那个街区慢慢行驶，想找个停车位。"},"pos":"verb"},{"en":"to win or achieve something easily","cn":"轻而易举赢得（或获得）；轻取","g":"[intransitive]","ex":{"en":"The home team cruised to victory.","cn":"主队轻松取胜。"},"pos":"verb"},{"en":"to go around in public places looking for a sexual partner","cn":"（在公共场所）寻觅性伙伴，猎艳","g":"[intransitive, transitive]","lab":"slang","pos":"verb"}]}},"crescendo":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"逐渐增强的喧闹声;噪声的最高点","en":"A crescendo is a noise that gets louder and louder. Some people also use crescendo to refer to the point when a noise is at its loudest.","ex":{"en":"She spoke in a crescendo: 'You are a bad girl! You are a wicked girl! You are evil!'","cn":"她嗓门越来越高地说道：“你是个坏女孩！你是个妖女！你是个魔鬼！”"}},{"pos":"N-COUNT 可数名词","cn":"最大强度;渐强;顶点","en":"People sometimes describe an increase in the intensity of something, or its most intense point, as a crescendo .","ex":{"en":"There was a crescendo of parliamentary and press criticism","cn":"来自议会和新闻界的批评越来越多。"}},{"pos":"N-COUNT 可数名词","cn":"(音乐的)渐强部分，高潮","en":"In music, a crescendo is a section of a piece of music in which the music gradually gets louder and louder."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a sound or a piece of music rises to a crescendo, it gradually becomes louder until it is very loud 〔","cn":"声音的〕最高点﹔〔音乐的〕渐强﹐高潮"},{"en":"if an activity or feeling reaches a crescendo, it gradually becomes stronger until it is very strong 〔","cn":"活动或感情的〕高潮﹐顶点"}]},"vocab":{"pos":"n v adj","senses":[{"en":"In a crescendo , the music is getting louder. There's often a crescendo in a large group of talking people, too."}]},"collocations":{"phrases":["ADJ. deafening","VERB + CRESCENDO reach, rise to The music reached a deafening crescendo."]},"media":{"uk":"media/ldoce/hwd/bre/4/crescendo0205.mp3","us":"media/ldoce/hwd/ame/4/crescendo1.mp3"},"examples":[{"en":"Voices rose in a crescendo and drowned him out.","cn":"人们讲话的声音越来越大，盖过了他的声音。"},{"en":"( figurative ) The advertising campaign reached a crescendo just before Christmas.","cn":"圣诞节前夕，广告攻势达到了高潮。"}],"oxford":{"phon":"krəˈʃendəʊ","pos":"noun","senses":[{"en":"a slow steady increase in how loudly a piece of music is played or sung","cn":"（音乐的）渐强","lab":"music, from Italian，，"},{"en":"a slow steady increase in noise; the loudest point of a period of continuous noise","cn":"逐渐增强的喧闹声；持续噪声的最高点","lab":"figurative","ex":{"en":"Voices rose in a crescendo and drowned him out.","cn":"人们讲话的声音越来越大，盖过了他的声音。"}}]}},"cramp":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"痛性痉挛;抽筋","en":"Cramp is a sudden strong pain caused by a muscle suddenly contracting. You sometimes get cramp in a muscle after you have been making a physical effort over a long period of time.","ex":{"en":"Hillsden was complaining of cramp in his calf muscles","cn":"希尔斯登说他小腿抽筋。"}},{"pos":"PHRASE 短语","cn":"束缚…的手脚;使不能放开手脚","en":"If someone or something cramps your style, their presence or existence restricts your behaviour in some way.","ex":{"en":"Like more and more women, she believes marriage would cramp her style.","cn":"像越来越多的女性一样，她认为婚姻会对她形成束缚。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a severe pain that you get in part of your body when a muscle becomes too tight, making it difficult for you to move that part of your body","cn":"痛性痉挛﹔痉挛﹐抽筋"},{"en":"severe pains in the stomach, especially the ones that women get when they menstruate 〔","cn":"尤指女性经期的〕（腹部）绞痛"},{"en":"to prevent the development of someone or something","cn":"限制﹐束缚〔某人或某事物的发展〕"}]},"collocations":{"phrases":["ADJ. agonizing, painful | sudden She had a sudden painful cramp in her left leg. | abdominal, stomach","QUANT. attack I was suddenly seized by an attack of cramp.","VERB + CRAMP have"]},"media":{"uk":"media/ldoce/hwd/bre/9/cramp_n0205.mp3","us":"media/ldoce/hwd/ame/7/cramp1.mp3"},"examples":[{"en":"Tighter trade restrictions might cramp economic growth.","cn":"较严格的贸易限制会妨碍经济的增长。"},{"en":"( BrE ) to get cramp in your leg","cn":"腿部抽筋"}],"oxford":{"phon":"kræmp","pos":"noun","senses":[{"en":"a sudden pain that you get when the muscles in a particular part of your body contract, usually caused by cold or too much exercise","cn":"痛性痉挛；抽筋","g":"[uncountable, countable]","lab":"British English","ex":{"en":"to get cramp in your leg","cn":"腿部抽筋"}},{"en":"severe pain in the stomach","cn":"（腹部）绞痛","g":"[plural]"},{"en":"to prevent the development or progress of somebody/something","cn":"阻碍，阻止（发展或进步）","ex":{"en":"Tighter trade restrictions might cramp economic growth.","cn":"较严格的贸易限制会妨碍经济的增长。"},"pos":"verb"}]}},"crutch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(腿或脚受伤的人用的)腋杖，拐杖","en":"A crutch is a stick whose top fits round or under the user's arm, which someone with an injured foot or leg uses to support their weight when walking.","ex":{"en":"I can walk without the aid of crutches","cn":"我不用拐杖也能自己走。"}},{"pos":"N-SING 单数名词","cn":"依靠;依赖","en":"If you refer to someone or something as a crutch, you mean that they give you help or support.","ex":{"en":"The calculator is a tool, not a crutch; yet it is increasingly being used as a crutch by many children","cn":"计算器是工具，不是拐杖，可是现在很多孩子越来越依赖它。"}},{"pos":"N-COUNT 可数名词","cn":"同 crotch","en":"Your crutch is the same as your crotch .","ex":{"en":"He kicked him in the crutch.","cn":"他踢了他的裆部。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of a pair of long sticks that you put under your arms to help you walk when you have hurt your leg 〔","cn":"放在腋下用的〕拐杖﹐腋杖"},{"en":"something that gives someone support or help, especially something that is not really good for them 〔","cn":"尤指无益的〕支撑，依靠"},{"en":"the part of your body between the tops of your legs","cn":"胯部"}]},"collocations":{"phrases":["ADJ. emotional, psychological (both figurative) He saw religion as a psychological crutch.","VERB + CRUTCH need, use He needs crutches to walk.","PREP. on/with ~ She can only walk with crutches."]},"media":{"img":["media/ldoce/img/crutches.jpg"],"uk":"media/ldoce/hwd/bre/c/crutch0205.mp3","us":"media/ldoce/hwd/ame/2/crutch.mp3"},"examples":[{"en":"After the accident I spent six months on crutches.","cn":"事故后我用了六个月的腋杖。"},{"en":"I was on crutches for three months after the operation.","cn":"手术后我拄了三个月的拐杖。"}],"oxford":{"phon":"krʌtʃ","pos":"noun","senses":[{"en":"one of two long sticks that you put under your arms to help you walk after you have injured your leg or foot","cn":"（腿或脚受伤者用的）腋杖","ex":{"en":"After the accident I spent six months on crutches.","cn":"事故后我用了六个月的腋杖。"}},{"en":"a person or thing that gives you help or support but often makes you depend on them too much","cn":"依靠；依赖","lab":"usually disapproving","ex":{"en":"High interest rates are merely a crutch for the country’s ailing economy.","cn":"高利率只是该国疲弱经济的一根拐杖。"}},{"en":"the part of the body where the legs join at the top, including the area around the genitals","cn":"（人体的）胯部，两腿分叉处"},{"en":"the part of a pair of trousers, etc. that covers the crotch","cn":"裤裆"}]}},"creak":{"collins":{"senses":[{"pos":"VERB 动词","cn":"嘎吱作响","en":"If something creaks, it makes a short, high-pitched sound when it moves.","ex":{"en":"The bed-springs creaked","cn":"床垫的弹簧嘎吱作响。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"a very short high sound or cry","cn":""},{"en":"a long high sound that something makes when someone opens it, walks on it, sits on it etc – used especially about a door, wooden floor, bed, or stairs","cn":""},{"en":"a loud, long, unpleasantly high sound – used especially about someone’s voice, or about brakes, tyres etc","cn":""}]},"collocations":{"phrases":["ADV. slightly","PREP. under The chair creaked under his weight.","PHRASES creak and groan The ice creaked and groaned underfoot. | creak open The door creaked open an inch."]},"media":{"uk":"media/ldoce/hwd/bre/1/creak0205.mp3","us":"media/ldoce/hwd/ame/0/creak.mp3"},"examples":[{"en":"Distant creaks and groans echoed eerily along the dark corridors.","cn":"远处嘎吱嘎吱的声音回响在漆黑的走廊里，怪可怕的。"},{"en":"She heard a floorboard creak upstairs.","cn":"她听见楼上的地板发出嘎吱嘎吱的响声。"}],"oxford":{"phon":"kriːk","pos":"verb","senses":[{"en":"to make the sound that a door sometimes makes when you open it or that a wooden floor sometimes makes when you step on it","cn":"嘎吱作响（开门或踩上木地板等时发出的声音）","ex":{"en":"She heard a floorboard creak upstairs.","cn":"她听见楼上的地板发出嘎吱嘎吱的响声。"}},{"en":"a sound, for example that sometimes made by a door when it opens or shuts, or by a wooden floor when you step on it","cn":"嘎吱声","ex":{"en":"the creak/creaking of the door","cn":"门的嘎吱声"},"pos":"noun"}]}},"crouch":{"collins":{"senses":[{"pos":"VERB 动词","cn":"蹲;蹲伏","en":"If you are crouching, your legs are bent under you so that you are close to the ground and leaning forward slightly.","ex":{"en":"We were crouching in the bushes","cn":"我们蹲在树丛里。"}},{"pos":"VERB 动词","cn":"俯身接近","en":"If you crouch over something, you bend over it so that you are very near to it.","ex":{"en":"Meantime, here I crouch over a cup of tea in my unheated study.","cn":"与此同时，在没有暖气的书房里，我只能就着一杯茶取暖。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move your body forwards or move it downwards, so that you can lift something, touch something etc","cn":""},{"en":"to bend your body from the waist, usually in order to pick something up","cn":""},{"en":"to bend your body low enough to pick something up, touch the floor etc","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"To crouch is to bend your knees, pull your body in, and sit on your heels. This position is called a crouch . You might crouch down to pet a kitten or catch a baseball."}]},"collocations":{"phrases":["ADV. low The hare crouches low on the ground. | down We crouched down to avoid being seen.","PREP. behind crouching behind the sofa | over They crouched over the dead animal."]},"media":{"uk":"media/ldoce/hwd/bre/d/crouch0205.mp3","us":"media/ldoce/hwd/ame/3/crouch.mp3"},"examples":[{"en":"He crouched down beside her.","cn":"他在她的旁边蹲了下来。"},{"en":"He crouched over the papers on his desk.","cn":"他俯身看他桌上的文件。"}],"oxford":{"phon":"kraʊtʃ","pos":"verb","senses":[{"en":"to put your body close to the ground by bending your legs under you","cn":"蹲；蹲下；蹲伏","ex":{"en":"He crouched down beside her.","cn":"他在她的旁边蹲了下来。"}},{"en":"a crouching position","cn":"蹲着的姿势","ex":{"en":"She dropped to a crouch.","cn":"她俯身蹲了下来。"},"pos":"noun"}]}},"crater":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(撞击或爆炸形成的)坑，弹坑","en":"A crater is a very large hole in the ground, which has been caused by something hitting it or by an explosion."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an empty space in the surface of something, which sometimes goes all the way through it","cn":""},{"en":"an empty area between two things, into which you can put something","cn":""},{"en":"an empty area between two things or two parts of something, especially one that should not be there","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A crater is a roundish dent left in the surface of something by the impact of something else. Look at the moon: it's covered in craters from thousands of impacts over millions of years."}]},"collocations":{"phrases":["ADJ. deep, gaping, huge, large The blast blew a gaping crater in the road. | shallow, small | bomb, shell | meteor | volcanic | lunar","VERB + CRATER blow, form, leave, make","PREP. in a/the ~","PHRASES the edge/lip/side of a crater We peered over the lip of the crater into the volcano."]},"media":{"uk":"media/ldoce/hwd/bre/0/crater0205.mp3","us":"media/ldoce/hwd/ame/b/crater.mp3"},"examples":[{"en":"a meteorite crater","cn":"陨石坑"},{"en":"craters on the Moon’s surface","cn":"月球表面的坑"}],"oxford":{"phon":"ˈkreɪtə(r)","pos":"noun","senses":[{"en":"a large hole in the top of a volcano","cn":"火山口","ex":{"en":"We peered over the lip of the crater into the volcano.","cn":"我们在火山口边缘观察火山。"}},{"en":"a large hole in the ground caused by the explosion of a bomb or by something large hitting it","cn":"（由炸弹爆炸或巨物撞击形成的）坑","ex":{"en":"a meteorite crater","cn":"陨石坑"}}]}},"creepy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人紧张不安的;令人毛骨悚然的","en":"If you say that something or someone is creepy, you mean they make you feel very nervous or frightened.","ex":{"en":"There were certain places that were really creepy at night","cn":"有些地方晚上真是让人不寒而栗。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel frightened","cn":""},{"en":"frightening. Scary is less formal than frightening and is very common in everyday English","cn":""},{"en":"frightening, especially because violence, cruelty, or danger is involved","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look, seem It feels a bit creepy in here. | get It can get pretty creepy in the cellar at night.","ADV. a bit, pretty, slightly"]},"media":{"uk":"media/ldoce/hwd/bre/f/creepy0205.mp3","us":"media/ldoce/hwd/ame/e/creepy.mp3"},"examples":[{"en":"It's kind of creepy down in the cellar!","cn":"地窖里真令人有点不寒而栗！"},{"en":"What a creepy coincidence.","cn":"多么离奇的巧合。"}],"oxford":{"phon":"ˈkriːpi","pos":"adjective","senses":[{"en":"causing an unpleasant feeling of fear or slight horror","cn":"令人毛骨悚然的；令人不寒而栗的","ex":{"en":"a creepy ghost story","cn":"令人毛骨悚然的鬼故事"}},{"en":"strange in a way that makes you feel nervous","cn":"怪异的，离奇的（使人感到紧张）","ex":{"en":"What a creepy coincidence.","cn":"多么离奇的巧合。"}}]}},"credible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可信的;可靠的","en":"Credible means able to be trusted or believed.","ex":{"en":"Baroness Thatcher's claims seem credible to many","cn":"撒切尔女男爵的主张在很多人看来是可信的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(候选人、政策、体系等)有望成功的","en":"A credible candidate, policy, or system, for example, is one that appears to have a chance of being successful.","ex":{"en":"Mr Robertson would be a credible candidate","cn":"罗伯逊先生将是可能当选的候选人之一。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a story, explanation etc is believable , you can believe it because it seems possible or likely","cn":""},{"en":"a convincing explanation, argument, reason etc seems likely to be true","cn":""},{"en":"something that is plausible seems reasonable and likely to be true, even though it may actually be untrue - use this especially about an explanation, excuse, or idea","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Someone who's credible is honest and believable. A pathological liar, for example, might not be the most credible witness for your case against the bank robber."}]},"collocations":{"phrases":["VERBS appear, be, seem | become | make sth | find sth I'm not sure that I find her story credible.","ADV. highly, very | completely, fully, quite You need imagination to make what you write fully credible. | barely, hardly, scarcely It seems"]},"media":{"uk":"media/ldoce/hwd/bre/3/credible0205.mp3","us":"media/ldoce/hwd/ame/4/credible.mp3"},"examples":[{"en":"We can credibly describe the band's latest album as their best yet.","cn":"我们完全可以说，这支乐队的最新专辑是他们迄今的最佳作品。"},{"en":"Community service is seen as the only credible alternative to imprisonment.","cn":"除监禁外，社区劳动被看作是唯一可接受的选择。"}],"oxford":{"phon":"ˈkredəbl","pos":"adjective","senses":[{"en":"that can be believed or trusted","cn":"可信的；可靠的","ex":{"en":"a credible explanation/witness","cn":"可信的解释／证人"}},{"en":"that can be accepted, because it seems possible that it could be successful","cn":"（因看似可能成功而）可接受的","ex":{"en":"Community service is seen as the only credible alternative to imprisonment.","cn":"除监禁外，社区劳动被看作是唯一可接受的选择。"}}]}},"craftsmanship":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"手艺;技艺","en":"Craftsmanship is the skill that someone uses when they make beautiful things with their hands.","ex":{"en":"It is easy to appreciate the craftsmanship of Armani.","cn":"阿玛尼的精致工艺很容易博得人们的赞誉。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"精工细作","en":"Craftsmanship is the quality that something has when it is beautiful and has been very carefully made.","ex":{"en":"His canoes are known for their style, fine detail and craftsmanship.","cn":"他的独木舟以其风格独特、注重细节和做工精细著称。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to do something well especially because you have learned and practised it","cn":""},{"en":"the ability to do something well, either because you have learned how to do it or because you are naturally good at it","cn":""},{"en":"a natural ability to do something very well","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Craftsmanship is what skilled artists and builders demonstrate when they create something."}]},"collocations":{"phrases":["ADJ. exquisite, fine, skilled, superb We admired the superb craftsmanship of the furniture.","PREP. with ~ bowls made with exquisite craftsmanship","PHRASES standard of craftsmanship a very high standard of craftsmanship"]},"media":{"uk":"media/ldoce/hwd/bre/e/craftsmanship0205.mp3","us":"media/ldoce/hwd/ame/3/laadcraftsmanship.mp3"},"examples":[{"en":"The whole house is a monument to her craftsmanship.","cn":"那整座房子是她技艺的一座丰碑。"},{"en":"the superb craftsmanship of the carvings","cn":"这些雕刻品的一流工艺"}],"oxford":{"phon":"ˈkrɑːftsmənʃɪp","pos":"noun","senses":[{"en":"the level of skill shown by somebody in making something beautiful with their hands","cn":"手艺；技艺","ex":{"en":"The whole house is a monument to her craftsmanship.","cn":"那整座房子是她技艺的一座丰碑。"}},{"en":"the quality of design and work shown by something that has been made by hand","cn":"工艺质量","ex":{"en":"the superb craftsmanship of the carvings","cn":"这些雕刻品的一流工艺"}}]}},"crane":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"起重机;吊车","en":"A crane is a large machine that moves heavy things by lifting them in the air.","ex":{"en":"The little prefabricated hut was lifted away by a huge crane.","cn":"那间用预制板搭建的小棚屋被一辆大型起重机吊走了。"}},{"pos":"N-COUNT 可数名词","cn":"鹤","en":"A crane is a kind of large bird with a long neck and long legs."},{"pos":"VERB 动词","cn":"(为看或听得更清楚)伸长(脖子)，探(头)","en":"If you crane your neck or head, you stretch your neck in a particular direction in order to see or hear something better.","ex":{"en":"She craned her neck to get a better view","cn":"她伸长脖子想看得更清楚些。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large tall machine used by builders for lifting heavy things","cn":"起重机﹐吊车"},{"en":"a tall water bird with very long legs","cn":"鹤"},{"en":"to look around or over something by stretching or leaning","cn":"伸长（脖子）看﹔探头看﹔倾身看"}]},"media":{"img":["media/ldoce/img/crane.jpg"],"uk":"media/ldoce/hwd/bre/3/crane_v0205.mp3","us":"media/ldoce/hwd/ame/0/crane1.mp3"},"examples":[{"en":"She craned her neck to get a better view of the stage.","cn":"她伸长了脖子看舞台，好看清楚些。"},{"en":"People were craning out of the windows and waving.","cn":"人们把头探出窗外挥手致意。"}],"oxford":{"phon":"kreɪn","pos":"noun","senses":[{"en":"a tall machine with a long arm, used to lift and move building materials and other heavy objects","cn":"起重机；吊车"},{"en":"a large bird with long legs and a long neck","cn":"鹤"},{"en":"to lean or stretch over something in order to see something better; to stretch your neck","cn":"（为看得更清楚而）探着身子；伸长（脖子）","ex":{"en":"People were craning out of the windows and waving.","cn":"人们把头探出窗外挥手致意。"},"pos":"verb"}]}}});
